  status_is_pko: boolean | null;
  /** TRUE when the version holds a status PKO does not define. */
  uses_non_pko_status: boolean | null;
  /** Documented exceptions. */
  exception_count: number | null;
  /** Fallback transitions. */
  fallback_transition_count: number | null;
  /** Alternative transitions. */
  alternative_transition_count: number | null;
  /** TRUE when a version with steps captures only the normative path: no exception, fallback or alternative. */
