// =============================================================================
// PROCEDUREVERSIONLINKS TABLE
// Directed links between versioned procedures. Maps to dcat:previousVersion/dcat:hasVersion and pko:nextVersion.
// =============================================================================

/** A row in the ProcedureVersionLinks table. */
export interface ProcedureVersionLinksRow {
  /** Stored logical identifier for one ProcedureVersionLinks row. */
  procedure_version_link_id: string;
  /** Human-readable calculated display alias for the ProcedureVersionLinks row. */
  name: string | null;
  /** Earlier version. */
  previous_procedure_version: string | null;
  /** Later version. */
  next_procedure_version: string | null;
  /** Exact version relation IRI. */
  relation_iri: string | null;
  /** Summary of semantic change across the edge. */
  change_summary: string | null;
  /** Echoes the superseded (previous) version id for rows that express a next-version relation. Supersession is carried by RelationIri here, not by a separate link-kind column. */
  superseded_version_key: string | null;
  _erb_errors?: Record<string, string>;
}

const procedureVersionLinksFieldTypes: Record<string, FieldType> = {
  procedure_version_link_id: "string",
  name: "*string",
  previous_procedure_version: "*string",
  next_procedure_version: "*string",
  relation_iri: "*string",
  change_summary: "*string",
  superseded_version_key: "*string",
};

/** Computes the Name calculated field.
 *  Human-readable calculated display alias for the ProcedureVersionLinks row.
 *  Formula: ={{PreviousProcedureVersion}} & " -> " & {{NextProcedureVersion}} */
export function calcProcedureVersionLinksName(tc: ProcedureVersionLinksRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.previous_procedure_version)), vS(" -> "), erbText(vStr(tc.next_procedure_version))));
}

/** Computes the SupersededVersionKey calculated field.
 *  Echoes the superseded (previous) version id for rows that express a next-version relation. Supersession is carried by RelationIri here, not by a separate link-kind column.
 *  Formula: =IF({{RelationIri}} = "https://w3id.org/pko#nextVersion", {{PreviousProcedureVersion}}, "") */
export function calcProcedureVersionLinksSupersededVersionKey(tc: ProcedureVersionLinksRow): string | null {
  return toStringPtr(erbIf(erbBool3(erbEq(erbNullif(vStr(tc.relation_iri)), vS("https://w3id.org/pko#nextVersion"))), () => vStr(tc.previous_procedure_version), () => vS("")));
}

/** Computes every calculated field of the row in dependency order. */
export function computeProcedureVersionLinks(tc: ProcedureVersionLinksRow): ProcedureVersionLinksRow {
  // Level 1
  calcGuard(tc, procedureVersionLinksFieldTypes, "name", () => { tc.name = calcProcedureVersionLinksName(tc); });
  calcGuard(tc, procedureVersionLinksFieldTypes, "superseded_version_key", () => { tc.superseded_version_key = calcProcedureVersionLinksSupersededVersionKey(tc); });
  return tc;
}

/** Reads ProcedureVersionLinks rows from a JSON array file. */
export function loadProcedureVersionLinksRows(file: string): ProcedureVersionLinksRow[] {
  return loadRows(file, { fields: procedureVersionLinksFieldTypes }) as unknown as ProcedureVersionLinksRow[];
}

// =============================================================================
// PROCEDURESTATUSCHANGES TABLE
// Lifecycle events that move a procedure version between PKO statuses. Maps to pko:ChangeOfStatus, fromStatus, toStatus, and prov:atTime.
// =============================================================================

/** A row in the ProcedureStatusChanges table. */
export interface ProcedureStatusChangesRow {
  /** Stored logical identifier for one ProcedureStatusChanges row. */
  procedure_status_change_id: string;
  /** Human-readable calculated display alias for the ProcedureStatusChanges row. */
  name: string | null;
  /** Procedure version whose status changed. */
  procedure_version: string | null;
  /** Previous PKO status. */
  from_status: string | null;
  /** New PKO status. */
  to_status: string | null;
  /** Time of change; maps to prov:atTime. */
  changed_at: string | null;
  /** Agent responsible for the change. */
  changed_by_agent: string | null;
  /** Reason for changing status. */
  motivation: string | null;
  /** Exact PKO class IRI. */
  semantic_type_iri: string | null;
  /** Create, Modify, Extract, Validate, Approve or Archive. */
  change_kind: string | null;
  /** Execution the change applies to, when it is not a version change. */
  procedure_execution: string | null;
  /** TRUE when nobody is recorded as making the change. */
  is_unattributed_change: boolean | null;
  /** TRUE when the kind of change does not match the status it moved to. */
  change_kind_contradicts_target: boolean | null;
  _erb_errors?: Record<string, string>;
}

const procedureStatusChangesFieldTypes: Record<string, FieldType> = {
  procedure_status_change_id: "string",
  name: "*string",
  procedure_version: "*string",
  from_status: "*string",
  to_status: "*string",
  changed_at: "*string",
  changed_by_agent: "*string",
  motivation: "*string",
  semantic_type_iri: "*string",
  change_kind: "*string",
  procedure_execution: "*string",
  is_unattributed_change: "*bool",
  change_kind_contradicts_target: "*bool",
};

/** Computes the Name calculated field.
 *  Human-readable calculated display alias for the ProcedureStatusChanges row.
 *  Formula: ={{ProcedureVersion}} & ": " & {{FromStatus}} & " -> " & {{ToStatus}} */
export function calcProcedureStatusChangesName(tc: ProcedureStatusChangesRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.procedure_version)), vS(": "), erbText(vStr(tc.from_status)), vS(" -> "), erbText(vStr(tc.to_status))));
}

/** Computes the IsUnattributedChange calculated field.
 *  TRUE when nobody is recorded as making the change.
 *  Formula: ={{ChangedByAgent}} = "" */
export function calcProcedureStatusChangesIsUnattributedChange(tc: ProcedureStatusChangesRow): boolean | null {
  return toBoolPtr(erbIsBlank(vStr(tc.changed_by_agent)));
}

/** Computes the ChangeKindContradictsTarget calculated field.
 *  TRUE when the kind of change does not match the status it moved to.
 *  Formula: =OR(AND({{ChangeKind}} = "Approve", {{ToStatus}} <> "Approved"), AND({{ChangeKind}} = "Validate", {{ToStatus}} <> "Validation"), AND({{ChangeKind}} = "Archive", {{ToStatus}} <> "Archived", {{ToStatus}} <> "Deprecated")) */
export function calcProcedureStatusChangesChangeKindContradictsTarget(tc: ProcedureStatusChangesRow): boolean | null {
  return toBoolPtr(erbOr(erbBool3(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.change_kind)), vS("Approve"))), erbBool3(erbNe(erbNullif(vStr(tc.to_status)), vS("Approved"))))), erbBool3(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.change_kind)), vS("Validate"))), erbBool3(erbNe(erbNullif(vStr(tc.to_status)), vS("Validation"))))), erbBool3(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.change_kind)), vS("Archive"))), erbBool3(erbNe(erbNullif(vStr(tc.to_status)), vS("Archived"))), erbBool3(erbNe(erbNullif(vStr(tc.to_status)), vS("Deprecated")))))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeProcedureStatusChanges(tc: ProcedureStatusChangesRow): ProcedureStatusChangesRow {
  // Level 1
  calcGuard(tc, procedureStatusChangesFieldTypes, "name", () => { tc.name = calcProcedureStatusChangesName(tc); });
  calcGuard(tc, procedureStatusChangesFieldTypes, "is_unattributed_change", () => { tc.is_unattributed_change = calcProcedureStatusChangesIsUnattributedChange(tc); });
  calcGuard(tc, procedureStatusChangesFieldTypes, "change_kind_contradicts_target", () => { tc.change_kind_contradicts_target = calcProcedureStatusChangesChangeKindContradictsTarget(tc); });
  return tc;
}

/** Reads ProcedureStatusChanges rows from a JSON array file. */
export function loadProcedureStatusChangesRows(file: string): ProcedureStatusChangesRow[] {
  return loadRows(file, { fields: procedureStatusChangesFieldTypes }) as unknown as ProcedureStatusChangesRow[];
}

// =============================================================================
// STEPS TABLE
// Version-scoped units of work. Atomic steps map to pplan:Step; composite steps map to pplan:MultiStep. The specification is never conflated with execution.
// =============================================================================

/** A row in the Steps table. */
export interface StepsRow {
  /** Stored logical identifier for one Steps row. */
  step_id: string;
  /** Human-readable calculated display alias for the Steps row. */
  name: string | null;
  /** Procedure version containing the step; maps to pko:hasStep/pplan:isStepOfPlan. */
  procedure_version: string | null;
  /** Stable sequence label; maps to pko:stepNumber. */
  step_number: string | null;
  /** Human-readable step title. */
  title: string | null;
  /** Atomic or MultiStep. */
  step_kind: string | null;
  /** Role responsible for the step. */
  assigned_role: string | null;
  /** Resolved role label. */
  assigned_role_label: string | null;
  /** Current role-filler category. */
  assigned_agent_kind: string | null;
  /** Normative step instruction. */
  instruction: string | null;
  /** Expected duration represented as an OWL-Time duration in semantic projections. */
  expected_duration_minutes: number | null;
  /** PKO expertise level: Junior, Senior, Expert, or Master. */
  expertise_level: string | null;
  /** TRUE when a human must confirm the step; maps to pko:wasConfirmedBy at execution. */
  requires_human_confirmation: boolean | null;
  /** How many blocking requirements the specification attaches to this step. */
  blocking_requirement_count: number | null;
  /** How many operational bindings for this step are currently outside their freshness SLA. */
  stale_binding_count: number | null;
  /** How many authoritative bindings for this step are currently stale. */
  authoritative_stale_count: number | null;
  /** How many active exceptions the specification defines for this step. */
  available_exception_count: number | null;
  /** How many verifications the specification declares for this step. */
  declared_verification_count: number | null;
  /** TRUE for steps whose assigned role produces the work product rather than reviewing it. */
  is_preparation_step: boolean | null;
  /** TRUE for steps whose assigned role is an approval authority. */
  is_approval_step: boolean | null;
  /** Number of authoritative bindings for this step that are past their freshness SLA. */
  stale_authoritative_binding_count: number | null;
  /** TRUE when no authoritative binding for this step is stale. */
  inputs_are_fresh: boolean | null;
  /** TRUE when this step is specified to be performed by software rather than a person. */
  is_software_assigned: boolean | null;
  /** TRUE for the steps that exist specifically to place a human commitment between drafting and delivery. */
  is_human_approval_gate: boolean | null;
  /** TRUE when a designated approval gate is in fact assigned to a human role. */
  gate_held_by_human: boolean | null;
  /** Number of authority boundaries currently binding at this step. */
  binding_boundary_count: number | null;
  /** Whether this step's assigned role is a non-human role with no governing assignment. */
  assigned_role_is_ungoverned: boolean | null;
  /** Number of bindings at this step that are unapproved or stale. */
  unusable_binding_count: number | null;
  /** TRUE when every binding at this step is an approved, fresh source. */
  all_sources_usable: boolean | null;
  /** What kind of control this step is: Preparation, Approval, LegalReview, Verification, Extraction, Publication, Retrospective, or None. That policy-04 is a legal review is a property OF policy-04, not of a formula that happens to name it; storing it as data makes downstream predicates portable to procedures that do not exist yet. */
  control_kind: string | null;
  /** How many boundaries governing this step are being enforced without a valid ratifying claim. */
  unwarranted_boundary_count: number | null;
  /** Whether this step's constraints on machine authority rest on a claim that is no longer valid. */
  is_governed_by_unwarranted_boundary: boolean | null;
  /** How many times a software agent has actually executed this step. */
  software_execution_count: number | null;
  /** Whether any software agent has ever executed this step. */
  has_been_approached_by_software: boolean | null;
  /** A human-only approval gate that no software agent has ever attempted — the control is asserted, not demonstrated. */
  is_unexercised_human_gate: boolean | null;
  /** A human gate that software has actually reached and that a human nevertheless held. */
  is_demonstrated_human_gate: boolean | null;
  /** Composite-key echo: this step's procedure version when the step is an unexercised human gate, blank otherwise. */
  unexercised_gate_version_key: string | null;
  /** Whether this step declares what kind of control it is. */
  has_declared_control_kind: boolean | null;
  /** Composite-key echo: this step's procedure version when the step has no declared control kind, blank otherwise. */
  undeclared_control_version_key: string | null;
  /** An approval-kind step whose assigned role is currently held by an AI agent or automated pipeline. */
  approval_step_is_software_assigned: boolean | null;
  /** How many blocking controls bound to this step have no computed witness. */
  unwitnessed_blocking_count: number | null;
  /** Number of steps this step can lead to through one or more transitions, including itself when it lies on a rework loop. */
  reachable_step_count: number | null;
  /** Number of steps that can lead to this step through one or more transitions, including itself when it lies on a rework loop. */
  reached_from_step_count: number | null;
  /** 1 when the closure contains the pair (this step, this step), i.e. some path of one or more transitions returns to this step; otherwise 0. */
  self_reach_count: number | null;
  /** The procedure can send work back to this step after it has run: the step lies on a cycle of the step graph. */
  is_on_rework_loop: boolean | null;
  /** A step carrying at least one blocking requirement can be re-entered, so that control must hold on every pass, not only the first. */
  is_blocking_control_on_rework_loop: boolean | null;
  /** Number of transitions, of any kind, that lead into this step. */
  incoming_transition_count: number | null;
  /** No transition leads into this step: the procedure version starts here. */
  is_entry_step: boolean | null;
  /** Composite-key echo: this step's id when it is its procedure version's entry step, blank otherwise. */
  entry_step_key: string | null;
  /** The entry step of this step's procedure version. */
  version_entry_step_id: string | null;
  /** 1 when some route of one or more gate-free transitions leads from the procedure version's entry step to this step; otherwise 0. */
  gate_free_reach_from_entry_count: number | null;
  /** Work can arrive at this step from the start of the procedure without passing any human approval gate. */
  is_reachable_from_entry_without_human_gate: boolean | null;
  /** A publication step the procedure can reach without human sign-off: the approval gate is structurally bypassable. */
  is_gate_bypassed_publication: boolean | null;
  /** Exact P-Plan class IRI. */
  semantic_type_iri: string | null;
  /** The multi-step this step sits in (pko:isStepOfMultiStep). */
  parent_step: string | null;
  /** For a multi-step, its first sub-step (pko:hasFirstStep). */
  first_child_step: string | null;
  /** For a verification step, the step it checks (pko:isStepVerificationOf). */
  verifies_step: string | null;
  /** Error this step remedies (pko:addressesError). */
  remedy_for_error: string | null;
  /** Sub-procedure this step invokes. */
  calls_procedure: string | null;
  /** Energy source this step isolates. */
  isolates_energy_source: string | null;
  /** Step whose completion this step requires first (the requires relation). */
  prerequisite_step: string | null;
  /** Minimum times the step runs in one execution (pko:minRepetitions). */
  min_repetitions: number | null;
  /** Maximum times the step may run in one execution (pko:maxRepetitions). */
  max_repetitions: number | null;
  /** Longer description of the step (dct:description). */
  description: string | null;
  /** Sub-steps of this step. */
  child_step_count: number | null;
  /** Kind of the parent step. */
  parent_step_kind: string | null;
  /** TRUE for a step declared MultiStep that has no sub-steps. */
  is_composite_without_children: boolean | null;
  /** Preconditions. */
  precondition_count: number | null;
  /** Postconditions. */
  postcondition_count: number | null;
  /** Invariants. */
  invariant_count: number | null;
  /** Safety-critical conditions. */
  safety_critical_condition_count: number | null;
  /** Documented failure modes. */
  failure_mode_count: number | null;
  /** Cues a practitioner reads during the step. */
  cue_count: number | null;
  /** Danger cues that call for escalation. */
  danger_cue_count: number | null;
  /** Decision points. */
  decision_point_count: number | null;
  /** Knowledge fragments attached to the step. */
  knowledge_fragment_count: number | null;
  /** TRUE for a step that carries only its one-line instruction: no condition, cue, failure mode, decision or captured knowledge. */
  has_instruction_only: boolean | null;
  /** Declared input variables. */
  input_variable_count: number | null;
  /** Declared output variables (what the step produces). */
  output_variable_count: number | null;
  /** Locks the step requires. */
  required_lock_count: number | null;
  /** Protective equipment the step requires. */
  required_protective_equipment_count: number | null;
  /** TRUE when a step isolates an energy source but requires no lock to hold the isolation. */
  is_isolation_without_lock: boolean | null;
  /** Resources the step references. */
  referenced_resource_count: number | null;
  /** Version key for a step with no ontology type. */
  untyped_version_key: string | null;
  /** TRUE when the role accountable for the step is held by software or an AI agent. */
  is_accountable_to_software: boolean | null;
  /** TRUE when any step follows this one anywhere along the ordering chain. */
  has_downstream_steps: boolean | null;
  /** Cues that show the step did not fully take effect. */
  incompleteness_cue_count: number | null;
  /** TRUE when the step documents a cue that shows it did not fully take effect. */
  has_incompleteness_cue: boolean | null;
  /** TRUE when the step states what must hold after it. */
  has_postcondition: boolean | null;
  /** Agent currently holding the step's role. */
  accountable_agent: string | null;
  /** TRUE when nobody currently holds the role accountable for the step. */
  has_no_accountable_agent: boolean | null;
  /** Version key for a step with no precondition. */
  conditionless_version_key: string | null;
  /** Closure pairs showing the step's prerequisite comes after it in the specified order. */
  prerequisite_downstream_count: number | null;
  /** TRUE when the specification orders a step before the step it requires, so following the order is unsafe. */
  prerequisite_is_downstream: boolean | null;
  /** TRUE when the step states all three things the operational level needs: what it follows, what it depends on, and what must hold first. */
  states_operational_knowledge: boolean | null;
  /** Resources allocated to the step whose demand exceeds capacity. */
  bottleneck_allocation_count: number | null;
  /** TRUE when the step waits on a resource whose demand exceeds its capacity. */
  is_bottleneck_step: boolean | null;
  /** Stage the step is grouped in. */
  stage: string | null;
  /** Activity (bundles many actions), Task, or Action (a single physical or system action). */
  detail_level: string | null;
  /** Version key for a top-level step at Activity detail. */
  coarse_top_level_version_key: string | null;
  /** Version key for a top-level step at Action detail. */
  fine_top_level_version_key: string | null;
  /** Recorded ways the step's significance depends on context. */
  context_sensitivity_count: number | null;
  /** Context dependencies with no applicability scope. */
  unscoped_sensitivity_count: number | null;
  /** TRUE when the step's significance depends on context and some such dependency says nowhere where it holds. */
  is_context_sensitive_but_unscoped: boolean | null;
  /** Procedure the step's version belongs to. */
  version_procedure: string | null;
  /** Whether the step's role carries the compliance-review capability. */
  assigned_role_does_compliance_review: boolean | null;
  /** Procedure key for a step performed by a compliance-review role. */
  compliance_review_procedure_key: string | null;
  /** Procedure type of the step's version. */
  step_procedure_type: string | null;
  /** TRUE for an approval gate in a software release procedure. */
  is_release_approval_gate: boolean | null;
  /** Requirements on the step that a regulation imposes. */
  regulatory_requirement_count: number | null;
  /** Functions an agent may invoke at the step. */
  tool_function_count: number | null;
  /** Conditions stored as machine-parseable expressions. */
  parseable_condition_count: number | null;
  /** Decision points encoded as DMN decisions. */
  dmn_decision_count: number | null;
  /** TRUE for a step where an agent uses tools but no condition or decision is stored in parseable form. */
  tool_use_rules_only_in_prose: boolean | null;
  /** Open practitioner flags that the step's guidance is outdated. */
  open_outdated_flag_count: number | null;
  /** TRUE for a step practitioners' feedback says no longer matches how the work is done. */
  has_reported_reality_mismatch: boolean | null;
  /** Executions of the step that recorded a deviation. */
  deviated_run_count: number | null;
  /** TRUE when practice deviates from the step repeatedly, or deviates where practitioners flagged the guidance outdated. */
  is_drifted_from_practice: boolean | null;
  /** Failed AI assistant tasks during this step. */
  ai_failure_count: number | null;
  /** TRUE for a step where an AI assistant has failed a task. */
  is_ai_failure_point: boolean | null;
  /** Inputs fed by an artifact an AI agent's step produces. */
  ai_artifact_input_count: number | null;
  /** TRUE when the step takes an AI agent's artifact as an input. */
  consumes_ai_agent_artifact: boolean | null;
  /** Traces from this step to collected material, in any role. */
  collection_evidence_count: number | null;
  /** TRUE when the step traces to at least one collected material. */
  has_collection_evidence: boolean | null;
  /** Origin traces of this step as an activity definition. */
  activity_origin_trace_count: number | null;
  /** Origin traces of the step's process model. */
  version_model_trace_count: number | null;
  /** TRUE when the step belongs to a traced process model but its own definition traces to no collection. */
  is_untraced_activity_in_traced_model: boolean | null;
  /** Validations of this step captured from people. */
  elicited_validation_count: number | null;
  /** Extensions of this step captured from people. */
  elicited_extension_count: number | null;
  /** Steps reachable from this step along artifact hand-offs. */
  downstream_artifact_step_count: number | null;
  /** TRUE for the step its version declares as its first step. */
  is_declared_first_step: boolean | null;
  /** TRUE for the step its version declares as its fallback step. */
  is_declared_fallback_step: boolean | null;
  /** Step key when declared first. */
  declared_first_step_key: string | null;
  /** Step key when declared the fallback. */
  declared_fallback_step_key: string | null;
  /** The organization that owns the procedure this row belongs to, one hop at a time from Procedures.OwnerOrganization. A row policy compares it to the caller's organization, so a plant sign-in never sees the finance close. */
  owner_organization: string | null;
  _erb_errors?: Record<string, string>;
}

