// USERFEEDBACK TABLE
// Feedback supplied by users about a procedure or execution. Maps to pko:UserFeedbackOccurrence, feedbackOnProcedureExecution, and wasProvidedBy.
// =============================================================================

/** A row in the UserFeedback table. */
export interface UserFeedbackRow {
  /** Stored logical identifier for one UserFeedback row. */
  user_feedback_id: string;
  /** Human-readable calculated display alias for the UserFeedback row. */
  name: string | null;
  /** Execution receiving feedback. */
  procedure_execution: string | null;
  /** Agent providing feedback. */
  provided_by_agent: string | null;
  /** Feedback time. */
  provided_at: string | null;
  /** Feedback statement. */
  feedback_text: string | null;
  /** Accepted, Rejected, UnderReview, or Deferred. */
  disposition: string | null;
  /** Related change request identifier. */
  change_request_key: string | null;
  /** Exact PKO class IRI. */
  semantic_type_iri: string | null;
  /** Remark about the procedure itself (pko:feedbackOnProcedure). */
  feedback_on_procedure: string | null;
  /** Remark about this execution (pko:feedbackOnProcedureExecution). */
  feedback_on_execution: string | null;
  /** TRUE when feedback criticizes the procedure and no change request carries it forward. */
  is_unactioned_procedure_critique: boolean | null;
  /** TRUE when the feedback surfaces know-how the procedure does not hold. */
  reveals_tacit_knowledge: boolean | null;
  /** Collected materials this feedback prompted. */
  collection_follow_up_count: number | null;
  /** TRUE when feedback that surfaces tacit know-how prompted no collection. */
  is_tacit_signal_not_fed_into_collection: boolean | null;
  _erb_errors?: Record<string, string>;
}

const userFeedbackFieldTypes: Record<string, FieldType> = {
  user_feedback_id: "string",
  name: "*string",
  procedure_execution: "*string",
  provided_by_agent: "*string",
  provided_at: "*string",
  feedback_text: "*string",
  disposition: "*string",
  change_request_key: "*string",
  semantic_type_iri: "*string",
  feedback_on_procedure: "*string",
  feedback_on_execution: "*string",
  is_unactioned_procedure_critique: "*bool",
  reveals_tacit_knowledge: "*bool",
  collection_follow_up_count: "*int",
  is_tacit_signal_not_fed_into_collection: "*bool",
};

/** Computes the Name calculated field.
 *  Human-readable calculated display alias for the UserFeedback row.
 *  Formula: ={{Disposition}} & ": " & LEFT({{FeedbackText}}, 60) */
export function calcUserFeedbackName(tc: UserFeedbackRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.disposition)), vS(": "), erbText(erbLeft(vStr(tc.feedback_text), vI(60)))));
}

/** Computes the IsUnactionedProcedureCritique calculated field.
 *  TRUE when feedback criticizes the procedure and no change request carries it forward.
 *  Formula: =AND({{FeedbackOnProcedure}} <> "", {{ChangeRequestKey}} = "", {{Disposition}} <> "Declined") */
export function calcUserFeedbackIsUnactionedProcedureCritique(tc: UserFeedbackRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.feedback_on_procedure))), erbBool3(erbIsBlank(vStr(tc.change_request_key))), erbBool3(erbNe(erbNullif(vStr(tc.disposition)), vS("Declined")))));
}

/** Computes the IsTacitSignalNotFedIntoCollection calculated field.
 *  TRUE when feedback that surfaces tacit know-how prompted no collection.
 *  Formula: =AND({{RevealsTacitKnowledge}}, {{CollectionFollowUpCount}} = 0) */
export function calcUserFeedbackIsTacitSignalNotFedIntoCollection(tc: UserFeedbackRow): boolean | null {
  return toBoolPtr(erbAnd(erbIsTrue(vBool(tc.reveals_tacit_knowledge)), erbBool3(erbEq(vInt(tc.collection_follow_up_count), vI(0)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeUserFeedback(tc: UserFeedbackRow): UserFeedbackRow {
  // Level 1
  calcGuard(tc, userFeedbackFieldTypes, "name", () => { tc.name = calcUserFeedbackName(tc); });
  calcGuard(tc, userFeedbackFieldTypes, "is_unactioned_procedure_critique", () => { tc.is_unactioned_procedure_critique = calcUserFeedbackIsUnactionedProcedureCritique(tc); });
  calcGuard(tc, userFeedbackFieldTypes, "is_tacit_signal_not_fed_into_collection", () => { tc.is_tacit_signal_not_fed_into_collection = calcUserFeedbackIsTacitSignalNotFedIntoCollection(tc); });
  return tc;
}

/** Reads UserFeedback rows from a JSON array file. */
export function loadUserFeedbackRows(file: string): UserFeedbackRow[] {
  return loadRows(file, { fields: userFeedbackFieldTypes }) as unknown as UserFeedbackRow[];
}

