// LIFECYCLESTATUSES TABLE
// Every status a procedure version or an execution can hold, as one controlled scheme. PKO 2.0.0 types procedure statuses and execution statuses as specializations of one general status.
// =============================================================================

/** A row in the LifecycleStatuses table. */
export interface LifecycleStatusesRow {
  /** Stored identifier. */
  lifecycle_status_id: string;
  /** Display name. */
  name: string | null;
  /** Status label. */
  label: string | null;
  /** ProcedureStatus or ProcedureExecutionStatus. */
  status_scheme: string | null;
  /** The general status concept this one specializes. */
  broader_status: string | null;
  /** TRUE when PKO 2.0.0 defines this individual. */
  is_pko_status: boolean | null;
  /** The PKO individual IRI, when there is one. */
  pko_iri: string | null;
  /** Procedure versions currently holding this status. */
  version_use_count: number | null;
  /** Procedure executions currently holding this status. */
  execution_use_count: number | null;
  /** TRUE when a status PKO does not define is held by some version or execution. */
  is_non_pko_status_in_use: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  /** Concept of the controlled workflow-status scheme this status maps to. */
  workflow_status_concept: string | null;
  _erb_errors?: Record<string, string>;
}

const lifecycleStatusesFieldTypes: Record<string, FieldType> = {
  lifecycle_status_id: "string",
  name: "*string",
  label: "*string",
  status_scheme: "*string",
  broader_status: "*string",
  is_pko_status: "*bool",
  pko_iri: "*string",
  version_use_count: "*int",
  execution_use_count: "*int",
  is_non_pko_status_in_use: "*bool",
  semantic_type_iri: "*string",
  workflow_status_concept: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{Label}} */
export function calcLifecycleStatusesName(tc: LifecycleStatusesRow): string | null {
  return toStringPtr(vStr(tc.label));
}

/** Computes the IsNonPkoStatusInUse calculated field.
 *  TRUE when a status PKO does not define is held by some version or execution.
 *  Formula: =AND({{IsPkoStatus}} = FALSE, ({{VersionUseCount}} + {{ExecutionUseCount}}) > 0) */
export function calcLifecycleStatusesIsNonPkoStatusInUse(tc: LifecycleStatusesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vBool(tc.is_pko_status)), vB(false))), erbBool3(erbCmp(erbAdd(vInt(tc.version_use_count), vInt(tc.execution_use_count)), ">", vI(0)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeLifecycleStatuses(tc: LifecycleStatusesRow): LifecycleStatusesRow {
  // Level 1
  calcGuard(tc, lifecycleStatusesFieldTypes, "name", () => { tc.name = calcLifecycleStatusesName(tc); });
  calcGuard(tc, lifecycleStatusesFieldTypes, "is_non_pko_status_in_use", () => { tc.is_non_pko_status_in_use = calcLifecycleStatusesIsNonPkoStatusInUse(tc); });
  return tc;
}

