/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{FromStep}} & " " & {{RelationType}} & " " & {{ToStep}} */
export function calcActivityRelationsName(tc: ActivityRelationsRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.from_step)), vS(" "), erbText(vStr(tc.relation_type)), vS(" "), erbText(vStr(tc.to_step))));
}

/** Computes the UsesUndefinedRelationType calculated field.
 *  TRUE when two steps are linked by a relation type nobody has defined.
 *  Formula: ={{RelationTypeIsDefined}} = FALSE */
export function calcActivityRelationsUsesUndefinedRelationType(tc: ActivityRelationsRow): boolean | null {
  return toBoolPtr(erbEq(vBool(tc.relation_type_is_defined), vB(false)));
}

/** Computes the OverlapsVersionKey calculated field.
 *  Version key for an overlaps relation.
 *  Formula: =IF({{RelationType}} = "Overlaps", {{FromStepVersion}}, "") */
export function calcActivityRelationsOverlapsVersionKey(tc: ActivityRelationsRow): string | null {
  return toStringPtr(erbIf(erbBool3(erbEq(erbNullif(vStr(tc.relation_type)), vS("Overlaps"))), () => vStr(tc.from_step_version), () => vS("")));
}

/** Computes the EnablesVersionKey calculated field.
 *  Version key for an enables relation.
 *  Formula: =IF({{RelationType}} = "Enables", {{FromStepVersion}}, "") */
export function calcActivityRelationsEnablesVersionKey(tc: ActivityRelationsRow): string | null {
  return toStringPtr(erbIf(erbBool3(erbEq(erbNullif(vStr(tc.relation_type)), vS("Enables"))), () => vStr(tc.from_step_version), () => vS("")));
}

/** Computes the PreventsVersionKey calculated field.
 *  Version key for a prevents relation.
 *  Formula: =IF({{RelationType}} = "Prevents", {{FromStepVersion}}, "") */
export function calcActivityRelationsPreventsVersionKey(tc: ActivityRelationsRow): string | null {
  return toStringPtr(erbIf(erbBool3(erbEq(erbNullif(vStr(tc.relation_type)), vS("Prevents"))), () => vStr(tc.from_step_version), () => vS("")));
}

/** Computes every calculated field of the row in dependency order. */
export function computeActivityRelations(tc: ActivityRelationsRow): ActivityRelationsRow {
  // Level 1
  calcGuard(tc, activityRelationsFieldTypes, "name", () => { tc.name = calcActivityRelationsName(tc); });
  calcGuard(tc, activityRelationsFieldTypes, "uses_undefined_relation_type", () => { tc.uses_undefined_relation_type = calcActivityRelationsUsesUndefinedRelationType(tc); });
  calcGuard(tc, activityRelationsFieldTypes, "overlaps_version_key", () => { tc.overlaps_version_key = calcActivityRelationsOverlapsVersionKey(tc); });
  calcGuard(tc, activityRelationsFieldTypes, "enables_version_key", () => { tc.enables_version_key = calcActivityRelationsEnablesVersionKey(tc); });
  calcGuard(tc, activityRelationsFieldTypes, "prevents_version_key", () => { tc.prevents_version_key = calcActivityRelationsPreventsVersionKey(tc); });
  return tc;
}

