const executionEntitiesFieldTypes: Record<string, FieldType> = {
  execution_entity_id: "string",
  name: "*string",
  step_execution: "*string",
  step_variable: "*string",
  usage: "*string",
  entity_label: "*string",
  entity_uri: "*string",
  variable_direction: "*string",
  variable_step: "*string",
  executed_step: "*string",
  is_usage_direction_mismatch: "*bool",
  is_foreign_variable: "*bool",
  used_execution_key: "*string",
  generated_execution_key: "*string",
  semantic_type_iri: "*string",
  recorded_datatype: "*string",
  recorded_format: "*string",
  variable_datatype: "*string",
  variable_expected_format: "*string",
  violates_declared_datatype_or_format: "*bool",
  generating_agent: "*string",
  attributed_to_agent: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{StepExecution}} & " " & {{Usage}} & " " & {{EntityLabel}} */
export function calcExecutionEntitiesName(tc: ExecutionEntitiesRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.step_execution)), vS(" "), erbText(vStr(tc.usage)), vS(" "), erbText(vStr(tc.entity_label))));
}

/** Computes the IsUsageDirectionMismatch calculated field.
 *  TRUE when a used entity maps to an output or a generated entity maps to an input.
 *  Formula: =OR(AND({{Usage}} = "Used", {{VariableDirection}} <> "Input"), AND({{Usage}} = "Generated", {{VariableDirection}} <> "Output")) */
export function calcExecutionEntitiesIsUsageDirectionMismatch(tc: ExecutionEntitiesRow): boolean | null {
  return toBoolPtr(erbOr(erbBool3(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.usage)), vS("Used"))), erbBool3(erbNe(vStr(tc.variable_direction), vS("Input"))))), erbBool3(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.usage)), vS("Generated"))), erbBool3(erbNe(vStr(tc.variable_direction), vS("Output")))))));
}

/** Computes the IsForeignVariable calculated field.
 *  TRUE when the entity corresponds to a variable another step declares.
 *  Formula: ={{VariableStep}} <> {{ExecutedStep}} */
export function calcExecutionEntitiesIsForeignVariable(tc: ExecutionEntitiesRow): boolean | null {
  return toBoolPtr(erbNe(vStr(tc.variable_step), vStr(tc.executed_step)));
}

/** Computes the UsedExecutionKey calculated field.
 *  Step execution key for a used entity.
 *  Formula: =IF({{Usage}} = "Used", {{StepExecution}}, "") */
export function calcExecutionEntitiesUsedExecutionKey(tc: ExecutionEntitiesRow): string | null {
  return toStringPtr(erbIf(erbBool3(erbEq(erbNullif(vStr(tc.usage)), vS("Used"))), () => vStr(tc.step_execution), () => vS("")));
}

/** Computes the GeneratedExecutionKey calculated field.
 *  Step execution key for a generated entity.
 *  Formula: =IF({{Usage}} = "Generated", {{StepExecution}}, "") */
export function calcExecutionEntitiesGeneratedExecutionKey(tc: ExecutionEntitiesRow): string | null {
  return toStringPtr(erbIf(erbBool3(erbEq(erbNullif(vStr(tc.usage)), vS("Generated"))), () => vStr(tc.step_execution), () => vS("")));
}

/** Computes the ViolatesDeclaredDatatypeOrFormat calculated field.
 *  TRUE when a recorded value's datatype or format differs from what its variable declares.
 *  Formula: =OR(AND({{RecordedDatatype}} <> "", {{RecordedDatatype}} <> {{VariableDatatype}}), AND({{RecordedFormat}} <> "", {{VariableExpectedFormat}} <> "", {{RecordedFormat}} <> {{VariableExpectedFormat}})) */
export function calcExecutionEntitiesViolatesDeclaredDatatypeOrFormat(tc: ExecutionEntitiesRow): boolean | null {
  return toBoolPtr(erbOr(erbBool3(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.recorded_datatype))), erbBool3(erbNe(erbNullif(vStr(tc.recorded_datatype)), vStr(tc.variable_datatype))))), erbBool3(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.recorded_format))), erbBool3(erbIsNotBlank(vStr(tc.variable_expected_format))), erbBool3(erbNe(erbNullif(vStr(tc.recorded_format)), vStr(tc.variable_expected_format)))))));
}

/** Computes the AttributedToAgent calculated field.
 *  For a generated entity, the agent it is attributed to (prov:wasAttributedTo).
 *  Formula: =IF({{Usage}} = "Generated", {{GeneratingAgent}}, "") */
export function calcExecutionEntitiesAttributedToAgent(tc: ExecutionEntitiesRow): string | null {
  return toStringPtr(erbIf(erbBool3(erbEq(erbNullif(vStr(tc.usage)), vS("Generated"))), () => vStr(tc.generating_agent), () => vS("")));
}

/** Computes every calculated field of the row in dependency order. */
export function computeExecutionEntities(tc: ExecutionEntitiesRow): ExecutionEntitiesRow {
  // Level 1
  calcGuard(tc, executionEntitiesFieldTypes, "name", () => { tc.name = calcExecutionEntitiesName(tc); });
  calcGuard(tc, executionEntitiesFieldTypes, "is_usage_direction_mismatch", () => { tc.is_usage_direction_mismatch = calcExecutionEntitiesIsUsageDirectionMismatch(tc); });
  calcGuard(tc, executionEntitiesFieldTypes, "is_foreign_variable", () => { tc.is_foreign_variable = calcExecutionEntitiesIsForeignVariable(tc); });
  calcGuard(tc, executionEntitiesFieldTypes, "used_execution_key", () => { tc.used_execution_key = calcExecutionEntitiesUsedExecutionKey(tc); });
  calcGuard(tc, executionEntitiesFieldTypes, "generated_execution_key", () => { tc.generated_execution_key = calcExecutionEntitiesGeneratedExecutionKey(tc); });
  calcGuard(tc, executionEntitiesFieldTypes, "violates_declared_datatype_or_format", () => { tc.violates_declared_datatype_or_format = calcExecutionEntitiesViolatesDeclaredDatatypeOrFormat(tc); });
  calcGuard(tc, executionEntitiesFieldTypes, "attributed_to_agent", () => { tc.attributed_to_agent = calcExecutionEntitiesAttributedToAgent(tc); });
  return tc;
}

/** Reads ExecutionEntities rows from a JSON array file. */
export function loadExecutionEntitiesRows(file: string): ExecutionEntitiesRow[] {
  return loadRows(file, { fields: executionEntitiesFieldTypes }) as unknown as ExecutionEntitiesRow[];
}

// =============================================================================
// STEPCONDITIONS TABLE
// Pre-conditions, post-conditions and invariants of a step.
// =============================================================================

/** A row in the StepConditions table. */
export interface StepConditionsRow {
  /** Stored identifier. */
  step_condition_id: string;
  /** Display name. */
  name: string | null;
  /** Step. */
  step: string | null;
  /** Precondition, Postcondition or Invariant. */
  condition_kind: string | null;
  /** The condition. */
  statement: string | null;
  /** TRUE when breaking it endangers people. */
  is_safety_critical: boolean | null;
  /** Times the condition was checked. */
  check_count: number | null;
  /** TRUE for a condition no execution has ever checked. */
  is_never_checked: boolean | null;
  /** Step key for a precondition. */
  precondition_step_key: string | null;
  /** Step key for a postcondition. */
  postcondition_step_key: string | null;
  /** Step key for an invariant. */
  invariant_step_key: string | null;
  /** Step key for a safety-critical condition. */
  safety_critical_step_key: string | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  /** The condition as an expression an agent or constraint engine can evaluate. */
  machine_expression: string | null;
  /** TRUE when the condition is stored as an expression, not only prose. */
  is_machine_parseable: boolean | null;
  _erb_errors?: Record<string, string>;
}

const stepConditionsFieldTypes: Record<string, FieldType> = {
  step_condition_id: "string",
  name: "*string",
  step: "*string",
  condition_kind: "*string",
  statement: "*string",
  is_safety_critical: "*bool",
  check_count: "*int",
  is_never_checked: "*bool",
  precondition_step_key: "*string",
  postcondition_step_key: "*string",
  invariant_step_key: "*string",
  safety_critical_step_key: "*string",
  semantic_type_iri: "*string",
  machine_expression: "*string",
  is_machine_parseable: "*bool",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{Step}} & " " & {{ConditionKind}} */
export function calcStepConditionsName(tc: StepConditionsRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.step)), vS(" "), erbText(vStr(tc.condition_kind))));
}

/** Computes the IsNeverChecked calculated field.
 *  TRUE for a condition no execution has ever checked.
 *  Formula: ={{CheckCount}} = 0 */
export function calcStepConditionsIsNeverChecked(tc: StepConditionsRow): boolean | null {
  return toBoolPtr(erbEq(vInt(tc.check_count), vI(0)));
}

/** Computes the PreconditionStepKey calculated field.
 *  Step key for a precondition.
 *  Formula: =IF({{ConditionKind}} = "Precondition", {{Step}}, "") */
export function calcStepConditionsPreconditionStepKey(tc: StepConditionsRow): string | null {
  return toStringPtr(erbIf(erbBool3(erbEq(erbNullif(vStr(tc.condition_kind)), vS("Precondition"))), () => vStr(tc.step), () => vS("")));
}

/** Computes the PostconditionStepKey calculated field.
 *  Step key for a postcondition.
 *  Formula: =IF({{ConditionKind}} = "Postcondition", {{Step}}, "") */
export function calcStepConditionsPostconditionStepKey(tc: StepConditionsRow): string | null {
  return toStringPtr(erbIf(erbBool3(erbEq(erbNullif(vStr(tc.condition_kind)), vS("Postcondition"))), () => vStr(tc.step), () => vS("")));
}

/** Computes the InvariantStepKey calculated field.
 *  Step key for an invariant.
 *  Formula: =IF({{ConditionKind}} = "Invariant", {{Step}}, "") */
export function calcStepConditionsInvariantStepKey(tc: StepConditionsRow): string | null {
  return toStringPtr(erbIf(erbBool3(erbEq(erbNullif(vStr(tc.condition_kind)), vS("Invariant"))), () => vStr(tc.step), () => vS("")));
}

/** Computes the SafetyCriticalStepKey calculated field.
 *  Step key for a safety-critical condition.
 *  Formula: =IF({{IsSafetyCritical}}, {{Step}}, "") */
export function calcStepConditionsSafetyCriticalStepKey(tc: StepConditionsRow): string | null {
  return toStringPtr(erbIf(erbIsTrue(vBool(tc.is_safety_critical)), () => vStr(tc.step), () => vS("")));
}

/** Computes the IsMachineParseable calculated field.
 *  TRUE when the condition is stored as an expression, not only prose.
 *  Formula: ={{MachineExpression}} <> "" */
export function calcStepConditionsIsMachineParseable(tc: StepConditionsRow): boolean | null {
  return toBoolPtr(erbIsNotBlank(vStr(tc.machine_expression)));
}

/** Computes every calculated field of the row in dependency order. */
export function computeStepConditions(tc: StepConditionsRow): StepConditionsRow {
  // Level 1
  calcGuard(tc, stepConditionsFieldTypes, "name", () => { tc.name = calcStepConditionsName(tc); });
  calcGuard(tc, stepConditionsFieldTypes, "is_never_checked", () => { tc.is_never_checked = calcStepConditionsIsNeverChecked(tc); });
  calcGuard(tc, stepConditionsFieldTypes, "precondition_step_key", () => { tc.precondition_step_key = calcStepConditionsPreconditionStepKey(tc); });
  calcGuard(tc, stepConditionsFieldTypes, "postcondition_step_key", () => { tc.postcondition_step_key = calcStepConditionsPostconditionStepKey(tc); });
  calcGuard(tc, stepConditionsFieldTypes, "invariant_step_key", () => { tc.invariant_step_key = calcStepConditionsInvariantStepKey(tc); });
  calcGuard(tc, stepConditionsFieldTypes, "safety_critical_step_key", () => { tc.safety_critical_step_key = calcStepConditionsSafetyCriticalStepKey(tc); });
  calcGuard(tc, stepConditionsFieldTypes, "is_machine_parseable", () => { tc.is_machine_parseable = calcStepConditionsIsMachineParseable(tc); });
  return tc;
}

/** Reads StepConditions rows from a JSON array file. */
export function loadStepConditionsRows(file: string): StepConditionsRow[] {
  return loadRows(file, { fields: stepConditionsFieldTypes }) as unknown as StepConditionsRow[];
}

// =============================================================================
// CONDITIONCHECKS TABLE
// A step condition checked during a step execution.
// =============================================================================

/** A row in the ConditionChecks table. */
export interface ConditionChecksRow {
  /** Stored identifier. */
  condition_check_id: string;
  /** Display name. */
  name: string | null;
  /** Step execution. */
  step_execution: string | null;
  /** Condition checked. */
  step_condition: string | null;
  /** Whether the condition held. */
  held: boolean | null;
  /** When checked. */
  checked_at: string | null;
  /** Who checked. */
  checked_by_agent: string | null;
  /** Kind of the checked condition. */
  condition_kind: string | null;
  /** TRUE when a precondition did not hold. */
  is_failed_precondition: boolean | null;
  /** TRUE when an invariant did not hold. */
  is_violated_invariant: boolean | null;
  /** Step execution key when a precondition failed. */
  failed_precondition_execution_key: string | null;
  /** Step execution key when an invariant failed. */
  violated_invariant_execution_key: string | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const conditionChecksFieldTypes: Record<string, FieldType> = {
  condition_check_id: "string",
  name: "*string",
  step_execution: "*string",
  step_condition: "*string",
  held: "*bool",
  checked_at: "*string",
  checked_by_agent: "*string",
  condition_kind: "*string",
  is_failed_precondition: "*bool",
  is_violated_invariant: "*bool",
  failed_precondition_execution_key: "*string",
  violated_invariant_execution_key: "*string",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{StepExecution}} & " / " & {{StepCondition}} */
export function calcConditionChecksName(tc: ConditionChecksRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.step_execution)), vS(" / "), erbText(vStr(tc.step_condition))));
}

/** Computes the IsFailedPrecondition calculated field.
 *  TRUE when a precondition did not hold.
 *  Formula: =AND({{ConditionKind}} = "Precondition", {{Held}} = FALSE) */
export function calcConditionChecksIsFailedPrecondition(tc: ConditionChecksRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(vStr(tc.condition_kind), vS("Precondition"))), erbBool3(erbEq(erbNullif(vBool(tc.held)), vB(false)))));
}

/** Computes the IsViolatedInvariant calculated field.
 *  TRUE when an invariant did not hold.
 *  Formula: =AND({{ConditionKind}} = "Invariant", {{Held}} = FALSE) */
export function calcConditionChecksIsViolatedInvariant(tc: ConditionChecksRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(vStr(tc.condition_kind), vS("Invariant"))), erbBool3(erbEq(erbNullif(vBool(tc.held)), vB(false)))));
}

/** Computes the FailedPreconditionExecutionKey calculated field.
 *  Step execution key when a precondition failed.
 *  Formula: =IF({{IsFailedPrecondition}}, {{StepExecution}}, "") */
export function calcConditionChecksFailedPreconditionExecutionKey(tc: ConditionChecksRow): string | null {
  return toStringPtr(erbIf(erbBool3(vBool(tc.is_failed_precondition)), () => vStr(tc.step_execution), () => vS("")));
}

/** Computes the ViolatedInvariantExecutionKey calculated field.
 *  Step execution key when an invariant failed.
 *  Formula: =IF({{IsViolatedInvariant}}, {{StepExecution}}, "") */
export function calcConditionChecksViolatedInvariantExecutionKey(tc: ConditionChecksRow): string | null {
  return toStringPtr(erbIf(erbBool3(vBool(tc.is_violated_invariant)), () => vStr(tc.step_execution), () => vS("")));
}

/** Computes every calculated field of the row in dependency order. */
export function computeConditionChecks(tc: ConditionChecksRow): ConditionChecksRow {
  // Level 1
  calcGuard(tc, conditionChecksFieldTypes, "name", () => { tc.name = calcConditionChecksName(tc); });
  calcGuard(tc, conditionChecksFieldTypes, "is_failed_precondition", () => { tc.is_failed_precondition = calcConditionChecksIsFailedPrecondition(tc); });
  calcGuard(tc, conditionChecksFieldTypes, "is_violated_invariant", () => { tc.is_violated_invariant = calcConditionChecksIsViolatedInvariant(tc); });
  // Level 2
  calcGuard(tc, conditionChecksFieldTypes, "failed_precondition_execution_key", () => { tc.failed_precondition_execution_key = calcConditionChecksFailedPreconditionExecutionKey(tc); });
  calcGuard(tc, conditionChecksFieldTypes, "violated_invariant_execution_key", () => { tc.violated_invariant_execution_key = calcConditionChecksViolatedInvariantExecutionKey(tc); });
  return tc;
}

/** Reads ConditionChecks rows from a JSON array file. */
export function loadConditionChecksRows(file: string): ConditionChecksRow[] {
  return loadRows(file, { fields: conditionChecksFieldTypes }) as unknown as ConditionChecksRow[];
}

// =============================================================================
// FAILUREMODES TABLE
// Ways a step can fail and the response to each.
// =============================================================================

/** A row in the FailureModes table. */
export interface FailureModesRow {
  /** Stored identifier. */
  failure_mode_id: string;
  /** Display name. */
  name: string | null;
  /** Step that can fail this way. */
  step: string | null;
  /** Target this handling applies to, for unusually configured equipment. */
  procedure_target: string | null;
  /** What goes wrong. */
  description: string | null;
  /** What to do. */
  response: string | null;
  /** TRUE when the response is to escalate at once. */
  requires_escalation: boolean | null;
  /** Role that receives the escalation. */
  escalate_to_role: string | null;
  /** Whether the escalation role is currently unfilled. */
  escalation_role_has_no_holder: boolean | null;
  /** TRUE when a failure that must be escalated goes to a role nobody holds. */
  escalates_to_vacant_role: boolean | null;
  /** TRUE when a failure mode names no response. */
  has_no_response: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const failureModesFieldTypes: Record<string, FieldType> = {
  failure_mode_id: "string",
  name: "*string",
  step: "*string",
  procedure_target: "*string",
  description: "*string",
  response: "*string",
  requires_escalation: "*bool",
  escalate_to_role: "*string",
  escalation_role_has_no_holder: "*bool",
  escalates_to_vacant_role: "*bool",
  has_no_response: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{Step}} & ": " & LEFT({{Description}}, 40) */
export function calcFailureModesName(tc: FailureModesRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.step)), vS(": "), erbText(erbLeft(vStr(tc.description), vI(40)))));
}

/** Computes the EscalatesToVacantRole calculated field.
 *  TRUE when a failure that must be escalated goes to a role nobody holds.
 *  Formula: =AND({{RequiresEscalation}}, {{EscalationRoleHasNoHolder}}) */
export function calcFailureModesEscalatesToVacantRole(tc: FailureModesRow): boolean | null {
  return toBoolPtr(erbAnd(erbIsTrue(vBool(tc.requires_escalation)), erbBool3(vBool(tc.escalation_role_has_no_holder))));
}

/** Computes the HasNoResponse calculated field.
 *  TRUE when a failure mode names no response.
 *  Formula: ={{Response}} = "" */
export function calcFailureModesHasNoResponse(tc: FailureModesRow): boolean | null {
  return toBoolPtr(erbIsBlank(vStr(tc.response)));
}

/** Computes every calculated field of the row in dependency order. */
export function computeFailureModes(tc: FailureModesRow): FailureModesRow {
  // Level 1
  calcGuard(tc, failureModesFieldTypes, "name", () => { tc.name = calcFailureModesName(tc); });
  calcGuard(tc, failureModesFieldTypes, "escalates_to_vacant_role", () => { tc.escalates_to_vacant_role = calcFailureModesEscalatesToVacantRole(tc); });
  calcGuard(tc, failureModesFieldTypes, "has_no_response", () => { tc.has_no_response = calcFailureModesHasNoResponse(tc); });
  return tc;
}

/** Reads FailureModes rows from a JSON array file. */
export function loadFailureModesRows(file: string): FailureModesRow[] {
  return loadRows(file, { fields: failureModesFieldTypes }) as unknown as FailureModesRow[];
}

// =============================================================================
// STEPCUES TABLE
// Indicators, sounds and confirmations a practitioner reads during a step; some are danger cues.
// =============================================================================

/** A row in the StepCues table. */
export interface StepCuesRow {
  /** Stored identifier. */
  step_cue_id: string;
  /** Display name. */
  name: string | null;
  /** Step. */
  step: string | null;
  /** Indicator, Sound, Visual or Confirmation. */
  cue_kind: string | null;
  /** What the practitioner looks, listens or checks for. */
  description: string | null;
  /** TRUE when the cue shows the step did not fully take effect. */
  signals_incomplete_step: boolean | null;
  /** TRUE for a danger cue that calls for escalating at once. */
  requires_escalation: boolean | null;
  /** Role the cue is escalated to. */
  escalate_to_role: string | null;
  /** Times the cue was observed. */
  observation_count: number | null;
  /** Observations of this danger cue that were not escalated. */
  unescalated_observation_count: number | null;
  /** Step key for a danger cue. */
  danger_cue_step_key: string | null;
  /** Step key for a cue that shows the step did not take effect. */
  incomplete_cue_step_key: string | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  /** How a technician on the floor would ask about this warning sign. The assistant offers it verbatim. */
  operator_question: string | null;
  /** The failure mode this warning sign is evidence of. Its recorded response is the assistant's answer. */
  signals_failure_mode: string | null;
  /** What to do, from the failure mode this sign points at. */
  failure_mode_response: string | null;
  /** A sign that means 'not finished' but points at no failure mode, so neither the runner nor the assistant can say what to do about it. */
  is_unanswerable_sign: boolean | null;
  _erb_errors?: Record<string, string>;
}

const stepCuesFieldTypes: Record<string, FieldType> = {
  step_cue_id: "string",
  name: "*string",
  step: "*string",
  cue_kind: "*string",
  description: "*string",
  signals_incomplete_step: "*bool",
  requires_escalation: "*bool",
  escalate_to_role: "*string",
  observation_count: "*int",
  unescalated_observation_count: "*int",
  danger_cue_step_key: "*string",
  incomplete_cue_step_key: "*string",
  semantic_type_iri: "*string",
  operator_question: "*string",
  signals_failure_mode: "*string",
  failure_mode_response: "*string",
  is_unanswerable_sign: "*bool",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{Step}} & " " & {{CueKind}} */
export function calcStepCuesName(tc: StepCuesRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.step)), vS(" "), erbText(vStr(tc.cue_kind))));
}

/** Computes the DangerCueStepKey calculated field.
 *  Step key for a danger cue.
 *  Formula: =IF({{RequiresEscalation}}, {{Step}}, "") */
export function calcStepCuesDangerCueStepKey(tc: StepCuesRow): string | null {
  return toStringPtr(erbIf(erbIsTrue(vBool(tc.requires_escalation)), () => vStr(tc.step), () => vS("")));
}

/** Computes the IncompleteCueStepKey calculated field.
 *  Step key for a cue that shows the step did not take effect.
 *  Formula: =IF({{SignalsIncompleteStep}}, {{Step}}, "") */
export function calcStepCuesIncompleteCueStepKey(tc: StepCuesRow): string | null {
  return toStringPtr(erbIf(erbIsTrue(vBool(tc.signals_incomplete_step)), () => vStr(tc.step), () => vS("")));
}

/** Computes the IsUnanswerableSign calculated field.
 *  A sign that means 'not finished' but points at no failure mode, so neither the runner nor the assistant can say what to do about it.
 *  Formula: =AND({{SignalsIncompleteStep}} = TRUE, {{SignalsFailureMode}} = "") */
export function calcStepCuesIsUnanswerableSign(tc: StepCuesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vBool(tc.signals_incomplete_step)), vB(true))), erbBool3(erbIsBlank(vStr(tc.signals_failure_mode)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeStepCues(tc: StepCuesRow): StepCuesRow {
  // Level 1
  calcGuard(tc, stepCuesFieldTypes, "name", () => { tc.name = calcStepCuesName(tc); });
  calcGuard(tc, stepCuesFieldTypes, "danger_cue_step_key", () => { tc.danger_cue_step_key = calcStepCuesDangerCueStepKey(tc); });
  calcGuard(tc, stepCuesFieldTypes, "incomplete_cue_step_key", () => { tc.incomplete_cue_step_key = calcStepCuesIncompleteCueStepKey(tc); });
  calcGuard(tc, stepCuesFieldTypes, "is_unanswerable_sign", () => { tc.is_unanswerable_sign = calcStepCuesIsUnanswerableSign(tc); });
  return tc;
}

/** Reads StepCues rows from a JSON array file. */
export function loadStepCuesRows(file: string): StepCuesRow[] {
  return loadRows(file, { fields: stepCuesFieldTypes }) as unknown as StepCuesRow[];
}

