// TACTICALRESOURCEALLOCATIONS TABLE
// Tactical knowledge: resources allocated to a step, the demand on them, and the adjustment decided.
// =============================================================================

/** A row in the TacticalResourceAllocations table. */
export interface TacticalResourceAllocationsRow {
  /** Stored identifier. */
  tactical_resource_allocation_id: string;
  /** Display name. */
  name: string | null;
  /** Step the resource serves. */
  step: string | null;
  /** Where the resource is allocated. */
  facility: string | null;
  /** The resource. */
  resource_label: string | null;
  /** People, Equipment or Tooling. */
  resource_kind: string | null;
  /** Capacity allocated per week. */
  available_units_per_week: number | null;
  /** Demand on it per week. */
  demanded_units_per_week: number | null;
  /** How the process is being adjusted. */
  adjustment_decision: string | null;
  /** Demand as a percentage of capacity. */
  utilization_percent: number | null;
  /** TRUE when demand on the resource exceeds the capacity allocated to it. */
  is_bottleneck: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const tacticalResourceAllocationsFieldTypes: Record<string, FieldType> = {
  tactical_resource_allocation_id: "string",
  name: "*string",
  step: "*string",
  facility: "*string",
  resource_label: "*string",
  resource_kind: "*string",
  available_units_per_week: "*float64",
  demanded_units_per_week: "*float64",
  adjustment_decision: "*string",
  utilization_percent: "*float64",
  is_bottleneck: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{Step}} & " / " & {{ResourceLabel}} */
export function calcTacticalResourceAllocationsName(tc: TacticalResourceAllocationsRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.step)), vS(" / "), erbText(vStr(tc.resource_label))));
}

/** Computes the UtilizationPercent calculated field.
 *  Demand as a percentage of capacity.
 *  Formula: =IF({{AvailableUnitsPerWeek}} = 0, 0, ROUND({{DemandedUnitsPerWeek}} * 100 / {{AvailableUnitsPerWeek}}, 1)) */
export function calcTacticalResourceAllocationsUtilizationPercent(tc: TacticalResourceAllocationsRow): number | null {
  return toFloatPtr(erbIf(erbBool3(erbEq(erbNullif(vNum(tc.available_units_per_week)), vI(0))), () => vI(0), () => erbRound(erbDiv(erbMul(vNum(tc.demanded_units_per_week), vI(100)), vNum(tc.available_units_per_week)), vI(1))));
}

/** Computes the IsBottleneck calculated field.
 *  TRUE when demand on the resource exceeds the capacity allocated to it.
 *  Formula: ={{DemandedUnitsPerWeek}} > {{AvailableUnitsPerWeek}} */
export function calcTacticalResourceAllocationsIsBottleneck(tc: TacticalResourceAllocationsRow): boolean | null {
  return toBoolPtr(erbCmp(erbNullif(vNum(tc.demanded_units_per_week)), ">", erbNullif(vNum(tc.available_units_per_week))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeTacticalResourceAllocations(tc: TacticalResourceAllocationsRow): TacticalResourceAllocationsRow {
  // Level 1
  calcGuard(tc, tacticalResourceAllocationsFieldTypes, "name", () => { tc.name = calcTacticalResourceAllocationsName(tc); });
  calcGuard(tc, tacticalResourceAllocationsFieldTypes, "utilization_percent", () => { tc.utilization_percent = calcTacticalResourceAllocationsUtilizationPercent(tc); });
  calcGuard(tc, tacticalResourceAllocationsFieldTypes, "is_bottleneck", () => { tc.is_bottleneck = calcTacticalResourceAllocationsIsBottleneck(tc); });
  return tc;
}

/** Reads TacticalResourceAllocations rows from a JSON array file. */
export function loadTacticalResourceAllocationsRows(file: string): TacticalResourceAllocationsRow[] {
  return loadRows(file, { fields: tacticalResourceAllocationsFieldTypes }) as unknown as TacticalResourceAllocationsRow[];
}

