export interface ProcedureLensViewsRow {
  /** Stored identifier. */
  procedure_lens_view_id: string;
  /** Display name. */
  name: string | null;
  /** Procedure viewed. */
  procedure: string | null;
  /** Lens served. */
  stakeholder_lens: string | null;
  /** Version the view is projected from; blank for a free-standing document. */
  projects_version: string | null;
  /** Step, Stage or Category. */
  granularity: string | null;
  /** Prose, Diagram, Table or MachineReadable. */
  form: string | null;
  /** The procedure's current version. */
  procedure_current_version: string | null;
  /** Granularity the lens requires. */
  lens_granularity_rank: number | null;
  /** Granularity the view delivers. */
  view_granularity_rank: number | null;
  /** TRUE when a view is coarser or finer than its lens's use requires. */
  is_granularity_misfit: boolean | null;
  /** TRUE when a view is not projected from the procedure's current version: a free-standing copy that will drift apart. */
  is_disconnected_silo: boolean | null;
  /** Procedure key when the lens needs step-level detail. */
  step_level_procedure_key: string | null;
  /** Procedure key when the lens needs only the category. */
  category_level_procedure_key: string | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const procedureLensViewsFieldTypes: Record<string, FieldType> = {
  procedure_lens_view_id: "string",
  name: "*string",
  procedure: "*string",
  stakeholder_lens: "*string",
  projects_version: "*string",
  granularity: "*string",
  form: "*string",
  procedure_current_version: "*string",
  lens_granularity_rank: "*int",
  view_granularity_rank: "*int",
  is_granularity_misfit: "*bool",
  is_disconnected_silo: "*bool",
  step_level_procedure_key: "*string",
  category_level_procedure_key: "*string",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{Procedure}} & " for " & {{StakeholderLens}} */
export function calcProcedureLensViewsName(tc: ProcedureLensViewsRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.procedure)), vS(" for "), erbText(vStr(tc.stakeholder_lens))));
}

/** Computes the ViewGranularityRank calculated field.
 *  Granularity the view delivers.
 *  Formula: =IF({{Granularity}} = "Step", 3, IF({{Granularity}} = "Stage", 2, IF({{Granularity}} = "Category", 1, 0))) */
export function calcProcedureLensViewsViewGranularityRank(tc: ProcedureLensViewsRow): number | null {
  return toIntPtr(erbInteger(erbIf(erbBool3(erbEq(erbNullif(vStr(tc.granularity)), vS("Step"))), () => vI(3), () => erbIf(erbBool3(erbEq(erbNullif(vStr(tc.granularity)), vS("Stage"))), () => vI(2), () => erbIf(erbBool3(erbEq(erbNullif(vStr(tc.granularity)), vS("Category"))), () => vI(1), () => vI(0))))));
}

/** Computes the IsGranularityMisfit calculated field.
 *  TRUE when a view is coarser or finer than its lens's use requires.
 *  Formula: =AND({{LensGranularityRank}} > 0, {{ViewGranularityRank}} <> {{LensGranularityRank}}) */
export function calcProcedureLensViewsIsGranularityMisfit(tc: ProcedureLensViewsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.lens_granularity_rank), ">", vI(0))), erbBool3(erbNe(vInt(tc.view_granularity_rank), vInt(tc.lens_granularity_rank)))));
}

/** Computes the IsDisconnectedSilo calculated field.
 *  TRUE when a view is not projected from the procedure's current version: a free-standing copy that will drift apart.
 *  Formula: =OR({{ProjectsVersion}} = "", {{ProjectsVersion}} <> {{ProcedureCurrentVersion}}) */
export function calcProcedureLensViewsIsDisconnectedSilo(tc: ProcedureLensViewsRow): boolean | null {
  return toBoolPtr(erbOr(erbBool3(erbIsBlank(vStr(tc.projects_version))), erbBool3(erbNe(erbNullif(vStr(tc.projects_version)), vStr(tc.procedure_current_version)))));
}

/** Computes the StepLevelProcedureKey calculated field.
 *  Procedure key when the lens needs step-level detail.
 *  Formula: =IF({{LensGranularityRank}} = 3, {{Procedure}}, "") */
export function calcProcedureLensViewsStepLevelProcedureKey(tc: ProcedureLensViewsRow): string | null {
  return toStringPtr(erbIf(erbBool3(erbEq(vInt(tc.lens_granularity_rank), vI(3))), () => vStr(tc.procedure), () => vS("")));
}

/** Computes the CategoryLevelProcedureKey calculated field.
 *  Procedure key when the lens needs only the category.
 *  Formula: =IF({{LensGranularityRank}} = 1, {{Procedure}}, "") */
export function calcProcedureLensViewsCategoryLevelProcedureKey(tc: ProcedureLensViewsRow): string | null {
  return toStringPtr(erbIf(erbBool3(erbEq(vInt(tc.lens_granularity_rank), vI(1))), () => vStr(tc.procedure), () => vS("")));
}

/** Computes every calculated field of the row in dependency order. */
export function computeProcedureLensViews(tc: ProcedureLensViewsRow): ProcedureLensViewsRow {
  // Level 1
  calcGuard(tc, procedureLensViewsFieldTypes, "name", () => { tc.name = calcProcedureLensViewsName(tc); });
  calcGuard(tc, procedureLensViewsFieldTypes, "view_granularity_rank", () => { tc.view_granularity_rank = calcProcedureLensViewsViewGranularityRank(tc); });
  calcGuard(tc, procedureLensViewsFieldTypes, "is_disconnected_silo", () => { tc.is_disconnected_silo = calcProcedureLensViewsIsDisconnectedSilo(tc); });
  calcGuard(tc, procedureLensViewsFieldTypes, "step_level_procedure_key", () => { tc.step_level_procedure_key = calcProcedureLensViewsStepLevelProcedureKey(tc); });
  calcGuard(tc, procedureLensViewsFieldTypes, "category_level_procedure_key", () => { tc.category_level_procedure_key = calcProcedureLensViewsCategoryLevelProcedureKey(tc); });
  // Level 2
  calcGuard(tc, procedureLensViewsFieldTypes, "is_granularity_misfit", () => { tc.is_granularity_misfit = calcProcedureLensViewsIsGranularityMisfit(tc); });
  return tc;
}

/** Reads ProcedureLensViews rows from a JSON array file. */
export function loadProcedureLensViewsRows(file: string): ProcedureLensViewsRow[] {
  return loadRows(file, { fields: procedureLensViewsFieldTypes }) as unknown as ProcedureLensViewsRow[];
}

// =============================================================================
// APPLICABILITYSCOPES TABLE
// Where a piece of process knowledge applies: business unit, geography, customer segment, regulatory regime, conditions, and the named graph holding it.
// =============================================================================

/** A row in the ApplicabilityScopes table. */
export interface ApplicabilityScopesRow {
  /** Stored identifier. */
  applicability_scope_id: string;
  /** Display name. */
  name: string | null;
  /** Scope. */
  label: string | null;
  /** Business unit. */
  business_unit: string | null;
  /** Geography (ISO region code). */
  geography: string | null;
  /** Customer segment. */
  customer_segment: string | null;
  /** Regulatory regime. */
  regulatory_regime: string | null;
  /** Condition under which the knowledge holds. */
  applies_when: string | null;
  /** Scoping annotation: where the knowledge stops applying. */
  exclusion_condition: string | null;
  /** Named graph that holds the knowledge scoped here. */
  named_graph_iri: string | null;
  /** Context dimensions the scope names. */
  dimension_count: number | null;
  /** TRUE when the scope says when the knowledge applies or where it stops. */
  states_conditions: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const applicabilityScopesFieldTypes: Record<string, FieldType> = {
  applicability_scope_id: "string",
  name: "*string",
  label: "*string",
  business_unit: "*string",
  geography: "*string",
  customer_segment: "*string",
  regulatory_regime: "*string",
  applies_when: "*string",
  exclusion_condition: "*string",
  named_graph_iri: "*string",
  dimension_count: "*int",
  states_conditions: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{Label}} */
export function calcApplicabilityScopesName(tc: ApplicabilityScopesRow): string | null {
  return toStringPtr(vStr(tc.label));
}

/** Computes the DimensionCount calculated field.
 *  Context dimensions the scope names.
 *  Formula: =IF({{BusinessUnit}} <> "", 1, 0) + IF({{Geography}} <> "", 1, 0) + IF({{CustomerSegment}} <> "", 1, 0) + IF({{RegulatoryRegime}} <> "", 1, 0) */
export function calcApplicabilityScopesDimensionCount(tc: ApplicabilityScopesRow): number | null {
  return toIntPtr(erbInteger(erbAdd(erbAdd(erbAdd(erbIf(erbBool3(erbIsNotBlank(vStr(tc.business_unit))), () => vI(1), () => vI(0)), erbIf(erbBool3(erbIsNotBlank(vStr(tc.geography))), () => vI(1), () => vI(0))), erbIf(erbBool3(erbIsNotBlank(vStr(tc.customer_segment))), () => vI(1), () => vI(0))), erbIf(erbBool3(erbIsNotBlank(vStr(tc.regulatory_regime))), () => vI(1), () => vI(0)))));
}

/** Computes the StatesConditions calculated field.
 *  TRUE when the scope says when the knowledge applies or where it stops.
 *  Formula: =OR({{AppliesWhen}} <> "", {{ExclusionCondition}} <> "") */
export function calcApplicabilityScopesStatesConditions(tc: ApplicabilityScopesRow): boolean | null {
  return toBoolPtr(erbOr(erbBool3(erbIsNotBlank(vStr(tc.applies_when))), erbBool3(erbIsNotBlank(vStr(tc.exclusion_condition)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeApplicabilityScopes(tc: ApplicabilityScopesRow): ApplicabilityScopesRow {
  // Level 1
  calcGuard(tc, applicabilityScopesFieldTypes, "name", () => { tc.name = calcApplicabilityScopesName(tc); });
  calcGuard(tc, applicabilityScopesFieldTypes, "dimension_count", () => { tc.dimension_count = calcApplicabilityScopesDimensionCount(tc); });
  calcGuard(tc, applicabilityScopesFieldTypes, "states_conditions", () => { tc.states_conditions = calcApplicabilityScopesStatesConditions(tc); });
  return tc;
}

/** Reads ApplicabilityScopes rows from a JSON array file. */
export function loadApplicabilityScopesRows(file: string): ApplicabilityScopesRow[] {
  return loadRows(file, { fields: applicabilityScopesFieldTypes }) as unknown as ApplicabilityScopesRow[];
}

