// =============================================================================
// SITUATIONALVARIANTS TABLE
// How experts adapt a standard procedure to the situation in front of them.
// =============================================================================

/** A row in the SituationalVariants table. */
export interface SituationalVariantsRow {
  /** Stored identifier. */
  situational_variant_id: string;
  /** Display name. */
  name: string | null;
  /** Standard procedure adapted. */
  procedure: string | null;
  /** Variant. */
  label: string | null;
  /** The situation. */
  situation: string | null;
  /** What the expert does differently. */
  adaptation: string | null;
  /** Where the variant applies. */
  applicability_scope: string | null;
  /** Expert the variant came from. */
  expert_agent: string | null;
  /** Context dimensions the scope names. */
  scope_dimension_count: number | null;
  /** Whether the scope states its conditions. */
  scope_states_conditions: boolean | null;
  /** TRUE when nothing says under which business unit, geography, segment or regime the variant applies. */
  has_no_applicability_dimension: boolean | null;
  /** TRUE when a variant departs from the standard with no stated condition for when it applies or stops. */
  diverges_without_stated_conditions: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const situationalVariantsFieldTypes: Record<string, FieldType> = {
  situational_variant_id: "string",
  name: "*string",
  procedure: "*string",
  label: "*string",
  situation: "*string",
  adaptation: "*string",
  applicability_scope: "*string",
  expert_agent: "*string",
  scope_dimension_count: "*int",
  scope_states_conditions: "*bool",
  has_no_applicability_dimension: "*bool",
  diverges_without_stated_conditions: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{Label}} */
export function calcSituationalVariantsName(tc: SituationalVariantsRow): string | null {
  return toStringPtr(vStr(tc.label));
}

/** Computes the HasNoApplicabilityDimension calculated field.
 *  TRUE when nothing says under which business unit, geography, segment or regime the variant applies.
 *  Formula: =OR({{ApplicabilityScope}} = "", {{ScopeDimensionCount}} = 0) */
export function calcSituationalVariantsHasNoApplicabilityDimension(tc: SituationalVariantsRow): boolean | null {
  return toBoolPtr(erbOr(erbBool3(erbIsBlank(vStr(tc.applicability_scope))), erbBool3(erbEq(vInt(tc.scope_dimension_count), vI(0)))));
}

/** Computes the DivergesWithoutStatedConditions calculated field.
 *  TRUE when a variant departs from the standard with no stated condition for when it applies or stops.
 *  Formula: =AND({{Adaptation}} <> "", OR({{ApplicabilityScope}} = "", {{ScopeStatesConditions}} = FALSE)) */
export function calcSituationalVariantsDivergesWithoutStatedConditions(tc: SituationalVariantsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.adaptation))), erbBool3(erbOr(erbBool3(erbIsBlank(vStr(tc.applicability_scope))), erbBool3(erbEq(vBool(tc.scope_states_conditions), vB(false)))))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeSituationalVariants(tc: SituationalVariantsRow): SituationalVariantsRow {
  // Level 1
  calcGuard(tc, situationalVariantsFieldTypes, "name", () => { tc.name = calcSituationalVariantsName(tc); });
  calcGuard(tc, situationalVariantsFieldTypes, "has_no_applicability_dimension", () => { tc.has_no_applicability_dimension = calcSituationalVariantsHasNoApplicabilityDimension(tc); });
  calcGuard(tc, situationalVariantsFieldTypes, "diverges_without_stated_conditions", () => { tc.diverges_without_stated_conditions = calcSituationalVariantsDivergesWithoutStatedConditions(tc); });
  return tc;
}

/** Reads SituationalVariants rows from a JSON array file. */
export function loadSituationalVariantsRows(file: string): SituationalVariantsRow[] {
  return loadRows(file, { fields: situationalVariantsFieldTypes }) as unknown as SituationalVariantsRow[];
}

// =============================================================================
// COLLECTEDSOURCEMATERIALS TABLE
// Raw material collection produced, and when it was organized into a scheme and encoded into a procedure version.
// =============================================================================

/** A row in the CollectedSourceMaterials table. */
export interface CollectedSourceMaterialsRow {
  /** Stored identifier. */
  collected_source_material_id: string;
  /** Display name. */
  name: string | null;
  /** Material. */
  label: string | null;
  /** Transcript, FieldNotes, ProcessMap, MinedEventTrace or DocumentExcerpt. */
  material_kind: string | null;
  /** Procedure the material is about. */
  procedure: string | null;
  /** When collected. */
  collected_at: string | null;
  /** Scheme the material was organized into. */
  organized_into_scheme: string | null;
  /** When it was organized. */
  organized_at: string | null;
  /** Version it was modeled into. */
  encoded_into_version: string | null;
  /** When it was modeled. */
  encoded_at: string | null;
  /** TRUE when material was encoded into a procedure version before it was organized, or without ever being organized. */
  is_modeled_before_organized: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  /** The existing document the material was excerpted from. */
  source_document: string | null;
  /** Last revision of that document. */
  source_document_revised_at: string | null;
  /** TRUE for an excerpt of existing written material. */
  is_document_source: boolean | null;
  /** TRUE for material captured from people: a transcript or field notes. */
  is_people_capture: boolean | null;
  /** TRUE for material that records the work as performed: field notes or a mined event trace. */
  is_practice_evidence: boolean | null;
  /** TRUE when the material holds the reasoning or tacit knowledge behind the actions, not only the actions. */
  holds_reasoning_or_tacit_knowledge: boolean | null;
  /** The mining run whose findings this capture from people explains. */
  complements_mining_run: string | null;
  /** The execution during which the material was captured, when captured in the course of work. */
  captured_during_execution: string | null;
  /** TRUE when the material was captured while the work was being done. */
  is_captured_in_flow_of_work: boolean | null;
  /** The recurring occasion at which the material was collected. */
  collected_at_occasion: string | null;
  /** The practitioner feedback that prompted this collection. */
  prompted_by_feedback: string | null;
  /** The method application that produced the material. */
  produced_by_method_application: string | null;
  /** The domain expert whose time the capture consumed. */
  contributing_expert: string | null;
  /** Hours of expert time the capture consumed. */
  expert_effort_hours: number | null;
  /** Organized knowledge traced to this material. */
  dependent_trace_count: number | null;
  /** TRUE when the material was encoded into a model but no trace records what rests on it, so a change to it reveals nothing. */
  is_dependency_invisible_to_change: boolean | null;
  /** Traced knowledge taken before the source document was last revised. */
  changed_dependent_count: number | null;
  /** TRUE when a revision of the source affects organized knowledge taken from it. */
  has_knowledge_affected_by_source_change: boolean | null;
  _erb_errors?: Record<string, string>;
}

const collectedSourceMaterialsFieldTypes: Record<string, FieldType> = {
  collected_source_material_id: "string",
  name: "*string",
  label: "*string",
  material_kind: "*string",
  procedure: "*string",
  collected_at: "*string",
  organized_into_scheme: "*string",
  organized_at: "*string",
  encoded_into_version: "*string",
  encoded_at: "*string",
  is_modeled_before_organized: "*bool",
  semantic_type_iri: "*string",
  source_document: "*string",
  source_document_revised_at: "*string",
  is_document_source: "*bool",
  is_people_capture: "*bool",
  is_practice_evidence: "*bool",
  holds_reasoning_or_tacit_knowledge: "*bool",
  complements_mining_run: "*string",
  captured_during_execution: "*string",
  is_captured_in_flow_of_work: "*bool",
  collected_at_occasion: "*string",
  prompted_by_feedback: "*string",
  produced_by_method_application: "*string",
  contributing_expert: "*string",
  expert_effort_hours: "*float64",
  dependent_trace_count: "*int",
  is_dependency_invisible_to_change: "*bool",
  changed_dependent_count: "*int",
  has_knowledge_affected_by_source_change: "*bool",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{Label}} */
export function calcCollectedSourceMaterialsName(tc: CollectedSourceMaterialsRow): string | null {
  return toStringPtr(vStr(tc.label));
}

/** Computes the IsModeledBeforeOrganized calculated field.
 *  TRUE when material was encoded into a procedure version before it was organized, or without ever being organized.
 *  Formula: =AND({{EncodedIntoVersion}} <> "", OR({{OrganizedAt}} = "", {{EncodedAt}} < {{OrganizedAt}})) */
export function calcCollectedSourceMaterialsIsModeledBeforeOrganized(tc: CollectedSourceMaterialsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.encoded_into_version))), erbBool3(erbOr(erbBool3(erbIsBlank(vStr(tc.organized_at))), erbBool3(erbCmp(erbNullif(vStr(tc.encoded_at)), "<", erbNullif(vStr(tc.organized_at))))))));
}

/** Computes the IsDocumentSource calculated field.
 *  TRUE for an excerpt of existing written material.
 *  Formula: ={{MaterialKind}} = "DocumentExcerpt" */
export function calcCollectedSourceMaterialsIsDocumentSource(tc: CollectedSourceMaterialsRow): boolean | null {
  return toBoolPtr(erbEq(erbNullif(vStr(tc.material_kind)), vS("DocumentExcerpt")));
}

/** Computes the IsPeopleCapture calculated field.
 *  TRUE for material captured from people: a transcript or field notes.
 *  Formula: =OR({{MaterialKind}} = "Transcript", {{MaterialKind}} = "FieldNotes") */
export function calcCollectedSourceMaterialsIsPeopleCapture(tc: CollectedSourceMaterialsRow): boolean | null {
  return toBoolPtr(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.material_kind)), vS("Transcript"))), erbBool3(erbEq(erbNullif(vStr(tc.material_kind)), vS("FieldNotes")))));
}

/** Computes the IsPracticeEvidence calculated field.
 *  TRUE for material that records the work as performed: field notes or a mined event trace.
 *  Formula: =OR({{MaterialKind}} = "FieldNotes", {{MaterialKind}} = "MinedEventTrace") */
export function calcCollectedSourceMaterialsIsPracticeEvidence(tc: CollectedSourceMaterialsRow): boolean | null {
  return toBoolPtr(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.material_kind)), vS("FieldNotes"))), erbBool3(erbEq(erbNullif(vStr(tc.material_kind)), vS("MinedEventTrace")))));
}

/** Computes the IsCapturedInFlowOfWork calculated field.
 *  TRUE when the material was captured while the work was being done.
 *  Formula: ={{CapturedDuringExecution}} <> "" */
export function calcCollectedSourceMaterialsIsCapturedInFlowOfWork(tc: CollectedSourceMaterialsRow): boolean | null {
  return toBoolPtr(erbIsNotBlank(vStr(tc.captured_during_execution)));
}

/** Computes the IsDependencyInvisibleToChange calculated field.
 *  TRUE when the material was encoded into a model but no trace records what rests on it, so a change to it reveals nothing.
 *  Formula: =AND({{EncodedIntoVersion}} <> "", {{DependentTraceCount}} = 0) */
export function calcCollectedSourceMaterialsIsDependencyInvisibleToChange(tc: CollectedSourceMaterialsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.encoded_into_version))), erbBool3(erbEq(vInt(tc.dependent_trace_count), vI(0)))));
}

/** Computes the HasKnowledgeAffectedBySourceChange calculated field.
 *  TRUE when a revision of the source affects organized knowledge taken from it.
 *  Formula: ={{ChangedDependentCount}} > 0 */
export function calcCollectedSourceMaterialsHasKnowledgeAffectedBySourceChange(tc: CollectedSourceMaterialsRow): boolean | null {
  return toBoolPtr(erbCmp(vInt(tc.changed_dependent_count), ">", vI(0)));
}

/** Computes every calculated field of the row in dependency order. */
export function computeCollectedSourceMaterials(tc: CollectedSourceMaterialsRow): CollectedSourceMaterialsRow {
  // Level 1
  calcGuard(tc, collectedSourceMaterialsFieldTypes, "name", () => { tc.name = calcCollectedSourceMaterialsName(tc); });
  calcGuard(tc, collectedSourceMaterialsFieldTypes, "is_modeled_before_organized", () => { tc.is_modeled_before_organized = calcCollectedSourceMaterialsIsModeledBeforeOrganized(tc); });
  calcGuard(tc, collectedSourceMaterialsFieldTypes, "is_document_source", () => { tc.is_document_source = calcCollectedSourceMaterialsIsDocumentSource(tc); });
  calcGuard(tc, collectedSourceMaterialsFieldTypes, "is_people_capture", () => { tc.is_people_capture = calcCollectedSourceMaterialsIsPeopleCapture(tc); });
  calcGuard(tc, collectedSourceMaterialsFieldTypes, "is_practice_evidence", () => { tc.is_practice_evidence = calcCollectedSourceMaterialsIsPracticeEvidence(tc); });
  calcGuard(tc, collectedSourceMaterialsFieldTypes, "is_captured_in_flow_of_work", () => { tc.is_captured_in_flow_of_work = calcCollectedSourceMaterialsIsCapturedInFlowOfWork(tc); });
  calcGuard(tc, collectedSourceMaterialsFieldTypes, "is_dependency_invisible_to_change", () => { tc.is_dependency_invisible_to_change = calcCollectedSourceMaterialsIsDependencyInvisibleToChange(tc); });
  calcGuard(tc, collectedSourceMaterialsFieldTypes, "has_knowledge_affected_by_source_change", () => { tc.has_knowledge_affected_by_source_change = calcCollectedSourceMaterialsHasKnowledgeAffectedBySourceChange(tc); });
  return tc;
}

