// =============================================================================
// TERMLABELVARIANTS TABLE
// Preferred and alternative labels of a controlled concept, one row per wording, so variant wordings can be matched.
// =============================================================================

/** A row in the TermLabelVariants table. */
export interface TermLabelVariantsRow {
  /** Stored identifier. */
  term_label_variant_id: string;
  /** Display name. */
  name: string | null;
  /** Concept labeled. */
  vocabulary_term: string | null;
  /** pref (skos:prefLabel) or alt (skos:altLabel). */
  label_kind: string | null;
  /** The wording, lower case. */
  wording: string | null;
  /** Scheme the concept belongs to. */
  term_scheme: string | null;
  /** The preferred label of the concept this wording belongs to. What a vocabulary search answers with, whichever wording was typed. */
  term_pref_label: string | null;
  /** Scheme and wording. */
  wording_key: string | null;
  /** Scheme and wording for a preferred label. */
  pref_wording_key: string | null;
  /** Labels in the same scheme with this exact wording. */
  concepts_sharing_wording: number | null;
  /** TRUE when one wording is a label of more than one concept in the scheme, so it cannot normalize to one canonical concept. */
  is_ambiguous_label: boolean | null;
  /** Practitioner mentions using this wording in this scheme. */
  practitioner_mention_count: number | null;
  /** Wording of a preferred label, regardless of scheme. */
  pref_wording: string | null;
  /** Preferred labels in any scheme with this wording. */
  same_pref_wording_count: number | null;
  /** TRUE when the same concern is defined as a separate preferred concept in more than one scheme instead of being shared. */
  is_cross_scheme_duplicate_pref: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const termLabelVariantsFieldTypes: Record<string, FieldType> = {
  term_label_variant_id: "string",
  name: "*string",
  vocabulary_term: "*string",
  label_kind: "*string",
  wording: "*string",
  term_scheme: "*string",
  term_pref_label: "*string",
  wording_key: "*string",
  pref_wording_key: "*string",
  concepts_sharing_wording: "*int",
  is_ambiguous_label: "*bool",
  practitioner_mention_count: "*int",
  pref_wording: "*string",
  same_pref_wording_count: "*int",
  is_cross_scheme_duplicate_pref: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{VocabularyTerm}} & " " & {{LabelKind}} & ": " & {{Wording}} */
export function calcTermLabelVariantsName(tc: TermLabelVariantsRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.vocabulary_term)), vS(" "), erbText(vStr(tc.label_kind)), vS(": "), erbText(vStr(tc.wording))));
}

/** Computes the WordingKey calculated field.
 *  Scheme and wording.
 *  Formula: ={{TermScheme}} & "|" & {{Wording}} */
export function calcTermLabelVariantsWordingKey(tc: TermLabelVariantsRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.term_scheme)), vS("|"), erbText(vStr(tc.wording))));
}

/** Computes the PrefWordingKey calculated field.
 *  Scheme and wording for a preferred label.
 *  Formula: =IF({{LabelKind}} = "pref", {{WordingKey}}, "") */
export function calcTermLabelVariantsPrefWordingKey(tc: TermLabelVariantsRow): string | null {
  return toStringPtr(erbIf(erbBool3(erbEq(erbNullif(vStr(tc.label_kind)), vS("pref"))), () => vStr(tc.wording_key), () => vS("")));
}

/** Computes the IsAmbiguousLabel calculated field.
 *  TRUE when one wording is a label of more than one concept in the scheme, so it cannot normalize to one canonical concept.
 *  Formula: ={{ConceptsSharingWording}} > 1 */
export function calcTermLabelVariantsIsAmbiguousLabel(tc: TermLabelVariantsRow): boolean | null {
  return toBoolPtr(erbCmp(vInt(tc.concepts_sharing_wording), ">", vI(1)));
}

/** Computes the PrefWording calculated field.
 *  Wording of a preferred label, regardless of scheme.
 *  Formula: =IF({{LabelKind}} = "pref", {{Wording}}, "") */
export function calcTermLabelVariantsPrefWording(tc: TermLabelVariantsRow): string | null {
  return toStringPtr(erbIf(erbBool3(erbEq(erbNullif(vStr(tc.label_kind)), vS("pref"))), () => vStr(tc.wording), () => vS("")));
}

/** Computes the IsCrossSchemeDuplicatePref calculated field.
 *  TRUE when the same concern is defined as a separate preferred concept in more than one scheme instead of being shared.
 *  Formula: =AND({{LabelKind}} = "pref", {{SamePrefWordingCount}} > 1) */
export function calcTermLabelVariantsIsCrossSchemeDuplicatePref(tc: TermLabelVariantsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.label_kind)), vS("pref"))), erbBool3(erbCmp(vInt(tc.same_pref_wording_count), ">", vI(1)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeTermLabelVariants(tc: TermLabelVariantsRow): TermLabelVariantsRow {
  // Level 1
  calcGuard(tc, termLabelVariantsFieldTypes, "name", () => { tc.name = calcTermLabelVariantsName(tc); });
  calcGuard(tc, termLabelVariantsFieldTypes, "wording_key", () => { tc.wording_key = calcTermLabelVariantsWordingKey(tc); });
  calcGuard(tc, termLabelVariantsFieldTypes, "is_ambiguous_label", () => { tc.is_ambiguous_label = calcTermLabelVariantsIsAmbiguousLabel(tc); });
  calcGuard(tc, termLabelVariantsFieldTypes, "pref_wording", () => { tc.pref_wording = calcTermLabelVariantsPrefWording(tc); });
  calcGuard(tc, termLabelVariantsFieldTypes, "is_cross_scheme_duplicate_pref", () => { tc.is_cross_scheme_duplicate_pref = calcTermLabelVariantsIsCrossSchemeDuplicatePref(tc); });
  // Level 2
  calcGuard(tc, termLabelVariantsFieldTypes, "pref_wording_key", () => { tc.pref_wording_key = calcTermLabelVariantsPrefWordingKey(tc); });
  return tc;
}

/** Reads TermLabelVariants rows from a JSON array file. */
export function loadTermLabelVariantsRows(file: string): TermLabelVariantsRow[] {
  return loadRows(file, { fields: termLabelVariantsFieldTypes }) as unknown as TermLabelVariantsRow[];
}

