// =============================================================================
// ASSISTANTANSWERS TABLE
// One answer, guidance or recommendation an AI assistant delivered, recorded with its context and review. The model does not run the AI; it records what it said.
// =============================================================================

/** A row in the AssistantAnswers table. */
export interface AssistantAnswersRow {
  /** Stored identifier. */
  assistant_answer_id: string;
  /** Display name. */
  name: string | null;
  /** AI agent that answered. */
  answering_agent: string | null;
  /** Who asked. */
  asked_by_agent: string | null;
  /** Integration the answer came through. */
  via_integration: string | null;
  /** Step execution under way when the question was asked. */
  step_execution: string | null;
  /** When asked. */
  asked_at: string | null;
  /** When answered. */
  answered_at: string | null;
  /** Guidance, Recommendation or Lookup. */
  answer_kind: string | null;
  /** Authority, Safety, Sequence, Scheduling or General. */
  question_topic: string | null;
  /** The question. */
  question_text: string | null;
  /** The answer. */
  answer_text: string | null;
  /** StructuredQuery, DocumentPassage or None. */
  retrieval_mode: string | null;
  /** Reasoner, StructuredQuery or LanguageModel: what produced the logic of the answer. */
  derivation_performed_by: string | null;
  /** TRUE when the answer requires deriving something not stated outright. */
  needs_inference: boolean | null;
  /** Step the assistant believed the execution was at. */
  assumed_current_step: string | null;
  /** Step the assistant said comes next. */
  asserted_next_step: string | null;
  /** Step a recommendation acts on. */
  recommended_step: string | null;
  /** TRUE when the answer raised a possible safety problem. */
  raised_safety_concern: boolean | null;
  /** Delivered or Withheld. */
  delivery_disposition: string | null;
  /** TRUE when someone acted on the answer. */
  was_acted_on: boolean | null;
  /** Expert who reviewed the answer before it was used. */
  human_reviewed_by: string | null;
  /** Automation pilot whose output this expert review belongs to. */
  reviewed_for_initiative: string | null;
  /** Expert verdict on the answer. */
  was_correct: boolean | null;
  /** What was wrong, as documented. */
  documented_inaccuracy: string | null;
  /** Completed, Failed or Abandoned. */
  task_outcome: string | null;
  /** Groundings of the answer. */
  grounding_count: number | null;
  /** Groundings in the organization's own assertions or segments. */
  own_knowledge_grounding_count: number | null;
  /** Groundings shown to the person as citations. */
  cited_grounding_count: number | null;
  /** Groundings on stale or deprecated assertions. */
  stale_grounding_count: number | null;
  /** TRUE when a delivered answer rests on nothing from the organization's own procedural knowledge. */
  is_not_from_own_knowledge: boolean | null;
  /** TRUE when a delivered answer was grounded but showed the person none of its sources. */
  is_untraceable_to_source: boolean | null;
  /** Danger cues seen and not escalated on the step under way. */
  context_unescalated_danger_cue_count: number | null;
  /** TRUE when an unescalated danger cue was on record for the step and the answer raised no safety concern. */
  stayed_silent_on_safety_problem: boolean | null;
  /** When the step under way ended. */
  context_step_ended_at: string | null;
  /** TRUE when guidance for a step arrived after the step had already ended. */
  arrived_after_step_ended: boolean | null;
  /** Procedure execution under way. */
  execution_of_context: string | null;
  /** Step under way. */
  context_step: string | null;
  /** Completed runs, in the same execution, of the step the assistant believed it was at. */
  assumed_step_completed_count: number | null;
  /** TRUE when the assistant acted as if a step were done that the execution record shows never completed. */
  lost_track_of_state: boolean | null;
  /** Transitions the model allows from the assumed step to the asserted next step. */
  specified_transition_count: number | null;
  /** TRUE when the assistant asserted a next step the procedure's transition graph does not allow. */
  contradicts_shared_model: boolean | null;
  /** TRUE for a recommendation that names at least one piece of the organization's explicit process knowledge. */
  is_explicitly_grounded_recommendation: boolean | null;
  /** TRUE for a recommendation traceable to no explicit process knowledge. */
  recommendation_rests_on_nothing_explicit: boolean | null;
  /** Regulatory requirements on the recommended step. */
  recommended_step_regulatory_count: number | null;
  /** Requirement checks run on the answer. */
  requirement_check_count: number | null;
  /** Checks that found a conflict. */
  conflict_count: number | null;
  /** TRUE when a check found the recommended action conflicts with an applicable requirement. */
  conflicts_with_regulation: boolean | null;
  /** TRUE for a recommendation on a regulated step that was never checked against its requirements. */
  is_unchecked_regulated_recommendation: boolean | null;
  /** TRUE when the check found a regulatory conflict and the recommendation was delivered anyway. */
  delivered_despite_conflict: boolean | null;
  /** Whether the recommended step requires human confirmation. */
  recommended_step_needs_human: boolean | null;
  /** TRUE when an AI recommendation on a step that requires human judgment was acted on with no expert review. */
  acted_on_without_human_judgment: boolean | null;
  /** TRUE when an authority or safety question was answered from document passages rather than a structured query. */
  answered_compliance_question_from_documents: boolean | null;
  /** TRUE when an authority question answered by interpreting a document passage came back wrong. */
  document_interpretation_erred: boolean | null;
  /** TRUE when an answer that needed inference had its logic produced by the language model, not a reasoner or query. */
  model_did_the_reasoning: boolean | null;
  /** TRUE when a graph-grounded answer was wrong and rested on a stale or deprecated assertion. */
  wrong_because_graph_was_stale: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  /** The organization that owns the procedure this row belongs to, one hop at a time from Procedures.OwnerOrganization. A row policy compares it to the caller's organization, so a plant sign-in never sees the finance close. */
  owner_organization: string | null;
  /** The language model did the reasoning for this answer itself, and the task it was asked about ended in failure. */
  model_reasoned_and_task_failed: boolean | null;
  _erb_errors?: Record<string, string>;
}

const assistantAnswersFieldTypes: Record<string, FieldType> = {
  assistant_answer_id: "string",
  name: "*string",
  answering_agent: "*string",
  asked_by_agent: "*string",
  via_integration: "*string",
  step_execution: "*string",
  asked_at: "*string",
  answered_at: "*string",
  answer_kind: "*string",
  question_topic: "*string",
  question_text: "*string",
  answer_text: "*string",
  retrieval_mode: "*string",
  derivation_performed_by: "*string",
  needs_inference: "*bool",
  assumed_current_step: "*string",
  asserted_next_step: "*string",
  recommended_step: "*string",
  raised_safety_concern: "*bool",
  delivery_disposition: "*string",
  was_acted_on: "*bool",
  human_reviewed_by: "*string",
  reviewed_for_initiative: "*string",
  was_correct: "*bool",
  documented_inaccuracy: "*string",
  task_outcome: "*string",
  grounding_count: "*int",
  own_knowledge_grounding_count: "*int",
  cited_grounding_count: "*int",
  stale_grounding_count: "*int",
  is_not_from_own_knowledge: "*bool",
  is_untraceable_to_source: "*bool",
  context_unescalated_danger_cue_count: "*int",
  stayed_silent_on_safety_problem: "*bool",
  context_step_ended_at: "*string",
  arrived_after_step_ended: "*bool",
  execution_of_context: "*string",
  context_step: "*string",
  assumed_step_completed_count: "*int",
  lost_track_of_state: "*bool",
  specified_transition_count: "*int",
  contradicts_shared_model: "*bool",
  is_explicitly_grounded_recommendation: "*bool",
  recommendation_rests_on_nothing_explicit: "*bool",
  recommended_step_regulatory_count: "*int",
  requirement_check_count: "*int",
  conflict_count: "*int",
  conflicts_with_regulation: "*bool",
  is_unchecked_regulated_recommendation: "*bool",
  delivered_despite_conflict: "*bool",
  recommended_step_needs_human: "*bool",
  acted_on_without_human_judgment: "*bool",
  answered_compliance_question_from_documents: "*bool",
  document_interpretation_erred: "*bool",
  model_did_the_reasoning: "*bool",
  wrong_because_graph_was_stale: "*bool",
  semantic_type_iri: "*string",
  owner_organization: "*string",
  model_reasoned_and_task_failed: "*bool",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{AnsweringAgent}} & ": " & LEFT({{QuestionText}}, 50) */
export function calcAssistantAnswersName(tc: AssistantAnswersRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.answering_agent)), vS(": "), erbText(erbLeft(vStr(tc.question_text), vI(50)))));
}

/** Computes the IsNotFromOwnKnowledge calculated field.
 *  TRUE when a delivered answer rests on nothing from the organization's own procedural knowledge.
 *  Formula: =AND({{DeliveryDisposition}} = "Delivered", {{OwnKnowledgeGroundingCount}} = 0) */
export function calcAssistantAnswersIsNotFromOwnKnowledge(tc: AssistantAnswersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.delivery_disposition)), vS("Delivered"))), erbBool3(erbEq(vInt(tc.own_knowledge_grounding_count), vI(0)))));
}

/** Computes the IsUntraceableToSource calculated field.
 *  TRUE when a delivered answer was grounded but showed the person none of its sources.
 *  Formula: =AND({{DeliveryDisposition}} = "Delivered", {{GroundingCount}} > 0, {{CitedGroundingCount}} = 0) */
export function calcAssistantAnswersIsUntraceableToSource(tc: AssistantAnswersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.delivery_disposition)), vS("Delivered"))), erbBool3(erbCmp(vInt(tc.grounding_count), ">", vI(0))), erbBool3(erbEq(vInt(tc.cited_grounding_count), vI(0)))));
}

/** Computes the StayedSilentOnSafetyProblem calculated field.
 *  TRUE when an unescalated danger cue was on record for the step and the answer raised no safety concern.
 *  Formula: =AND({{ContextUnescalatedDangerCueCount}} > 0, {{RaisedSafetyConcern}} = FALSE) */
export function calcAssistantAnswersStayedSilentOnSafetyProblem(tc: AssistantAnswersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.context_unescalated_danger_cue_count), ">", vI(0))), erbBool3(erbEq(erbNullif(vBool(tc.raised_safety_concern)), vB(false)))));
}

/** Computes the ArrivedAfterStepEnded calculated field.
 *  TRUE when guidance for a step arrived after the step had already ended.
 *  Formula: =AND({{AnswerKind}} = "Guidance", {{ContextStepEndedAt}} <> "", {{AnsweredAt}} > {{ContextStepEndedAt}}) */
export function calcAssistantAnswersArrivedAfterStepEnded(tc: AssistantAnswersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.answer_kind)), vS("Guidance"))), erbBool3(erbIsNotBlank(vStr(tc.context_step_ended_at))), erbBool3(erbCmp(erbNullif(vStr(tc.answered_at)), ">", vStr(tc.context_step_ended_at)))));
}

/** Computes the LostTrackOfState calculated field.
 *  TRUE when the assistant acted as if a step were done that the execution record shows never completed.
 *  Formula: =AND({{AssumedCurrentStep}} <> "", {{ExecutionOfContext}} <> "", {{AssumedStepCompletedCount}} = 0) */
export function calcAssistantAnswersLostTrackOfState(tc: AssistantAnswersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.assumed_current_step))), erbBool3(erbIsNotBlank(vStr(tc.execution_of_context))), erbBool3(erbEq(vInt(tc.assumed_step_completed_count), vI(0)))));
}

/** Computes the ContradictsSharedModel calculated field.
 *  TRUE when the assistant asserted a next step the procedure's transition graph does not allow.
 *  Formula: =AND({{AssertedNextStep}} <> "", {{SpecifiedTransitionCount}} = 0) */
export function calcAssistantAnswersContradictsSharedModel(tc: AssistantAnswersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.asserted_next_step))), erbBool3(erbEq(vInt(tc.specified_transition_count), vI(0)))));
}

/** Computes the IsExplicitlyGroundedRecommendation calculated field.
 *  TRUE for a recommendation that names at least one piece of the organization's explicit process knowledge.
 *  Formula: =AND({{AnswerKind}} = "Recommendation", {{OwnKnowledgeGroundingCount}} > 0) */
export function calcAssistantAnswersIsExplicitlyGroundedRecommendation(tc: AssistantAnswersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.answer_kind)), vS("Recommendation"))), erbBool3(erbCmp(vInt(tc.own_knowledge_grounding_count), ">", vI(0)))));
}

/** Computes the RecommendationRestsOnNothingExplicit calculated field.
 *  TRUE for a recommendation traceable to no explicit process knowledge.
 *  Formula: =AND({{AnswerKind}} = "Recommendation", {{OwnKnowledgeGroundingCount}} = 0) */
export function calcAssistantAnswersRecommendationRestsOnNothingExplicit(tc: AssistantAnswersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.answer_kind)), vS("Recommendation"))), erbBool3(erbEq(vInt(tc.own_knowledge_grounding_count), vI(0)))));
}

/** Computes the ConflictsWithRegulation calculated field.
 *  TRUE when a check found the recommended action conflicts with an applicable requirement.
 *  Formula: ={{ConflictCount}} > 0 */
export function calcAssistantAnswersConflictsWithRegulation(tc: AssistantAnswersRow): boolean | null {
  return toBoolPtr(erbCmp(vInt(tc.conflict_count), ">", vI(0)));
}

/** Computes the IsUncheckedRegulatedRecommendation calculated field.
 *  TRUE for a recommendation on a regulated step that was never checked against its requirements.
 *  Formula: =AND({{AnswerKind}} = "Recommendation", {{RecommendedStepRegulatoryCount}} > 0, {{RequirementCheckCount}} = 0) */
export function calcAssistantAnswersIsUncheckedRegulatedRecommendation(tc: AssistantAnswersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.answer_kind)), vS("Recommendation"))), erbBool3(erbCmp(vInt(tc.recommended_step_regulatory_count), ">", vI(0))), erbBool3(erbEq(vInt(tc.requirement_check_count), vI(0)))));
}

/** Computes the DeliveredDespiteConflict calculated field.
 *  TRUE when the check found a regulatory conflict and the recommendation was delivered anyway.
 *  Formula: =AND({{ConflictCount}} > 0, {{DeliveryDisposition}} = "Delivered") */
export function calcAssistantAnswersDeliveredDespiteConflict(tc: AssistantAnswersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.conflict_count), ">", vI(0))), erbBool3(erbEq(erbNullif(vStr(tc.delivery_disposition)), vS("Delivered")))));
}

/** Computes the ActedOnWithoutHumanJudgment calculated field.
 *  TRUE when an AI recommendation on a step that requires human judgment was acted on with no expert review.
 *  Formula: =AND({{RecommendedStepNeedsHuman}}, {{WasActedOn}}, {{HumanReviewedBy}} = "") */
export function calcAssistantAnswersActedOnWithoutHumanJudgment(tc: AssistantAnswersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.recommended_step_needs_human)), erbIsTrue(vBool(tc.was_acted_on)), erbBool3(erbIsBlank(vStr(tc.human_reviewed_by)))));
}

/** Computes the AnsweredComplianceQuestionFromDocuments calculated field.
 *  TRUE when an authority or safety question was answered from document passages rather than a structured query.
 *  Formula: =AND(OR({{QuestionTopic}} = "Authority", {{QuestionTopic}} = "Safety"), {{RetrievalMode}} = "DocumentPassage") */
export function calcAssistantAnswersAnsweredComplianceQuestionFromDocuments(tc: AssistantAnswersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.question_topic)), vS("Authority"))), erbBool3(erbEq(erbNullif(vStr(tc.question_topic)), vS("Safety"))))), erbBool3(erbEq(erbNullif(vStr(tc.retrieval_mode)), vS("DocumentPassage")))));
}

/** Computes the DocumentInterpretationErred calculated field.
 *  TRUE when an authority question answered by interpreting a document passage came back wrong.
 *  Formula: =AND({{RetrievalMode}} = "DocumentPassage", {{QuestionTopic}} = "Authority", {{WasCorrect}} = FALSE) */
export function calcAssistantAnswersDocumentInterpretationErred(tc: AssistantAnswersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.retrieval_mode)), vS("DocumentPassage"))), erbBool3(erbEq(erbNullif(vStr(tc.question_topic)), vS("Authority"))), erbBool3(erbEq(erbNullif(vBool(tc.was_correct)), vB(false)))));
}

/** Computes the ModelDidTheReasoning calculated field.
 *  TRUE when an answer that needed inference had its logic produced by the language model, not a reasoner or query.
 *  Formula: =AND({{NeedsInference}}, {{DerivationPerformedBy}} = "LanguageModel") */
export function calcAssistantAnswersModelDidTheReasoning(tc: AssistantAnswersRow): boolean | null {
  return toBoolPtr(erbAnd(erbIsTrue(vBool(tc.needs_inference)), erbBool3(erbEq(erbNullif(vStr(tc.derivation_performed_by)), vS("LanguageModel")))));
}

/** Computes the WrongBecauseGraphWasStale calculated field.
 *  TRUE when a graph-grounded answer was wrong and rested on a stale or deprecated assertion.
 *  Formula: =AND({{RetrievalMode}} = "StructuredQuery", {{WasCorrect}} = FALSE, {{StaleGroundingCount}} > 0) */
export function calcAssistantAnswersWrongBecauseGraphWasStale(tc: AssistantAnswersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.retrieval_mode)), vS("StructuredQuery"))), erbBool3(erbEq(erbNullif(vBool(tc.was_correct)), vB(false))), erbBool3(erbCmp(vInt(tc.stale_grounding_count), ">", vI(0)))));
}

/** Computes the ModelReasonedAndTaskFailed calculated field.
 *  The language model did the reasoning for this answer itself, and the task it was asked about ended in failure.
 *  Formula: =AND({{ModelDidTheReasoning}}, {{TaskOutcome}} = "Failed") */
export function calcAssistantAnswersModelReasonedAndTaskFailed(tc: AssistantAnswersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.model_did_the_reasoning)), erbBool3(erbEq(erbNullif(vStr(tc.task_outcome)), vS("Failed")))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeAssistantAnswers(tc: AssistantAnswersRow): AssistantAnswersRow {
  // Level 1
  calcGuard(tc, assistantAnswersFieldTypes, "name", () => { tc.name = calcAssistantAnswersName(tc); });
  calcGuard(tc, assistantAnswersFieldTypes, "is_not_from_own_knowledge", () => { tc.is_not_from_own_knowledge = calcAssistantAnswersIsNotFromOwnKnowledge(tc); });
  calcGuard(tc, assistantAnswersFieldTypes, "is_untraceable_to_source", () => { tc.is_untraceable_to_source = calcAssistantAnswersIsUntraceableToSource(tc); });
  calcGuard(tc, assistantAnswersFieldTypes, "stayed_silent_on_safety_problem", () => { tc.stayed_silent_on_safety_problem = calcAssistantAnswersStayedSilentOnSafetyProblem(tc); });
  calcGuard(tc, assistantAnswersFieldTypes, "arrived_after_step_ended", () => { tc.arrived_after_step_ended = calcAssistantAnswersArrivedAfterStepEnded(tc); });
  calcGuard(tc, assistantAnswersFieldTypes, "lost_track_of_state", () => { tc.lost_track_of_state = calcAssistantAnswersLostTrackOfState(tc); });
  calcGuard(tc, assistantAnswersFieldTypes, "contradicts_shared_model", () => { tc.contradicts_shared_model = calcAssistantAnswersContradictsSharedModel(tc); });
  calcGuard(tc, assistantAnswersFieldTypes, "is_explicitly_grounded_recommendation", () => { tc.is_explicitly_grounded_recommendation = calcAssistantAnswersIsExplicitlyGroundedRecommendation(tc); });
  calcGuard(tc, assistantAnswersFieldTypes, "recommendation_rests_on_nothing_explicit", () => { tc.recommendation_rests_on_nothing_explicit = calcAssistantAnswersRecommendationRestsOnNothingExplicit(tc); });
  calcGuard(tc, assistantAnswersFieldTypes, "conflicts_with_regulation", () => { tc.conflicts_with_regulation = calcAssistantAnswersConflictsWithRegulation(tc); });
  calcGuard(tc, assistantAnswersFieldTypes, "is_unchecked_regulated_recommendation", () => { tc.is_unchecked_regulated_recommendation = calcAssistantAnswersIsUncheckedRegulatedRecommendation(tc); });
  calcGuard(tc, assistantAnswersFieldTypes, "delivered_despite_conflict", () => { tc.delivered_despite_conflict = calcAssistantAnswersDeliveredDespiteConflict(tc); });
  calcGuard(tc, assistantAnswersFieldTypes, "acted_on_without_human_judgment", () => { tc.acted_on_without_human_judgment = calcAssistantAnswersActedOnWithoutHumanJudgment(tc); });
  calcGuard(tc, assistantAnswersFieldTypes, "answered_compliance_question_from_documents", () => { tc.answered_compliance_question_from_documents = calcAssistantAnswersAnsweredComplianceQuestionFromDocuments(tc); });
  calcGuard(tc, assistantAnswersFieldTypes, "document_interpretation_erred", () => { tc.document_interpretation_erred = calcAssistantAnswersDocumentInterpretationErred(tc); });
  calcGuard(tc, assistantAnswersFieldTypes, "model_did_the_reasoning", () => { tc.model_did_the_reasoning = calcAssistantAnswersModelDidTheReasoning(tc); });
  calcGuard(tc, assistantAnswersFieldTypes, "wrong_because_graph_was_stale", () => { tc.wrong_because_graph_was_stale = calcAssistantAnswersWrongBecauseGraphWasStale(tc); });
  // Level 2
  calcGuard(tc, assistantAnswersFieldTypes, "model_reasoned_and_task_failed", () => { tc.model_reasoned_and_task_failed = calcAssistantAnswersModelReasonedAndTaskFailed(tc); });
  return tc;
}

/** Reads AssistantAnswers rows from a JSON array file. */
export function loadAssistantAnswersRows(file: string): AssistantAnswersRow[] {
  return loadRows(file, { fields: assistantAnswersFieldTypes }) as unknown as AssistantAnswersRow[];
}

// =============================================================================
// ANSWERGROUNDINGS TABLE
// Which served assertion, segment or external source grounded an assistant answer, and whether it was cited.
// =============================================================================

/** A row in the AnswerGroundings table. */
export interface AnswerGroundingsRow {
  /** Stored identifier. */
  answer_grounding_id: string;
  /** Display name. */
  name: string | null;
  /** Answer. */
  assistant_answer: string | null;
  /** Served assertion. */
  snapshot_assertion: string | null;
  /** Retrieved segment. */
  retrieval_segment: string | null;
  /** External content outside the organization's knowledge. */
  external_source_uri: string | null;
  /** TRUE when shown to the person as a citation. */
  cited_to_user: boolean | null;
  /** TRUE when the grounding is the organization's own assertion or segment. */
  is_from_own_knowledge: boolean | null;
  /** Whether the assertion rests on an ended role assignment. */
  assertion_is_stale: boolean | null;
  /** Whether the assertion presents a deprecated version as current. */
  assertion_presents_deprecated: boolean | null;
  /** TRUE when the grounding assertion is stale or deprecated. */
  grounds_on_stale_assertion: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const answerGroundingsFieldTypes: Record<string, FieldType> = {
  answer_grounding_id: "string",
  name: "*string",
  assistant_answer: "*string",
  snapshot_assertion: "*string",
  retrieval_segment: "*string",
  external_source_uri: "*string",
  cited_to_user: "*bool",
  is_from_own_knowledge: "*bool",
  assertion_is_stale: "*bool",
  assertion_presents_deprecated: "*bool",
  grounds_on_stale_assertion: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{AssistantAnswer}} & " <- " & {{SnapshotAssertion}} & {{RetrievalSegment}} & {{ExternalSourceUri}} */
export function calcAnswerGroundingsName(tc: AnswerGroundingsRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.assistant_answer)), vS(" <- "), erbText(vStr(tc.snapshot_assertion)), erbText(vStr(tc.retrieval_segment)), erbText(vStr(tc.external_source_uri))));
}

/** Computes the IsFromOwnKnowledge calculated field.
 *  TRUE when the grounding is the organization's own assertion or segment.
 *  Formula: =AND({{ExternalSourceUri}} = "", OR({{SnapshotAssertion}} <> "", {{RetrievalSegment}} <> "")) */
export function calcAnswerGroundingsIsFromOwnKnowledge(tc: AnswerGroundingsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsBlank(vStr(tc.external_source_uri))), erbBool3(erbOr(erbBool3(erbIsNotBlank(vStr(tc.snapshot_assertion))), erbBool3(erbIsNotBlank(vStr(tc.retrieval_segment)))))));
}

/** Computes the GroundsOnStaleAssertion calculated field.
 *  TRUE when the grounding assertion is stale or deprecated.
 *  Formula: =AND({{SnapshotAssertion}} <> "", OR({{AssertionIsStale}}, {{AssertionPresentsDeprecated}})) */
export function calcAnswerGroundingsGroundsOnStaleAssertion(tc: AnswerGroundingsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.snapshot_assertion))), erbBool3(erbOr(erbBool3(vBool(tc.assertion_is_stale)), erbBool3(vBool(tc.assertion_presents_deprecated))))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeAnswerGroundings(tc: AnswerGroundingsRow): AnswerGroundingsRow {
  // Level 1
  calcGuard(tc, answerGroundingsFieldTypes, "name", () => { tc.name = calcAnswerGroundingsName(tc); });
  calcGuard(tc, answerGroundingsFieldTypes, "is_from_own_knowledge", () => { tc.is_from_own_knowledge = calcAnswerGroundingsIsFromOwnKnowledge(tc); });
  calcGuard(tc, answerGroundingsFieldTypes, "grounds_on_stale_assertion", () => { tc.grounds_on_stale_assertion = calcAnswerGroundingsGroundsOnStaleAssertion(tc); });
  return tc;
}

/** Reads AnswerGroundings rows from a JSON array file. */
export function loadAnswerGroundingsRows(file: string): AnswerGroundingsRow[] {
  return loadRows(file, { fields: answerGroundingsFieldTypes }) as unknown as AnswerGroundingsRow[];
}

