// AITOOLINVOCATIONS TABLE
// A tool or function an AI agent invoked during a step execution, with the inputs it supplied.
// =============================================================================

/** A row in the AiToolInvocations table. */
export interface AiToolInvocationsRow {
  /** Stored identifier. */
  ai_tool_invocation_id: string;
  /** Display name. */
  name: string | null;
  /** AI agent. */
  invoking_agent: string | null;
  /** Step execution. */
  step_execution: string | null;
  /** Function invoked. */
  function: string | null;
  /** When. */
  invoked_at: string | null;
  /** Declared inputs the agent actually supplied. */
  supplied_input_count: number | null;
  /** Step being executed. */
  executed_step: string | null;
  /** Declarations of this function on the executed step. */
  declared_function_count: number | null;
  /** TRUE when an AI agent used a tool the process graph does not declare on that step. */
  is_undeclared_tool_use: boolean | null;
  /** Inputs the step declares. */
  declared_input_count: number | null;
  /** TRUE when the agent acted with fewer of the step's declared inputs than the step needs. */
  acted_without_declared_context: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const aiToolInvocationsFieldTypes: Record<string, FieldType> = {
  ai_tool_invocation_id: "string",
  name: "*string",
  invoking_agent: "*string",
  step_execution: "*string",
  function: "*string",
  invoked_at: "*string",
  supplied_input_count: "*int",
  executed_step: "*string",
  declared_function_count: "*int",
  is_undeclared_tool_use: "*bool",
  declared_input_count: "*int",
  acted_without_declared_context: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{InvokingAgent}} & " -> " & {{Function}} */
export function calcAiToolInvocationsName(tc: AiToolInvocationsRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.invoking_agent)), vS(" -> "), erbText(vStr(tc.function))));
}

/** Computes the IsUndeclaredToolUse calculated field.
 *  TRUE when an AI agent used a tool the process graph does not declare on that step.
 *  Formula: ={{DeclaredFunctionCount}} = 0 */
export function calcAiToolInvocationsIsUndeclaredToolUse(tc: AiToolInvocationsRow): boolean | null {
  return toBoolPtr(erbEq(vInt(tc.declared_function_count), vI(0)));
}

/** Computes the ActedWithoutDeclaredContext calculated field.
 *  TRUE when the agent acted with fewer of the step's declared inputs than the step needs.
 *  Formula: =AND({{DeclaredInputCount}} > 0, {{SuppliedInputCount}} < {{DeclaredInputCount}}) */
export function calcAiToolInvocationsActedWithoutDeclaredContext(tc: AiToolInvocationsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.declared_input_count), ">", vI(0))), erbBool3(erbCmp(erbNullif(vInt(tc.supplied_input_count)), "<", vInt(tc.declared_input_count)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeAiToolInvocations(tc: AiToolInvocationsRow): AiToolInvocationsRow {
  // Level 1
  calcGuard(tc, aiToolInvocationsFieldTypes, "name", () => { tc.name = calcAiToolInvocationsName(tc); });
  calcGuard(tc, aiToolInvocationsFieldTypes, "is_undeclared_tool_use", () => { tc.is_undeclared_tool_use = calcAiToolInvocationsIsUndeclaredToolUse(tc); });
  calcGuard(tc, aiToolInvocationsFieldTypes, "acted_without_declared_context", () => { tc.acted_without_declared_context = calcAiToolInvocationsActedWithoutDeclaredContext(tc); });
  return tc;
}

/** Reads AiToolInvocations rows from a JSON array file. */
export function loadAiToolInvocationsRows(file: string): AiToolInvocationsRow[] {
  return loadRows(file, { fields: aiToolInvocationsFieldTypes }) as unknown as AiToolInvocationsRow[];
}

// =============================================================================
// EMBEDDINGPROBES TABLE
// Recorded similarity of process-vocabulary term pairs under an embedding model.
// =============================================================================

/** A row in the EmbeddingProbes table. */
export interface EmbeddingProbesRow {
  /** Stored identifier. */
  embedding_probe_id: string;
  /** Display name. */
  name: string | null;
  /** First term. */
  term_a: string | null;
  /** Second term. */
  term_b: string | null;
  /** NearSynonym or Opposite in the process domain. */
  expected_relation: string | null;
  /** Embedding model probed. */
  embedding_model: string | null;
  /** Measured cosine similarity. */
  cosine_similarity: number | null;
  /** When. */
  probed_at: string | null;
  /** TRUE when the model places near-synonyms of the process domain below 0.7 similarity. */
  synonyms_not_similar: boolean | null;
  /** TRUE when the model places opposites of the process domain above 0.3 similarity. */
  opposites_not_opposed: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const embeddingProbesFieldTypes: Record<string, FieldType> = {
  embedding_probe_id: "string",
  name: "*string",
  term_a: "*string",
  term_b: "*string",
  expected_relation: "*string",
  embedding_model: "*string",
  cosine_similarity: "*float64",
  probed_at: "*string",
  synonyms_not_similar: "*bool",
  opposites_not_opposed: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{TermA}} & " / " & {{TermB}} & " @ " & {{EmbeddingModel}} */
export function calcEmbeddingProbesName(tc: EmbeddingProbesRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.term_a)), vS(" / "), erbText(vStr(tc.term_b)), vS(" @ "), erbText(vStr(tc.embedding_model))));
}

/** Computes the SynonymsNotSimilar calculated field.
 *  TRUE when the model places near-synonyms of the process domain below 0.7 similarity.
 *  Formula: =AND({{ExpectedRelation}} = "NearSynonym", {{CosineSimilarity}} < 0.7) */
export function calcEmbeddingProbesSynonymsNotSimilar(tc: EmbeddingProbesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.expected_relation)), vS("NearSynonym"))), erbBool3(erbCmp(erbNullif(vNum(tc.cosine_similarity)), "<", vF(0.7)))));
}

/** Computes the OppositesNotOpposed calculated field.
 *  TRUE when the model places opposites of the process domain above 0.3 similarity.
 *  Formula: =AND({{ExpectedRelation}} = "Opposite", {{CosineSimilarity}} > 0.3) */
export function calcEmbeddingProbesOppositesNotOpposed(tc: EmbeddingProbesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.expected_relation)), vS("Opposite"))), erbBool3(erbCmp(erbNullif(vNum(tc.cosine_similarity)), ">", vF(0.3)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeEmbeddingProbes(tc: EmbeddingProbesRow): EmbeddingProbesRow {
  // Level 1
  calcGuard(tc, embeddingProbesFieldTypes, "name", () => { tc.name = calcEmbeddingProbesName(tc); });
  calcGuard(tc, embeddingProbesFieldTypes, "synonyms_not_similar", () => { tc.synonyms_not_similar = calcEmbeddingProbesSynonymsNotSimilar(tc); });
  calcGuard(tc, embeddingProbesFieldTypes, "opposites_not_opposed", () => { tc.opposites_not_opposed = calcEmbeddingProbesOppositesNotOpposed(tc); });
  return tc;
}

/** Reads EmbeddingProbes rows from a JSON array file. */
export function loadEmbeddingProbesRows(file: string): EmbeddingProbesRow[] {
  return loadRows(file, { fields: embeddingProbesFieldTypes }) as unknown as EmbeddingProbesRow[];
}

// =============================================================================
// PROMPTTEMPLATES TABLE
// Prompts and system instructions that carry process knowledge to AI, layered and kept in a library.
// =============================================================================

/** A row in the PromptTemplates table. */
export interface PromptTemplatesRow {
  /** Stored identifier. */
  prompt_template_id: string;
  /** Display name. */
  name: string | null;
  /** Prompt. */
  label: string | null;
  /** Framework, ProcedureDetail or AdHocContext. */
  layer: string | null;
  /** The framework layer this detail layer is pulled into. */
  parent_template: string | null;
  /** Procedure version the prompt's knowledge was drawn from. */
  source_procedure_version: string | null;
  /** Maintained or Unmanaged. */
  library_status: string | null;
  /** Role maintaining the prompt. */
  maintained_by_role: string | null;
  /** AI agent using the prompt. */
  used_by_agent: string | null;
  /** TRUE when the prompt tells the AI how to carry out a procedure. */
  carries_procedure_instructions: boolean | null;
  /** TRUE when the prompt inlines detail needed only in rare cases. */
  includes_rare_detail: boolean | null;
  /** Tokens allowed. */
  token_budget: number | null;
  /** Tokens used. */
  estimated_tokens: number | null;
  /** Tokens in the source knowledge the prompt was made from. */
  source_token_count: number | null;
  /** Detail layers pulled into this one. */
  child_template_count: number | null;
  /** TRUE when a prompt carries procedure instructions that exist in no procedure version of the model. */
  is_disconnected_prompt_knowledge: boolean | null;
  /** TRUE when an agent uses a prompt nobody maintains in the library. */
  is_unmanaged_prompt_in_use: boolean | null;
  /** TRUE when a prompt inlines rarely needed detail and so exceeds its token budget. */
  spends_budget_on_rare_detail: boolean | null;
  /** Prompt size as a share of the source knowledge. */
  condensation_percent: number | null;
  /** TRUE when a prompt pastes its source at 90% or more of its size instead of codifying and condensing it. */
  is_verbatim_dump: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const promptTemplatesFieldTypes: Record<string, FieldType> = {
  prompt_template_id: "string",
  name: "*string",
  label: "*string",
  layer: "*string",
  parent_template: "*string",
  source_procedure_version: "*string",
  library_status: "*string",
  maintained_by_role: "*string",
  used_by_agent: "*string",
  carries_procedure_instructions: "*bool",
  includes_rare_detail: "*bool",
  token_budget: "*int",
  estimated_tokens: "*int",
  source_token_count: "*int",
  child_template_count: "*int",
  is_disconnected_prompt_knowledge: "*bool",
  is_unmanaged_prompt_in_use: "*bool",
  spends_budget_on_rare_detail: "*bool",
  condensation_percent: "*float64",
  is_verbatim_dump: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{Label}} */
export function calcPromptTemplatesName(tc: PromptTemplatesRow): string | null {
  return toStringPtr(vStr(tc.label));
}

/** Computes the IsDisconnectedPromptKnowledge calculated field.
 *  TRUE when a prompt carries procedure instructions that exist in no procedure version of the model.
 *  Formula: =AND({{CarriesProcedureInstructions}}, {{SourceProcedureVersion}} = "") */
export function calcPromptTemplatesIsDisconnectedPromptKnowledge(tc: PromptTemplatesRow): boolean | null {
  return toBoolPtr(erbAnd(erbIsTrue(vBool(tc.carries_procedure_instructions)), erbBool3(erbIsBlank(vStr(tc.source_procedure_version)))));
}

/** Computes the IsUnmanagedPromptInUse calculated field.
 *  TRUE when an agent uses a prompt nobody maintains in the library.
 *  Formula: =AND({{UsedByAgent}} <> "", OR({{LibraryStatus}} <> "Maintained", {{MaintainedByRole}} = "")) */
export function calcPromptTemplatesIsUnmanagedPromptInUse(tc: PromptTemplatesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.used_by_agent))), erbBool3(erbOr(erbBool3(erbNe(erbNullif(vStr(tc.library_status)), vS("Maintained"))), erbBool3(erbIsBlank(vStr(tc.maintained_by_role)))))));
}

/** Computes the SpendsBudgetOnRareDetail calculated field.
 *  TRUE when a prompt inlines rarely needed detail and so exceeds its token budget.
 *  Formula: =AND({{IncludesRareDetail}}, {{EstimatedTokens}} > {{TokenBudget}}) */
export function calcPromptTemplatesSpendsBudgetOnRareDetail(tc: PromptTemplatesRow): boolean | null {
  return toBoolPtr(erbAnd(erbIsTrue(vBool(tc.includes_rare_detail)), erbBool3(erbCmp(erbNullif(vInt(tc.estimated_tokens)), ">", erbNullif(vInt(tc.token_budget))))));
}

/** Computes the CondensationPercent calculated field.
 *  Prompt size as a share of the source knowledge.
 *  Formula: =IF({{SourceTokenCount}} = 0, 0, ROUND(100 * {{EstimatedTokens}} / {{SourceTokenCount}}, 1)) */
export function calcPromptTemplatesCondensationPercent(tc: PromptTemplatesRow): number | null {
  return toFloatPtr(erbIf(erbBool3(erbEq(erbNullif(vInt(tc.source_token_count)), vI(0))), () => vI(0), () => erbRound(erbDiv(erbMul(vI(100), vInt(tc.estimated_tokens)), vInt(tc.source_token_count)), vI(1))));
}

/** Computes the IsVerbatimDump calculated field.
 *  TRUE when a prompt pastes its source at 90% or more of its size instead of codifying and condensing it.
 *  Formula: =AND({{SourceTokenCount}} > 0, {{CondensationPercent}} >= 90) */
export function calcPromptTemplatesIsVerbatimDump(tc: PromptTemplatesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbCmp(erbNullif(vInt(tc.source_token_count)), ">", vI(0))), erbBool3(erbCmp(vNum(tc.condensation_percent), ">=", vI(90)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computePromptTemplates(tc: PromptTemplatesRow): PromptTemplatesRow {
  // Level 1
  calcGuard(tc, promptTemplatesFieldTypes, "name", () => { tc.name = calcPromptTemplatesName(tc); });
  calcGuard(tc, promptTemplatesFieldTypes, "is_disconnected_prompt_knowledge", () => { tc.is_disconnected_prompt_knowledge = calcPromptTemplatesIsDisconnectedPromptKnowledge(tc); });
  calcGuard(tc, promptTemplatesFieldTypes, "is_unmanaged_prompt_in_use", () => { tc.is_unmanaged_prompt_in_use = calcPromptTemplatesIsUnmanagedPromptInUse(tc); });
  calcGuard(tc, promptTemplatesFieldTypes, "spends_budget_on_rare_detail", () => { tc.spends_budget_on_rare_detail = calcPromptTemplatesSpendsBudgetOnRareDetail(tc); });
  calcGuard(tc, promptTemplatesFieldTypes, "condensation_percent", () => { tc.condensation_percent = calcPromptTemplatesCondensationPercent(tc); });
  // Level 2
  calcGuard(tc, promptTemplatesFieldTypes, "is_verbatim_dump", () => { tc.is_verbatim_dump = calcPromptTemplatesIsVerbatimDump(tc); });
  return tc;
}

/** Reads PromptTemplates rows from a JSON array file. */
export function loadPromptTemplatesRows(file: string): PromptTemplatesRow[] {
  return loadRows(file, { fields: promptTemplatesFieldTypes }) as unknown as PromptTemplatesRow[];
}

