  /** TRUE for a diagram drawn by hand or generated before the version last changed. */
  diagram_can_diverge_from_model: boolean | null;
  /** TRUE for narrative documentation written by hand or generated before the version last changed. */
  narrative_not_generated_from_model: boolean | null;
  /** TRUE for narrative documentation that is published nowhere and has never been opened. */
  narrative_unreachable: boolean | null;
  /** TRUE when stakeholders can open the projection. */
  is_published: boolean | null;
  /** Semantic type IRI. */
