const knowledgeProjectionsFieldTypes: Record<string, FieldType> = {
  knowledge_projection_id: "string",
  name: "*string",
  label: "*string",
  projection_kind: "*string",
  notation: "*string",
  procedure_version: "*string",
  output_path: "*string",
  generated_by_tool: "*string",
  generated_at: "*string",
  published_uri: "*string",
  audience_role: "*string",
  version_modified_at: "*string",
  open_count: "*int",
  diagram_can_diverge_from_model: "*bool",
  narrative_not_generated_from_model: "*bool",
  narrative_unreachable: "*bool",
  is_published: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{Label}} */
export function calcKnowledgeProjectionsName(tc: KnowledgeProjectionsRow): string | null {
  return toStringPtr(vStr(tc.label));
}

/** Computes the DiagramCanDivergeFromModel calculated field.
 *  TRUE for a diagram drawn by hand or generated before the version last changed.
 *  Formula: =AND({{ProjectionKind}} = "Diagram", OR({{GeneratedByTool}} = "", {{GeneratedAt}} < {{VersionModifiedAt}})) */
export function calcKnowledgeProjectionsDiagramCanDivergeFromModel(tc: KnowledgeProjectionsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.projection_kind)), vS("Diagram"))), erbBool3(erbOr(erbBool3(erbIsBlank(vStr(tc.generated_by_tool))), erbBool3(erbCmp(erbNullif(vStr(tc.generated_at)), "<", vStr(tc.version_modified_at)))))));
}

/** Computes the NarrativeNotGeneratedFromModel calculated field.
 *  TRUE for narrative documentation written by hand or generated before the version last changed.
 *  Formula: =AND({{ProjectionKind}} = "Narrative", OR({{GeneratedByTool}} = "", {{GeneratedAt}} < {{VersionModifiedAt}})) */
export function calcKnowledgeProjectionsNarrativeNotGeneratedFromModel(tc: KnowledgeProjectionsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.projection_kind)), vS("Narrative"))), erbBool3(erbOr(erbBool3(erbIsBlank(vStr(tc.generated_by_tool))), erbBool3(erbCmp(erbNullif(vStr(tc.generated_at)), "<", vStr(tc.version_modified_at)))))));
}

/** Computes the NarrativeUnreachable calculated field.
 *  TRUE for narrative documentation that is published nowhere and has never been opened.
 *  Formula: =AND({{ProjectionKind}} = "Narrative", {{PublishedUri}} = "", {{OpenCount}} = 0) */
export function calcKnowledgeProjectionsNarrativeUnreachable(tc: KnowledgeProjectionsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.projection_kind)), vS("Narrative"))), erbBool3(erbIsBlank(vStr(tc.published_uri))), erbBool3(erbEq(vInt(tc.open_count), vI(0)))));
}

/** Computes the IsPublished calculated field.
 *  TRUE when stakeholders can open the projection.
 *  Formula: ={{PublishedUri}} <> "" */
export function calcKnowledgeProjectionsIsPublished(tc: KnowledgeProjectionsRow): boolean | null {
  return toBoolPtr(erbIsNotBlank(vStr(tc.published_uri)));
}

/** Computes every calculated field of the row in dependency order. */
export function computeKnowledgeProjections(tc: KnowledgeProjectionsRow): KnowledgeProjectionsRow {
  // Level 1
  calcGuard(tc, knowledgeProjectionsFieldTypes, "name", () => { tc.name = calcKnowledgeProjectionsName(tc); });
  calcGuard(tc, knowledgeProjectionsFieldTypes, "diagram_can_diverge_from_model", () => { tc.diagram_can_diverge_from_model = calcKnowledgeProjectionsDiagramCanDivergeFromModel(tc); });
  calcGuard(tc, knowledgeProjectionsFieldTypes, "narrative_not_generated_from_model", () => { tc.narrative_not_generated_from_model = calcKnowledgeProjectionsNarrativeNotGeneratedFromModel(tc); });
  calcGuard(tc, knowledgeProjectionsFieldTypes, "narrative_unreachable", () => { tc.narrative_unreachable = calcKnowledgeProjectionsNarrativeUnreachable(tc); });
  calcGuard(tc, knowledgeProjectionsFieldTypes, "is_published", () => { tc.is_published = calcKnowledgeProjectionsIsPublished(tc); });
  return tc;
}

/** Reads KnowledgeProjections rows from a JSON array file. */
export function loadKnowledgeProjectionsRows(file: string): KnowledgeProjectionsRow[] {
  return loadRows(file, { fields: knowledgeProjectionsFieldTypes }) as unknown as KnowledgeProjectionsRow[];
}

// =============================================================================
// MODELANNOTATIONS TABLE
// Comments, questions, suggestions, alternative interpretations, outdated flags and new or missing knowledge practitioners attach to the model.
// =============================================================================

/** A row in the ModelAnnotations table. */
export interface ModelAnnotationsRow {
  /** Stored identifier. */
  model_annotation_id: string;
  /** Display name. */
  name: string | null;
  /** Version annotated. */
  procedure_version: string | null;
  /** Step annotated. */
  step: string | null;
  /** Who annotated. */
  annotated_by_agent: string | null;
  /** When. */
  annotated_at: string | null;
  /** Comment, Question, Suggestion, AlternativeInterpretation, FlagOutdated, NewKnowledge or MissingKnowledge. */
  annotation_kind: string | null;
  /** The annotation. */
  body: string | null;
  /** Open, Accepted or Declined. */
  status: string | null;
  /** AnnotationPanel or EmailToSteward. */
  entered_through: string | null;
  /** AnnotationLayer or AuthoritativeRulebook. */
  stored_in: string | null;
  /** Lifecycle stage the feedback concerns. */
  lifecycle_stage: string | null;
  /** Knowledge fragment new knowledge became. */
  promoted_to_fragment: string | null;
  /** Knowledge gap a missing-knowledge report became. */
  raised_knowledge_gap: string | null;
  /** TRUE when a comment, question, suggestion or alternative reading was written into the authoritative rulebook. */
  is_discussion_in_authoritative_model: boolean | null;
  /** TRUE when a practitioner had to flag outdated guidance outside the annotation interface. */
  flag_bypassed_annotation_interface: boolean | null;
  /** TRUE when new knowledge a practitioner added was not declined and never became a knowledge fragment. */
  is_lost_new_knowledge: boolean | null;
  /** TRUE when friction from missing knowledge was reported and never recorded as a knowledge gap. */
  is_friction_without_gap: boolean | null;
  /** TRUE for guidance a practitioner flagged as outdated that is still open. */
  is_open_outdated_flag: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const modelAnnotationsFieldTypes: Record<string, FieldType> = {
  model_annotation_id: "string",
  name: "*string",
  procedure_version: "*string",
  step: "*string",
  annotated_by_agent: "*string",
  annotated_at: "*string",
  annotation_kind: "*string",
  body: "*string",
  status: "*string",
  entered_through: "*string",
  stored_in: "*string",
  lifecycle_stage: "*string",
  promoted_to_fragment: "*string",
  raised_knowledge_gap: "*string",
  is_discussion_in_authoritative_model: "*bool",
  flag_bypassed_annotation_interface: "*bool",
  is_lost_new_knowledge: "*bool",
  is_friction_without_gap: "*bool",
  is_open_outdated_flag: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{AnnotationKind}} & ": " & LEFT({{Body}}, 50) */
export function calcModelAnnotationsName(tc: ModelAnnotationsRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.annotation_kind)), vS(": "), erbText(erbLeft(vStr(tc.body), vI(50)))));
}

/** Computes the IsDiscussionInAuthoritativeModel calculated field.
 *  TRUE when a comment, question, suggestion or alternative reading was written into the authoritative rulebook.
 *  Formula: =AND(OR({{AnnotationKind}} = "Comment", {{AnnotationKind}} = "Question", {{AnnotationKind}} = "Suggestion", {{AnnotationKind}} = "AlternativeInterpretation"), {{StoredIn}} = "AuthoritativeRulebook") */
export function calcModelAnnotationsIsDiscussionInAuthoritativeModel(tc: ModelAnnotationsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.annotation_kind)), vS("Comment"))), erbBool3(erbEq(erbNullif(vStr(tc.annotation_kind)), vS("Question"))), erbBool3(erbEq(erbNullif(vStr(tc.annotation_kind)), vS("Suggestion"))), erbBool3(erbEq(erbNullif(vStr(tc.annotation_kind)), vS("AlternativeInterpretation"))))), erbBool3(erbEq(erbNullif(vStr(tc.stored_in)), vS("AuthoritativeRulebook")))));
}

/** Computes the FlagBypassedAnnotationInterface calculated field.
 *  TRUE when a practitioner had to flag outdated guidance outside the annotation interface.
 *  Formula: =AND({{AnnotationKind}} = "FlagOutdated", {{EnteredThrough}} <> "AnnotationPanel") */
export function calcModelAnnotationsFlagBypassedAnnotationInterface(tc: ModelAnnotationsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.annotation_kind)), vS("FlagOutdated"))), erbBool3(erbNe(erbNullif(vStr(tc.entered_through)), vS("AnnotationPanel")))));
}

/** Computes the IsLostNewKnowledge calculated field.
 *  TRUE when new knowledge a practitioner added was not declined and never became a knowledge fragment.
 *  Formula: =AND({{AnnotationKind}} = "NewKnowledge", {{Status}} <> "Declined", {{PromotedToFragment}} = "") */
export function calcModelAnnotationsIsLostNewKnowledge(tc: ModelAnnotationsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.annotation_kind)), vS("NewKnowledge"))), erbBool3(erbNe(erbNullif(vStr(tc.status)), vS("Declined"))), erbBool3(erbIsBlank(vStr(tc.promoted_to_fragment)))));
}

/** Computes the IsFrictionWithoutGap calculated field.
 *  TRUE when friction from missing knowledge was reported and never recorded as a knowledge gap.
 *  Formula: =AND({{AnnotationKind}} = "MissingKnowledge", {{RaisedKnowledgeGap}} = "") */
export function calcModelAnnotationsIsFrictionWithoutGap(tc: ModelAnnotationsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.annotation_kind)), vS("MissingKnowledge"))), erbBool3(erbIsBlank(vStr(tc.raised_knowledge_gap)))));
}

/** Computes the IsOpenOutdatedFlag calculated field.
 *  TRUE for guidance a practitioner flagged as outdated that is still open.
 *  Formula: =AND({{AnnotationKind}} = "FlagOutdated", {{Status}} = "Open") */
export function calcModelAnnotationsIsOpenOutdatedFlag(tc: ModelAnnotationsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.annotation_kind)), vS("FlagOutdated"))), erbBool3(erbEq(erbNullif(vStr(tc.status)), vS("Open")))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeModelAnnotations(tc: ModelAnnotationsRow): ModelAnnotationsRow {
  // Level 1
  calcGuard(tc, modelAnnotationsFieldTypes, "name", () => { tc.name = calcModelAnnotationsName(tc); });
  calcGuard(tc, modelAnnotationsFieldTypes, "is_discussion_in_authoritative_model", () => { tc.is_discussion_in_authoritative_model = calcModelAnnotationsIsDiscussionInAuthoritativeModel(tc); });
  calcGuard(tc, modelAnnotationsFieldTypes, "flag_bypassed_annotation_interface", () => { tc.flag_bypassed_annotation_interface = calcModelAnnotationsFlagBypassedAnnotationInterface(tc); });
  calcGuard(tc, modelAnnotationsFieldTypes, "is_lost_new_knowledge", () => { tc.is_lost_new_knowledge = calcModelAnnotationsIsLostNewKnowledge(tc); });
  calcGuard(tc, modelAnnotationsFieldTypes, "is_friction_without_gap", () => { tc.is_friction_without_gap = calcModelAnnotationsIsFrictionWithoutGap(tc); });
  calcGuard(tc, modelAnnotationsFieldTypes, "is_open_outdated_flag", () => { tc.is_open_outdated_flag = calcModelAnnotationsIsOpenOutdatedFlag(tc); });
  return tc;
}

/** Reads ModelAnnotations rows from a JSON array file. */
export function loadModelAnnotationsRows(file: string): ModelAnnotationsRow[] {
  return loadRows(file, { fields: modelAnnotationsFieldTypes }) as unknown as ModelAnnotationsRow[];
}

// =============================================================================
// KNOWLEDGESEARCHEVENTS TABLE
// Searches and retrievals against the knowledge, by people and AI, with what they found and when they gave up.
// =============================================================================

/** A row in the KnowledgeSearchEvents table. */
export interface KnowledgeSearchEventsRow {
  /** Stored identifier. */
  knowledge_search_event_id: string;
  /** Display name. */
  name: string | null;
  /** Who searched. */
  searched_by_agent: string | null;
  /** When. */
  searched_at: string | null;
  /** RegisterSearch, TabletSearch or AssistantRetrieval. */
  channel: string | null;
  /** What was searched for. */
  query_text: string | null;
  /** Version the searcher was working with. */
  sought_procedure_version: string | null;
  /** Results returned. */
  result_count: number | null;
  /** Segment opened. */
  opened_segment: string | null;
  /** Document or diagram opened. */
  opened_projection: string | null;
  /** TRUE when the searcher gave up. */
  was_abandoned: boolean | null;
  /** Seconds before giving up. */
  seconds_before_abandoning: number | null;
  /** Time spent with what was found. */
  dwell_seconds: number | null;
  /** Knowledge gap the failed search was linked to. */
  linked_knowledge_gap: string | null;
  /** Usability barrier the failed search was linked to. */
  linked_usability_barrier: string | null;
  /** TRUE when a search returned nothing or nothing was opened. */
  found_nothing_useful: boolean | null;
  /** TRUE when the searcher abandoned the query after results came back. */
  gave_up_after_seeing_results: boolean | null;
  /** TRUE when a search that found nothing useful is linked to no knowledge gap and no usability barrier. */
  is_unlinked_failed_search: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const knowledgeSearchEventsFieldTypes: Record<string, FieldType> = {
  knowledge_search_event_id: "string",
  name: "*string",
  searched_by_agent: "*string",
  searched_at: "*string",
  channel: "*string",
  query_text: "*string",
  sought_procedure_version: "*string",
  result_count: "*int",
  opened_segment: "*string",
  opened_projection: "*string",
  was_abandoned: "*bool",
  seconds_before_abandoning: "*float64",
  dwell_seconds: "*float64",
  linked_knowledge_gap: "*string",
  linked_usability_barrier: "*string",
  found_nothing_useful: "*bool",
  gave_up_after_seeing_results: "*bool",
  is_unlinked_failed_search: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{SearchedByAgent}} & ": " & LEFT({{QueryText}}, 40) */
export function calcKnowledgeSearchEventsName(tc: KnowledgeSearchEventsRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.searched_by_agent)), vS(": "), erbText(erbLeft(vStr(tc.query_text), vI(40)))));
}

/** Computes the FoundNothingUseful calculated field.
 *  TRUE when a search returned nothing or nothing was opened.
 *  Formula: =OR({{ResultCount}} = 0, AND({{OpenedSegment}} = "", {{OpenedProjection}} = "")) */
export function calcKnowledgeSearchEventsFoundNothingUseful(tc: KnowledgeSearchEventsRow): boolean | null {
  return toBoolPtr(erbOr(erbBool3(erbEq(erbNullif(vInt(tc.result_count)), vI(0))), erbBool3(erbAnd(erbBool3(erbIsBlank(vStr(tc.opened_segment))), erbBool3(erbIsBlank(vStr(tc.opened_projection)))))));
}

/** Computes the GaveUpAfterSeeingResults calculated field.
 *  TRUE when the searcher abandoned the query after results came back.
 *  Formula: =AND({{WasAbandoned}}, {{ResultCount}} > 0) */
export function calcKnowledgeSearchEventsGaveUpAfterSeeingResults(tc: KnowledgeSearchEventsRow): boolean | null {
  return toBoolPtr(erbAnd(erbIsTrue(vBool(tc.was_abandoned)), erbBool3(erbCmp(erbNullif(vInt(tc.result_count)), ">", vI(0)))));
}

/** Computes the IsUnlinkedFailedSearch calculated field.
 *  TRUE when a search that found nothing useful is linked to no knowledge gap and no usability barrier.
 *  Formula: =AND({{FoundNothingUseful}}, {{LinkedKnowledgeGap}} = "", {{LinkedUsabilityBarrier}} = "") */
export function calcKnowledgeSearchEventsIsUnlinkedFailedSearch(tc: KnowledgeSearchEventsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.found_nothing_useful)), erbBool3(erbIsBlank(vStr(tc.linked_knowledge_gap))), erbBool3(erbIsBlank(vStr(tc.linked_usability_barrier)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeKnowledgeSearchEvents(tc: KnowledgeSearchEventsRow): KnowledgeSearchEventsRow {
  // Level 1
  calcGuard(tc, knowledgeSearchEventsFieldTypes, "name", () => { tc.name = calcKnowledgeSearchEventsName(tc); });
  calcGuard(tc, knowledgeSearchEventsFieldTypes, "found_nothing_useful", () => { tc.found_nothing_useful = calcKnowledgeSearchEventsFoundNothingUseful(tc); });
  calcGuard(tc, knowledgeSearchEventsFieldTypes, "gave_up_after_seeing_results", () => { tc.gave_up_after_seeing_results = calcKnowledgeSearchEventsGaveUpAfterSeeingResults(tc); });
  // Level 2
  calcGuard(tc, knowledgeSearchEventsFieldTypes, "is_unlinked_failed_search", () => { tc.is_unlinked_failed_search = calcKnowledgeSearchEventsIsUnlinkedFailedSearch(tc); });
  return tc;
}

/** Reads KnowledgeSearchEvents rows from a JSON array file. */
export function loadKnowledgeSearchEventsRows(file: string): KnowledgeSearchEventsRow[] {
  return loadRows(file, { fields: knowledgeSearchEventsFieldTypes }) as unknown as KnowledgeSearchEventsRow[];
}

// =============================================================================
