  /** GroundedAgent, Assistant or PromptOnly. */
  approach: string | null;
  /** Assist, Partial or Full. */
  automation_level: string | null;
  /** TRUE when the AI takes actions in the workflow, not just answers. */
  is_agentic: boolean | null;
  /** TRUE when the AI's task follows ordered steps. */
  task_is_multi_step: boolean | null;
  /** TRUE when the task depends on this organization's own knowledge. */
