  depends_on_organizational_knowledge: "*bool",
  preceding_initiative: "*string",
  status: "*string",
  outcome: "*string",
  redesign_started_at: "*string",
  connected_to_ai_at: "*string",
  model_layer_budget: "*float64",
  knowledge_layer_budget: "*float64",
  measured_bottom_line_impact: "*float64",
  evaluation_context: "*string",
  as_of_instant: "*string",
  target_has_no_explicit_steps: "*bool",
  target_version_issued_at: "*string",
  target_version_under_specified: "*bool",
  target_version_notation_only: "*bool",
  target_elicitation_evidence_count: "*int",
  reviewed_output_count: "*int",
  preceding_reviewed_output_count: "*int",
  last_outcome_measured_at: "*string",
  days_since_outcome_measured: "*int",
  ai_insight_count: "*int",
  hands_tacit_procedure_to_agent: "*bool",
  agent_on_under_specified_procedure: "*bool",
  agent_on_notation_only_procedure: "*bool",
  calls_for_process_knowledge_framework: "*bool",
  redesigned_before_documented: "*bool",
  breaks_elicit_encode_connect_order: "*bool",
  went_full_without_reviewed_partial_stage: "*bool",
  underinvests_knowledge_layer: "*bool",
  not_anchored_in_process_knowledge: "*bool",
  agentic_without_knowledge_capture: "*bool",
  is_ai_outcome_unmeasured: "*bool",
