/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{Title}} */
export function calcModelChangeRequestsName(tc: ModelChangeRequestsRow): string | null {
  return toStringPtr(vStr(tc.title));
}

/** Computes the RuleKey calculated field.
 *  Key of the change-authority rule for this model and layer.
 *  Formula: ={{GovernedModel}} & "|" & {{ChangeLayer}} */
export function calcModelChangeRequestsRuleKey(tc: ModelChangeRequestsRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.governed_model)), vS("|"), erbText(vStr(tc.change_layer))));
}

/** Computes the IsAccepted calculated field.
 *  TRUE once approved or deployed.
 *  Formula: =OR({{Status}} = "Approved", {{Status}} = "Deployed") */
export function calcModelChangeRequestsIsAccepted(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.status)), vS("Approved"))), erbBool3(erbEq(erbNullif(vStr(tc.status)), vS("Deployed")))));
}

/** Computes the IsModelingChange calculated field.
 *  TRUE for a modeling change rather than a data operation.
 *  Formula: ={{Classification}} = "ModelingChange" */
export function calcModelChangeRequestsIsModelingChange(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbEq(erbNullif(vStr(tc.classification)), vS("ModelingChange")));
}

/** Computes the IsSchemaChange calculated field.
 *  TRUE for a change to the schema layer.
 *  Formula: ={{ChangeLayer}} = "Schema" */
export function calcModelChangeRequestsIsSchemaChange(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbEq(erbNullif(vStr(tc.change_layer)), vS("Schema")));
}

/** Computes the HasAuthorityReview calculated field.
 *  TRUE when the authority reviewed the change.
 *  Formula: ={{AuthorityReviewedAt}} <> "" */
export function calcModelChangeRequestsHasAuthorityReview(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbIsNotBlank(vStr(tc.authority_reviewed_at)));
}

/** Computes the RequiresAuthorityReview calculated field.
 *  TRUE when the change alters or retires existing elements or vocabularies, adds disjointness, or is major.
 *  Formula: =OR({{ChangeOperation}} = "RenameClass", {{ChangeOperation}} = "RemoveClass", {{ChangeOperation}} = "ChangeDomainRange", {{ChangeOperation}} = "AddDisjointness", {{ChangeOperation}} = "AddVocabularyTerm", {{ChangeOperation}} = "RetireDefinition", {{DeclaredScale}} = "Major") */
export function calcModelChangeRequestsRequiresAuthorityReview(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.change_operation)), vS("RenameClass"))), erbBool3(erbEq(erbNullif(vStr(tc.change_operation)), vS("RemoveClass"))), erbBool3(erbEq(erbNullif(vStr(tc.change_operation)), vS("ChangeDomainRange"))), erbBool3(erbEq(erbNullif(vStr(tc.change_operation)), vS("AddDisjointness"))), erbBool3(erbEq(erbNullif(vStr(tc.change_operation)), vS("AddVocabularyTerm"))), erbBool3(erbEq(erbNullif(vStr(tc.change_operation)), vS("RetireDefinition"))), erbBool3(erbEq(erbNullif(vStr(tc.declared_scale)), vS("Major")))));
}

/** Computes the IsMinorScope calculated field.
 *  TRUE for a change the steward may approve and deploy alone.
 *  Formula: =AND({{RequiresAuthorityReview}} = FALSE, {{DeclaredScale}} <> "Major") */
export function calcModelChangeRequestsIsMinorScope(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(vBool(tc.requires_authority_review), vB(false))), erbBool3(erbNe(erbNullif(vStr(tc.declared_scale)), vS("Major")))));
}

/** Computes the StewardOwnChangeUnreviewed calculated field.
 *  TRUE when the steward raised a change beyond minor scope and the authority never reviewed it.
 *  Formula: =AND({{StewardAgent}} <> "", {{RequestedByAgent}} = {{StewardAgent}}, {{IsMinorScope}} = FALSE, {{HasAuthorityReview}} = FALSE) */
export function calcModelChangeRequestsStewardOwnChangeUnreviewed(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.steward_agent))), erbBool3(erbEq(erbNullif(vStr(tc.requested_by_agent)), vStr(tc.steward_agent))), erbBool3(erbEq(vBool(tc.is_minor_scope), vB(false))), erbBool3(erbEq(vBool(tc.has_authority_review), vB(false)))));
}

/** Computes the StewardApprovalOutOfBounds calculated field.
 *  TRUE when a steward who is not also the authority approved a change beyond the minor changes a steward is authorized to approve.
 *  Formula: =AND({{ApprovedByAgent}} <> "", {{ApprovedByAgent}} = {{StewardAgent}}, {{ApprovedByAgent}} <> {{AuthorityAgent}}, {{IsMinorScope}} = FALSE) */
export function calcModelChangeRequestsStewardApprovalOutOfBounds(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.approved_by_agent))), erbBool3(erbEq(erbNullif(vStr(tc.approved_by_agent)), vStr(tc.steward_agent))), erbBool3(erbNe(erbNullif(vStr(tc.approved_by_agent)), vStr(tc.authority_agent))), erbBool3(erbEq(vBool(tc.is_minor_scope), vB(false)))));
}

/** Computes the AuthorityReviewSkipped calculated field.
 *  TRUE when a change that alters existing elements or vocabularies, or adds disjointness, was accepted without authority review.
 *  Formula: =AND({{RequiresAuthorityReview}}, {{IsAccepted}}, {{HasAuthorityReview}} = FALSE) */
export function calcModelChangeRequestsAuthorityReviewSkipped(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.requires_authority_review)), erbBool3(vBool(tc.is_accepted)), erbBool3(erbEq(vBool(tc.has_authority_review), vB(false)))));
}

/** Computes the PlacementNotDecidedByAuthority calculated field.
 *  TRUE when someone other than the authority decided how and where a change is made.
 *  Formula: =AND({{ImplementationPlacement}} <> "", {{PlacementDecidedByAgent}} <> {{AuthorityAgent}}) */
export function calcModelChangeRequestsPlacementNotDecidedByAuthority(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.implementation_placement))), erbBool3(erbNe(erbNullif(vStr(tc.placement_decided_by_agent)), vStr(tc.authority_agent)))));
}

/** Computes the IsMisrouted calculated field.
 *  TRUE when a change went through a different process than the rule for its layer requires.
 *  Formula: =AND({{RequiredRoute}} <> "", {{Route}} <> {{RequiredRoute}}) */
export function calcModelChangeRequestsIsMisrouted(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.required_route))), erbBool3(erbNe(erbNullif(vStr(tc.route)), vStr(tc.required_route)))));
}

/** Computes the LacksMotivatingQuestion calculated field.
 *  TRUE when the request names no competency question.
 *  Formula: ={{MotivatingQuestion}} = "" */
export function calcModelChangeRequestsLacksMotivatingQuestion(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbIsBlank(vStr(tc.motivating_question)));
}

/** Computes the UnmotivatedAndNotReturned calculated field.
 *  TRUE when a request with no competency question went forward instead of being returned for clarification.
 *  Formula: =AND({{LacksMotivatingQuestion}}, {{Status}} <> "ReturnedForClarification") */
export function calcModelChangeRequestsUnmotivatedAndNotReturned(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.lacks_motivating_question)), erbBool3(erbNe(erbNullif(vStr(tc.status)), vS("ReturnedForClarification")))));
}

/** Computes the MotivatedByFailingQuestion calculated field.
 *  TRUE when the change exists because a question the model used to answer now fails.
 *  Formula: =AND({{MotivatingQuestion}} <> "", {{MotivationKind}} = "ExistingQuestionNowFails") */
export function calcModelChangeRequestsMotivatedByFailingQuestion(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.motivating_question))), erbBool3(erbEq(erbNullif(vStr(tc.motivation_kind)), vS("ExistingQuestionNowFails")))));
}

/** Computes the IsAcceptedWithoutNamedApprover calculated field.
 *  TRUE when an accepted change names nobody as approver.
 *  Formula: =AND({{IsAccepted}}, {{ApprovedByAgent}} = "") */
export function calcModelChangeRequestsIsAcceptedWithoutNamedApprover(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_accepted)), erbBool3(erbIsBlank(vStr(tc.approved_by_agent)))));
}

/** Computes the DeployedWithoutTargetRelease calculated field.
 *  TRUE when a deployed schema change names no release.
 *  Formula: =AND({{Status}} = "Deployed", {{IsSchemaChange}}, {{TargetRelease}} = "") */
export function calcModelChangeRequestsDeployedWithoutTargetRelease(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.status)), vS("Deployed"))), erbBool3(vBool(tc.is_schema_change)), erbBool3(erbIsBlank(vStr(tc.target_release)))));
}

/** Computes the IsMisclassifiedAgentSwap calculated field.
 *  TRUE when swapping which agent fills a role was handled as a modeling change.
 *  Formula: =AND({{ChangeOperation}} = "ReassignAgent", {{Classification}} <> "DataOperation") */
export function calcModelChangeRequestsIsMisclassifiedAgentSwap(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.change_operation)), vS("ReassignAgent"))), erbBool3(erbNe(erbNullif(vStr(tc.classification)), vS("DataOperation")))));
}

/** Computes the AiToHumanMoveWithoutComplianceReview calculated field.
 *  TRUE when a step moved from AI to human execution with no compliance consequences recorded.
 *  Formula: =AND({{ChangeOperation}} = "MoveStepToHuman", {{ComplianceImpact}} = "") */
export function calcModelChangeRequestsAiToHumanMoveWithoutComplianceReview(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.change_operation)), vS("MoveStepToHuman"))), erbBool3(erbIsBlank(vStr(tc.compliance_impact)))));
}

/** Computes the AiToHumanMoveUnaudited calculated field.
 *  TRUE when a move from AI to human execution does not record when it took effect or why.
 *  Formula: =AND({{ChangeOperation}} = "MoveStepToHuman", OR({{EffectiveAt}} = "", {{StatedNeed}} = "")) */
export function calcModelChangeRequestsAiToHumanMoveUnaudited(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.change_operation)), vS("MoveStepToHuman"))), erbBool3(erbOr(erbBool3(erbIsBlank(vStr(tc.effective_at))), erbBool3(erbIsBlank(vStr(tc.stated_need)))))));
}

/** Computes the IsAiToHumanMove calculated field.
 *  TRUE for a recorded move of a step from AI to human execution with its effective date.
 *  Formula: =AND({{ChangeOperation}} = "MoveStepToHuman", {{EffectiveAt}} <> "") */
export function calcModelChangeRequestsIsAiToHumanMove(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.change_operation)), vS("MoveStepToHuman"))), erbBool3(erbIsNotBlank(vStr(tc.effective_at)))));
}

/** Computes the LifecycleChangeByUnauthorizedAgent calculated field.
 *  TRUE when a definition was created, modified or retired on the approval of someone who is neither steward nor authority.
 *  Formula: =AND(OR({{ChangeOperation}} = "CreateDefinition", {{ChangeOperation}} = "ModifyDefinition", {{ChangeOperation}} = "RetireDefinition"), {{ApprovedByAgent}} <> "", {{ApprovedByAgent}} <> {{StewardAgent}}, {{ApprovedByAgent}} <> {{AuthorityAgent}}) */
export function calcModelChangeRequestsLifecycleChangeByUnauthorizedAgent(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.change_operation)), vS("CreateDefinition"))), erbBool3(erbEq(erbNullif(vStr(tc.change_operation)), vS("ModifyDefinition"))), erbBool3(erbEq(erbNullif(vStr(tc.change_operation)), vS("RetireDefinition"))))), erbBool3(erbIsNotBlank(vStr(tc.approved_by_agent))), erbBool3(erbNe(erbNullif(vStr(tc.approved_by_agent)), vStr(tc.steward_agent))), erbBool3(erbNe(erbNullif(vStr(tc.approved_by_agent)), vStr(tc.authority_agent)))));
}

/** Computes the WouldMakeInstancesInconsistent calculated field.
 *  TRUE when the assessment found existing instance data the change would make inconsistent.
 *  Formula: ={{AssessedInconsistentCount}} > 0 */
export function calcModelChangeRequestsWouldMakeInstancesInconsistent(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbCmp(vInt(tc.assessed_inconsistent_count), ">", vI(0)));
}

/** Computes the WouldAlterInferences calculated field.
 *  TRUE when the assessment found inferences the change would alter.
 *  Formula: ={{AssessedInferenceCount}} > 0 */
export function calcModelChangeRequestsWouldAlterInferences(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbCmp(vInt(tc.assessed_inference_count), ">", vI(0)));
}

/** Computes the WouldAlterQueryResults calculated field.
 *  TRUE when the assessment found query results the change would alter.
 *  Formula: ={{AssessedQueryResultCount}} > 0 */
export function calcModelChangeRequestsWouldAlterQueryResults(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbCmp(vInt(tc.assessed_query_result_count), ">", vI(0)));
}

/** Computes the WouldLeaveCoverageIncomplete calculated field.
 *  TRUE when the assessment found the change would leave the vocabulary layer or coverage model incomplete.
 *  Formula: ={{AssessedCoverageGapCount}} > 0 */
export function calcModelChangeRequestsWouldLeaveCoverageIncomplete(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbCmp(vInt(tc.assessed_coverage_gap_count), ">", vI(0)));
}

/** Computes the MissedInconsistentInstances calculated field.
 *  TRUE when instance data became inconsistent after deployment and the impact assessment had identified none.
 *  Formula: =AND({{PostDeployInconsistentCount}} > 0, {{AssessedInconsistentCount}} = 0) */
export function calcModelChangeRequestsMissedInconsistentInstances(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.post_deploy_inconsistent_count), ">", vI(0))), erbBool3(erbEq(vInt(tc.assessed_inconsistent_count), vI(0)))));
}

/** Computes the MissedAlteredInferences calculated field.
 *  TRUE when inferences changed after deployment and the impact assessment had identified none.
 *  Formula: =AND({{PostDeployInferenceCount}} > 0, {{AssessedInferenceCount}} = 0) */
export function calcModelChangeRequestsMissedAlteredInferences(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.post_deploy_inference_count), ">", vI(0))), erbBool3(erbEq(vInt(tc.assessed_inference_count), vI(0)))));
}

/** Computes the MissedAlteredQueryResults calculated field.
 *  TRUE when query results changed after deployment and the impact assessment had identified none.
 *  Formula: =AND({{PostDeployQueryResultCount}} > 0, {{AssessedQueryResultCount}} = 0) */
export function calcModelChangeRequestsMissedAlteredQueryResults(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.post_deploy_query_result_count), ">", vI(0))), erbBool3(erbEq(vInt(tc.assessed_query_result_count), vI(0)))));
}

/** Computes the LeavesCoverageUnchecked calculated field.
 *  TRUE when an accepted modeling change was never checked against the vocabulary layer and domain coverage model.
 *  Formula: =AND({{IsAccepted}}, {{IsModelingChange}}, {{CoverageCheckedAt}} = "") */
export function calcModelChangeRequestsLeavesCoverageUnchecked(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_accepted)), erbBool3(vBool(tc.is_modeling_change)), erbBool3(erbIsBlank(vStr(tc.coverage_checked_at)))));
}

/** Computes the DomainChangeSpreadWrongInferences calculated field.
 *  TRUE when a domain or range change produced altered inferences in deployment.
 *  Formula: =AND({{ChangeOperation}} = "ChangeDomainRange", {{PostDeployInferenceCount}} > 0) */
export function calcModelChangeRequestsDomainChangeSpreadWrongInferences(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.change_operation)), vS("ChangeDomainRange"))), erbBool3(erbCmp(vInt(tc.post_deploy_inference_count), ">", vI(0)))));
}

/** Computes the IntuitiveDisjointnessBrokeIndividuals calculated field.
 *  TRUE when a disjointness axiom added with no motivating question made individuals inconsistent.
 *  Formula: =AND({{ChangeOperation}} = "AddDisjointness", {{LacksMotivatingQuestion}}, ({{AssessedInconsistentCount}} + {{PostDeployInconsistentCount}}) > 0) */
export function calcModelChangeRequestsIntuitiveDisjointnessBrokeIndividuals(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.change_operation)), vS("AddDisjointness"))), erbBool3(vBool(tc.lacks_motivating_question)), erbBool3(erbCmp(erbAdd(vInt(tc.assessed_inconsistent_count), vInt(tc.post_deploy_inconsistent_count)), ">", vI(0)))));
}

/** Computes the AcceptedWithoutTestRun calculated field.
 *  TRUE when a modeling change was accepted without ever running the validation suite with it applied.
 *  Formula: =AND({{IsAccepted}}, {{IsModelingChange}}, {{ValidationRunCount}} = 0) */
export function calcModelChangeRequestsAcceptedWithoutTestRun(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_accepted)), erbBool3(vBool(tc.is_modeling_change)), erbBool3(erbEq(vInt(tc.validation_run_count), vI(0)))));
}

/** Computes the AcceptedWithFailingSuite calculated field.
 *  TRUE when a change was accepted although the full suite failed with it applied.
 *  Formula: =AND({{IsAccepted}}, {{AcceptanceFailureTotal}} > 0) */
export function calcModelChangeRequestsAcceptedWithFailingSuite(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_accepted)), erbBool3(erbCmp(vInt(tc.acceptance_failure_total), ">", vI(0)))));
}

/** Computes the AcceptedWithoutStructuralCheck calculated field.
 *  TRUE when a modeling change was accepted with no passing automated structural consistency check.
 *  Formula: =AND({{IsAccepted}}, {{IsModelingChange}}, {{StructuralPassCount}} = 0) */
export function calcModelChangeRequestsAcceptedWithoutStructuralCheck(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_accepted)), erbBool3(vBool(tc.is_modeling_change)), erbBool3(erbEq(vInt(tc.structural_pass_count), vI(0)))));
}

/** Computes the AcceptedWithoutVocabularyCheck calculated field.
 *  TRUE when a modeling change was accepted with no passing automated check that it uses only approved vocabulary.
 *  Formula: =AND({{IsAccepted}}, {{IsModelingChange}}, {{VocabularyPassCount}} = 0) */
export function calcModelChangeRequestsAcceptedWithoutVocabularyCheck(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_accepted)), erbBool3(vBool(tc.is_modeling_change)), erbBool3(erbEq(vInt(tc.vocabulary_pass_count), vI(0)))));
}

/** Computes the IntegrityDecidedWithoutHuman calculated field.
 *  TRUE when an accepted schema change's integrity was judged only by software.
 *  Formula: =AND({{IsAccepted}}, {{IsSchemaChange}}, {{IntegrityCheckCount}} > 0, {{HumanIntegrityCheckCount}} = 0) */
export function calcModelChangeRequestsIntegrityDecidedWithoutHuman(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_accepted)), erbBool3(vBool(tc.is_schema_change)), erbBool3(erbCmp(vInt(tc.integrity_check_count), ">", vI(0))), erbBool3(erbEq(vInt(tc.human_integrity_check_count), vI(0)))));
}

/** Computes the SkippedDisjointnessReview calculated field.
 *  TRUE when an accepted schema change was never checked for disjointness violations.
 *  Formula: =AND({{IsAccepted}}, {{IsSchemaChange}}, {{DisjointnessCheckCount}} = 0) */
export function calcModelChangeRequestsSkippedDisjointnessReview(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_accepted)), erbBool3(vBool(tc.is_schema_change)), erbBool3(erbEq(vInt(tc.disjointness_check_count), vI(0)))));
}

/** Computes the SkippedDomainInferenceReview calculated field.
 *  TRUE when an accepted schema change was never checked for unintended domain inferences.
 *  Formula: =AND({{IsAccepted}}, {{IsSchemaChange}}, {{DomainInferenceCheckCount}} = 0) */
export function calcModelChangeRequestsSkippedDomainInferenceReview(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_accepted)), erbBool3(vBool(tc.is_schema_change)), erbBool3(erbEq(vInt(tc.domain_inference_check_count), vI(0)))));
}

/** Computes the SkippedRangeReview calculated field.
 *  TRUE when an accepted schema change was never checked for property range inconsistencies.
 *  Formula: =AND({{IsAccepted}}, {{IsSchemaChange}}, {{RangeConsistencyCheckCount}} = 0) */
export function calcModelChangeRequestsSkippedRangeReview(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_accepted)), erbBool3(vBool(tc.is_schema_change)), erbBool3(erbEq(vInt(tc.range_consistency_check_count), vI(0)))));
}

/** Computes the ApprovedOverUnresolvedObjection calculated field.
 *  TRUE when a change was accepted while a stakeholder objection remained unresolved.
 *  Formula: =AND({{IsAccepted}}, {{UnresolvedObjectionCount}} > 0) */
export function calcModelChangeRequestsApprovedOverUnresolvedObjection(tc: ModelChangeRequestsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_accepted)), erbBool3(erbCmp(vInt(tc.unresolved_objection_count), ">", vI(0)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeModelChangeRequests(tc: ModelChangeRequestsRow): ModelChangeRequestsRow {
  // Level 1
  calcGuard(tc, modelChangeRequestsFieldTypes, "name", () => { tc.name = calcModelChangeRequestsName(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "rule_key", () => { tc.rule_key = calcModelChangeRequestsRuleKey(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "is_accepted", () => { tc.is_accepted = calcModelChangeRequestsIsAccepted(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "is_modeling_change", () => { tc.is_modeling_change = calcModelChangeRequestsIsModelingChange(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "is_schema_change", () => { tc.is_schema_change = calcModelChangeRequestsIsSchemaChange(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "has_authority_review", () => { tc.has_authority_review = calcModelChangeRequestsHasAuthorityReview(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "requires_authority_review", () => { tc.requires_authority_review = calcModelChangeRequestsRequiresAuthorityReview(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "placement_not_decided_by_authority", () => { tc.placement_not_decided_by_authority = calcModelChangeRequestsPlacementNotDecidedByAuthority(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "is_misrouted", () => { tc.is_misrouted = calcModelChangeRequestsIsMisrouted(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "lacks_motivating_question", () => { tc.lacks_motivating_question = calcModelChangeRequestsLacksMotivatingQuestion(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "motivated_by_failing_question", () => { tc.motivated_by_failing_question = calcModelChangeRequestsMotivatedByFailingQuestion(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "is_misclassified_agent_swap", () => { tc.is_misclassified_agent_swap = calcModelChangeRequestsIsMisclassifiedAgentSwap(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "ai_to_human_move_without_compliance_review", () => { tc.ai_to_human_move_without_compliance_review = calcModelChangeRequestsAiToHumanMoveWithoutComplianceReview(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "ai_to_human_move_unaudited", () => { tc.ai_to_human_move_unaudited = calcModelChangeRequestsAiToHumanMoveUnaudited(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "is_ai_to_human_move", () => { tc.is_ai_to_human_move = calcModelChangeRequestsIsAiToHumanMove(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "lifecycle_change_by_unauthorized_agent", () => { tc.lifecycle_change_by_unauthorized_agent = calcModelChangeRequestsLifecycleChangeByUnauthorizedAgent(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "would_make_instances_inconsistent", () => { tc.would_make_instances_inconsistent = calcModelChangeRequestsWouldMakeInstancesInconsistent(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "would_alter_inferences", () => { tc.would_alter_inferences = calcModelChangeRequestsWouldAlterInferences(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "would_alter_query_results", () => { tc.would_alter_query_results = calcModelChangeRequestsWouldAlterQueryResults(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "would_leave_coverage_incomplete", () => { tc.would_leave_coverage_incomplete = calcModelChangeRequestsWouldLeaveCoverageIncomplete(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "missed_inconsistent_instances", () => { tc.missed_inconsistent_instances = calcModelChangeRequestsMissedInconsistentInstances(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "missed_altered_inferences", () => { tc.missed_altered_inferences = calcModelChangeRequestsMissedAlteredInferences(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "missed_altered_query_results", () => { tc.missed_altered_query_results = calcModelChangeRequestsMissedAlteredQueryResults(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "domain_change_spread_wrong_inferences", () => { tc.domain_change_spread_wrong_inferences = calcModelChangeRequestsDomainChangeSpreadWrongInferences(tc); });
  // Level 2
  calcGuard(tc, modelChangeRequestsFieldTypes, "is_minor_scope", () => { tc.is_minor_scope = calcModelChangeRequestsIsMinorScope(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "authority_review_skipped", () => { tc.authority_review_skipped = calcModelChangeRequestsAuthorityReviewSkipped(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "unmotivated_and_not_returned", () => { tc.unmotivated_and_not_returned = calcModelChangeRequestsUnmotivatedAndNotReturned(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "is_accepted_without_named_approver", () => { tc.is_accepted_without_named_approver = calcModelChangeRequestsIsAcceptedWithoutNamedApprover(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "deployed_without_target_release", () => { tc.deployed_without_target_release = calcModelChangeRequestsDeployedWithoutTargetRelease(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "leaves_coverage_unchecked", () => { tc.leaves_coverage_unchecked = calcModelChangeRequestsLeavesCoverageUnchecked(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "intuitive_disjointness_broke_individuals", () => { tc.intuitive_disjointness_broke_individuals = calcModelChangeRequestsIntuitiveDisjointnessBrokeIndividuals(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "accepted_without_test_run", () => { tc.accepted_without_test_run = calcModelChangeRequestsAcceptedWithoutTestRun(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "accepted_with_failing_suite", () => { tc.accepted_with_failing_suite = calcModelChangeRequestsAcceptedWithFailingSuite(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "accepted_without_structural_check", () => { tc.accepted_without_structural_check = calcModelChangeRequestsAcceptedWithoutStructuralCheck(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "accepted_without_vocabulary_check", () => { tc.accepted_without_vocabulary_check = calcModelChangeRequestsAcceptedWithoutVocabularyCheck(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "integrity_decided_without_human", () => { tc.integrity_decided_without_human = calcModelChangeRequestsIntegrityDecidedWithoutHuman(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "skipped_disjointness_review", () => { tc.skipped_disjointness_review = calcModelChangeRequestsSkippedDisjointnessReview(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "skipped_domain_inference_review", () => { tc.skipped_domain_inference_review = calcModelChangeRequestsSkippedDomainInferenceReview(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "skipped_range_review", () => { tc.skipped_range_review = calcModelChangeRequestsSkippedRangeReview(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "approved_over_unresolved_objection", () => { tc.approved_over_unresolved_objection = calcModelChangeRequestsApprovedOverUnresolvedObjection(tc); });
  // Level 3
  calcGuard(tc, modelChangeRequestsFieldTypes, "steward_own_change_unreviewed", () => { tc.steward_own_change_unreviewed = calcModelChangeRequestsStewardOwnChangeUnreviewed(tc); });
  calcGuard(tc, modelChangeRequestsFieldTypes, "steward_approval_out_of_bounds", () => { tc.steward_approval_out_of_bounds = calcModelChangeRequestsStewardApprovalOutOfBounds(tc); });
  return tc;
}

/** Reads ModelChangeRequests rows from a JSON array file. */
export function loadModelChangeRequestsRows(file: string): ModelChangeRequestsRow[] {
  return loadRows(file, { fields: modelChangeRequestsFieldTypes }) as unknown as ModelChangeRequestsRow[];
}

// =============================================================================
// CHANGEAUTHORITYRULES TABLE
// Which role may change which layer of a model, who approves, through which process, and the response when a change breaks the model.
// =============================================================================

/** A row in the ChangeAuthorityRules table. */
export interface ChangeAuthorityRulesRow {
  /** Stored identifier. */
  change_authority_rule_id: string;
  /** Display name. */
  name: string | null;
  /** Model. */
  governed_model: string | null;
  /** Layer the rule governs. */
  change_layer: string | null;
  /** Role that may make the change. */
  permitted_role: string | null;
  /** Role that approves it. */
  approval_role: string | null;
  /** DataOperations or Governance. */
  required_route: string | null;
  /** When such changes may be made. */
  when_permitted: string | null;
  /** What happens when a change of this kind breaks the model. */
  breakage_response: string | null;
  /** Requests under this rule that went through the wrong process. */
  misrouted_request_count: number | null;
  /** TRUE when at least one change went around this rule's required process. */
  is_rule_bypassed: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const changeAuthorityRulesFieldTypes: Record<string, FieldType> = {
  change_authority_rule_id: "string",
  name: "*string",
  governed_model: "*string",
  change_layer: "*string",
  permitted_role: "*string",
  approval_role: "*string",
  required_route: "*string",
  when_permitted: "*string",
  breakage_response: "*string",
  misrouted_request_count: "*int",
  is_rule_bypassed: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{GovernedModel}} & " " & {{ChangeLayer}} */
export function calcChangeAuthorityRulesName(tc: ChangeAuthorityRulesRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.governed_model)), vS(" "), erbText(vStr(tc.change_layer))));
}

/** Computes the IsRuleBypassed calculated field.
 *  TRUE when at least one change went around this rule's required process.
 *  Formula: ={{MisroutedRequestCount}} > 0 */
export function calcChangeAuthorityRulesIsRuleBypassed(tc: ChangeAuthorityRulesRow): boolean | null {
  return toBoolPtr(erbCmp(vInt(tc.misrouted_request_count), ">", vI(0)));
}

/** Computes every calculated field of the row in dependency order. */
export function computeChangeAuthorityRules(tc: ChangeAuthorityRulesRow): ChangeAuthorityRulesRow {
  // Level 1
  calcGuard(tc, changeAuthorityRulesFieldTypes, "name", () => { tc.name = calcChangeAuthorityRulesName(tc); });
  calcGuard(tc, changeAuthorityRulesFieldTypes, "is_rule_bypassed", () => { tc.is_rule_bypassed = calcChangeAuthorityRulesIsRuleBypassed(tc); });
  return tc;
}

/** Reads ChangeAuthorityRules rows from a JSON array file. */
export function loadChangeAuthorityRulesRows(file: string): ChangeAuthorityRulesRow[] {
  return loadRows(file, { fields: changeAuthorityRulesFieldTypes }) as unknown as ChangeAuthorityRulesRow[];
}

