// =============================================================================
// COMPETENCYQUESTIONSETENTRIES TABLE
// The competency question set of each governed model, with the original baseline kept apart from later additions.
// =============================================================================

/** A row in the CompetencyQuestionSetEntries table. */
export interface CompetencyQuestionSetEntriesRow {
  /** Stored identifier. */
  competency_question_set_entry_id: string;
  /** Display name. */
  name: string | null;
  /** Model. */
  governed_model: string | null;
  /** Question. */
  role_question: string | null;
  /** TRUE for a question in the original set the model was built against. */
  is_original_baseline: boolean | null;
  /** When added. */
  added_at: string | null;
  /** Active, DeprecationCandidate or Deprecated. */
  status: string | null;
  /** Relevant or NoLongerRelevant, from the latest review. */
  relevance_verdict: string | null;
  /** Used to scope the model. */
  used_for_scoping: boolean | null;
  /** Used as an acceptance criterion. */
  used_as_acceptance_criterion: boolean | null;
  /** Drives validation tests. */
  used_as_test_driver: boolean | null;
  /** Reviewed as a governance instrument. */
  used_for_governance: boolean | null;
  /** Evaluation context. */
  evaluation_context: string | null;
  /** The modeled instant this row is judged against. */
  as_of_instant: string | null;
  /** Days in the set. */
  days_since_added: number | null;
  /** TRUE for an original question that after more than a year of operation no longer fits what the organization needs. */
  is_outgrown_baseline_question: boolean | null;
  /** TRUE when review found a question no longer relevant and it was not made a deprecation candidate. */
  irrelevant_but_still_active: boolean | null;
  /** How many of the four roles (scoping, acceptance, test driver, governance) the question serves. */
  governance_use_count: number | null;
  /** TRUE when one question served in turn as scoping tool, acceptance criterion, test driver and governance instrument. */
  serves_every_governance_use: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const competencyQuestionSetEntriesFieldTypes: Record<string, FieldType> = {
  competency_question_set_entry_id: "string",
  name: "*string",
  governed_model: "*string",
  role_question: "*string",
  is_original_baseline: "*bool",
  added_at: "*string",
  status: "*string",
  relevance_verdict: "*string",
  used_for_scoping: "*bool",
  used_as_acceptance_criterion: "*bool",
  used_as_test_driver: "*bool",
  used_for_governance: "*bool",
  evaluation_context: "*string",
  as_of_instant: "*string",
  days_since_added: "*int",
  is_outgrown_baseline_question: "*bool",
  irrelevant_but_still_active: "*bool",
  governance_use_count: "*int",
  serves_every_governance_use: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{GovernedModel}} & " / " & {{RoleQuestion}} */
export function calcCompetencyQuestionSetEntriesName(tc: CompetencyQuestionSetEntriesRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.governed_model)), vS(" / "), erbText(vStr(tc.role_question))));
}

/** Computes the DaysSinceAdded calculated field.
 *  Days in the set.
 *  Formula: =DATETIME_DIFF({{AsOfInstant}}, {{AddedAt}}, "days") */
export function calcCompetencyQuestionSetEntriesDaysSinceAdded(tc: CompetencyQuestionSetEntriesRow): number | null {
  return toIntPtr(erbInteger(erbDatetimeDiff(vStr(tc.as_of_instant), vStr(tc.added_at), vS("days"))));
}

/** Computes the IsOutgrownBaselineQuestion calculated field.
 *  TRUE for an original question that after more than a year of operation no longer fits what the organization needs.
 *  Formula: =AND({{IsOriginalBaseline}}, {{DaysSinceAdded}} > 365, {{RelevanceVerdict}} = "NoLongerRelevant") */
export function calcCompetencyQuestionSetEntriesIsOutgrownBaselineQuestion(tc: CompetencyQuestionSetEntriesRow): boolean | null {
  return toBoolPtr(erbAnd(erbIsTrue(vBool(tc.is_original_baseline)), erbBool3(erbCmp(vInt(tc.days_since_added), ">", vI(365))), erbBool3(erbEq(erbNullif(vStr(tc.relevance_verdict)), vS("NoLongerRelevant")))));
}

/** Computes the IrrelevantButStillActive calculated field.
 *  TRUE when review found a question no longer relevant and it was not made a deprecation candidate.
 *  Formula: =AND({{RelevanceVerdict}} = "NoLongerRelevant", {{Status}} = "Active") */
export function calcCompetencyQuestionSetEntriesIrrelevantButStillActive(tc: CompetencyQuestionSetEntriesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.relevance_verdict)), vS("NoLongerRelevant"))), erbBool3(erbEq(erbNullif(vStr(tc.status)), vS("Active")))));
}

/** Computes the GovernanceUseCount calculated field.
 *  How many of the four roles (scoping, acceptance, test driver, governance) the question serves.
 *  Formula: =IF({{UsedForScoping}}, 1, 0) + IF({{UsedAsAcceptanceCriterion}}, 1, 0) + IF({{UsedAsTestDriver}}, 1, 0) + IF({{UsedForGovernance}}, 1, 0) */
export function calcCompetencyQuestionSetEntriesGovernanceUseCount(tc: CompetencyQuestionSetEntriesRow): number | null {
  return toIntPtr(erbInteger(erbAdd(erbAdd(erbAdd(erbIf(erbIsTrue(vBool(tc.used_for_scoping)), () => vI(1), () => vI(0)), erbIf(erbIsTrue(vBool(tc.used_as_acceptance_criterion)), () => vI(1), () => vI(0))), erbIf(erbIsTrue(vBool(tc.used_as_test_driver)), () => vI(1), () => vI(0))), erbIf(erbIsTrue(vBool(tc.used_for_governance)), () => vI(1), () => vI(0)))));
}

/** Computes the ServesEveryGovernanceUse calculated field.
 *  TRUE when one question served in turn as scoping tool, acceptance criterion, test driver and governance instrument.
 *  Formula: ={{GovernanceUseCount}} = 4 */
export function calcCompetencyQuestionSetEntriesServesEveryGovernanceUse(tc: CompetencyQuestionSetEntriesRow): boolean | null {
  return toBoolPtr(erbEq(vInt(tc.governance_use_count), vI(4)));
}

/** Computes every calculated field of the row in dependency order. */
export function computeCompetencyQuestionSetEntries(tc: CompetencyQuestionSetEntriesRow): CompetencyQuestionSetEntriesRow {
  // Level 1
  calcGuard(tc, competencyQuestionSetEntriesFieldTypes, "name", () => { tc.name = calcCompetencyQuestionSetEntriesName(tc); });
  calcGuard(tc, competencyQuestionSetEntriesFieldTypes, "days_since_added", () => { tc.days_since_added = calcCompetencyQuestionSetEntriesDaysSinceAdded(tc); });
  calcGuard(tc, competencyQuestionSetEntriesFieldTypes, "irrelevant_but_still_active", () => { tc.irrelevant_but_still_active = calcCompetencyQuestionSetEntriesIrrelevantButStillActive(tc); });
  calcGuard(tc, competencyQuestionSetEntriesFieldTypes, "governance_use_count", () => { tc.governance_use_count = calcCompetencyQuestionSetEntriesGovernanceUseCount(tc); });
  // Level 2
  calcGuard(tc, competencyQuestionSetEntriesFieldTypes, "is_outgrown_baseline_question", () => { tc.is_outgrown_baseline_question = calcCompetencyQuestionSetEntriesIsOutgrownBaselineQuestion(tc); });
  calcGuard(tc, competencyQuestionSetEntriesFieldTypes, "serves_every_governance_use", () => { tc.serves_every_governance_use = calcCompetencyQuestionSetEntriesServesEveryGovernanceUse(tc); });
  return tc;
}

/** Reads CompetencyQuestionSetEntries rows from a JSON array file. */
export function loadCompetencyQuestionSetEntriesRows(file: string): CompetencyQuestionSetEntriesRow[] {
  return loadRows(file, { fields: competencyQuestionSetEntriesFieldTypes }) as unknown as CompetencyQuestionSetEntriesRow[];
}

