  calcGuard(tc, competencyQuestionRunsFieldTypes, "is_baseline_regression", () => { tc.is_baseline_regression = calcCompetencyQuestionRunsIsBaselineRegression(tc); });
  calcGuard(tc, competencyQuestionRunsFieldTypes, "is_unfixed_wrong_answer", () => { tc.is_unfixed_wrong_answer = calcCompetencyQuestionRunsIsUnfixedWrongAnswer(tc); });
