// =============================================================================

/** A row in the ProcessDesignDecisions table. */
export interface ProcessDesignDecisionsRow {
  /** Stored identifier. */
  process_design_decision_id: string;
  /** Display name. */
  name: string | null;
  /** Version. */
  procedure_version: string | null;
  /** Step the commitment is on. */
  step: string | null;
  /** The commitment. */
  decision: string | null;
  /** Why. */
  rationale: string | null;
  /** Who decided. */
  decided_by_agent: string | null;
  /** When decided. */
  decided_at: string | null;
  /** When written down. */
  recorded_at: string | null;
  /** TRUE when a procedure commitment was recorded with no reason behind it. */
  is_commitment_without_rationale: boolean | null;
  /** Days between deciding and writing the decision down. */
  days_before_recorded: number | null;
  /** TRUE when a decision was written down more than thirty days after it was made, so its why was reconstructed from memory. */
  is_recorded_after_the_fact: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const processDesignDecisionsFieldTypes: Record<string, FieldType> = {
  process_design_decision_id: "string",
  name: "*string",
  procedure_version: "*string",
  step: "*string",
  decision: "*string",
  rationale: "*string",
  decided_by_agent: "*string",
  decided_at: "*string",
  recorded_at: "*string",
  is_commitment_without_rationale: "*bool",
  days_before_recorded: "*int",
  is_recorded_after_the_fact: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: =LEFT({{Decision}}, 60) */
export function calcProcessDesignDecisionsName(tc: ProcessDesignDecisionsRow): string | null {
  return toStringPtr(erbLeft(vStr(tc.decision), vI(60)));
}

/** Computes the IsCommitmentWithoutRationale calculated field.
 *  TRUE when a procedure commitment was recorded with no reason behind it.
 *  Formula: =AND({{Decision}} <> "", {{Rationale}} = "") */
export function calcProcessDesignDecisionsIsCommitmentWithoutRationale(tc: ProcessDesignDecisionsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.decision))), erbBool3(erbIsBlank(vStr(tc.rationale)))));
}

/** Computes the DaysBeforeRecorded calculated field.
 *  Days between deciding and writing the decision down.
 *  Formula: =DATETIME_DIFF({{RecordedAt}}, {{DecidedAt}}, "days") */
export function calcProcessDesignDecisionsDaysBeforeRecorded(tc: ProcessDesignDecisionsRow): number | null {
  return toIntPtr(erbInteger(erbDatetimeDiff(vStr(tc.recorded_at), vStr(tc.decided_at), vS("days"))));
}

/** Computes the IsRecordedAfterTheFact calculated field.
 *  TRUE when a decision was written down more than thirty days after it was made, so its why was reconstructed from memory.
 *  Formula: ={{DaysBeforeRecorded}} > 30 */
export function calcProcessDesignDecisionsIsRecordedAfterTheFact(tc: ProcessDesignDecisionsRow): boolean | null {
  return toBoolPtr(erbCmp(vInt(tc.days_before_recorded), ">", vI(30)));
}

/** Computes every calculated field of the row in dependency order. */
export function computeProcessDesignDecisions(tc: ProcessDesignDecisionsRow): ProcessDesignDecisionsRow {
  // Level 1
  calcGuard(tc, processDesignDecisionsFieldTypes, "name", () => { tc.name = calcProcessDesignDecisionsName(tc); });
  calcGuard(tc, processDesignDecisionsFieldTypes, "is_commitment_without_rationale", () => { tc.is_commitment_without_rationale = calcProcessDesignDecisionsIsCommitmentWithoutRationale(tc); });
  calcGuard(tc, processDesignDecisionsFieldTypes, "days_before_recorded", () => { tc.days_before_recorded = calcProcessDesignDecisionsDaysBeforeRecorded(tc); });
  // Level 2
  calcGuard(tc, processDesignDecisionsFieldTypes, "is_recorded_after_the_fact", () => { tc.is_recorded_after_the_fact = calcProcessDesignDecisionsIsRecordedAfterTheFact(tc); });
  return tc;
}

/** Reads ProcessDesignDecisions rows from a JSON array file. */
export function loadProcessDesignDecisionsRows(file: string): ProcessDesignDecisionsRow[] {
  return loadRows(file, { fields: processDesignDecisionsFieldTypes }) as unknown as ProcessDesignDecisionsRow[];
}

