  /** Stored identifier. */
  model_change_log_entry_id: string;
  /** Display name. */
  name: string | null;
  /** Model. */
  governed_model: string | null;
  /** Change request behind the entry. */
  model_change_request: string | null;
  /** Schema release it shipped in. */
  release: string | null;
  /** Data version it shipped in. */
  instance_data_version: string | null;
  /** Schema, Instance, Vocabulary or Documentation. */
  change_layer: string | null;
  /** Operation. */
  change_operation: string | null;
  /** The change. */
  change_summary: string | null;
  /** Why. */
  rationale: string | null;
  /** Terms affected. */
  terms_affected: string | null;
  /** Table affected. */
  affected_table: string | null;
  /** Whether existing instance assertions become invalid or inconsistent. */
  invalidates_instances: boolean | null;
  /** When. */
  logged_at: string | null;
  /** Who. */
