  motivating_question: string | null;
  /** Version number shipped in. */
  release_version: string | null;
  /** Whether the release's versioning decision was left undocumented. */
  release_decision_undocumented: boolean | null;
  /** TRUE for a schema or vocabulary change, as opposed to documentation or instance data. */
  alters_logical_model: boolean | null;
  /** TRUE when a class is removed or renamed. */
  is_class_removal_or_rename: boolean | null;
  /** TRUE for a domain or range change that invalidates existing assertions. */
  is_invalidating_domain_range_change: boolean | null;
  /** TRUE for a disjointness axiom that makes existing individuals inconsistent. */
  is_inconsistent_disjointness: boolean | null;
  /** TRUE when the change breaks existing data or queries. */
  is_backward_incompatible: boolean | null;
