/** Computes the SchemaChangeWithoutRequest calculated field.
 *  TRUE when a schema change was made outside the change process, with no change request.
 *  Formula: =AND({{ChangeLayer}} = "Schema", {{ModelChangeRequest}} = "") */
export function calcModelChangeLogEntriesSchemaChangeWithoutRequest(tc: ModelChangeLogEntriesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.change_layer)), vS("Schema"))), erbBool3(erbIsBlank(vStr(tc.model_change_request)))));
}

/** Computes the CannotBeAudited calculated field.
 *  TRUE when a change names nobody who made it or no version it belongs to.
 *  Formula: =OR({{ChangedByAgent}} = "", AND({{Release}} = "", {{InstanceDataVersion}} = "")) */
export function calcModelChangeLogEntriesCannotBeAudited(tc: ModelChangeLogEntriesRow): boolean | null {
  return toBoolPtr(erbOr(erbBool3(erbIsBlank(vStr(tc.changed_by_agent))), erbBool3(erbAnd(erbBool3(erbIsBlank(vStr(tc.release))), erbBool3(erbIsBlank(vStr(tc.instance_data_version)))))));
}

/** Computes the CannotBeRolledBack calculated field.
 *  TRUE when no prior-state commit is recorded, so the change cannot be rolled back.
 *  Formula: ={{PriorStateCommit}} = "" */
export function calcModelChangeLogEntriesCannotBeRolledBack(tc: ModelChangeLogEntriesRow): boolean | null {
  return toBoolPtr(erbIsBlank(vStr(tc.prior_state_commit)));
}

/** Computes the IsUntraceableBreakingChange calculated field.
 *  TRUE when a breaking change cannot be traced to a documented versioning decision.
 *  Formula: =AND({{IsBackwardIncompatible}}, OR({{Release}} = "", {{ReleaseDecisionUndocumented}})) */
export function calcModelChangeLogEntriesIsUntraceableBreakingChange(tc: ModelChangeLogEntriesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_backward_incompatible)), erbBool3(erbOr(erbBool3(erbIsBlank(vStr(tc.release))), erbBool3(vBool(tc.release_decision_undocumented))))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeModelChangeLogEntries(tc: ModelChangeLogEntriesRow): ModelChangeLogEntriesRow {
  // Level 1
  calcGuard(tc, modelChangeLogEntriesFieldTypes, "name", () => { tc.name = calcModelChangeLogEntriesName(tc); });
  calcGuard(tc, modelChangeLogEntriesFieldTypes, "alters_logical_model", () => { tc.alters_logical_model = calcModelChangeLogEntriesAltersLogicalModel(tc); });
  calcGuard(tc, modelChangeLogEntriesFieldTypes, "is_class_removal_or_rename", () => { tc.is_class_removal_or_rename = calcModelChangeLogEntriesIsClassRemovalOrRename(tc); });
  calcGuard(tc, modelChangeLogEntriesFieldTypes, "is_invalidating_domain_range_change", () => { tc.is_invalidating_domain_range_change = calcModelChangeLogEntriesIsInvalidatingDomainRangeChange(tc); });
  calcGuard(tc, modelChangeLogEntriesFieldTypes, "is_inconsistent_disjointness", () => { tc.is_inconsistent_disjointness = calcModelChangeLogEntriesIsInconsistentDisjointness(tc); });
  calcGuard(tc, modelChangeLogEntriesFieldTypes, "is_additive_schema_change", () => { tc.is_additive_schema_change = calcModelChangeLogEntriesIsAdditiveSchemaChange(tc); });
  calcGuard(tc, modelChangeLogEntriesFieldTypes, "is_unexplained_modification", () => { tc.is_unexplained_modification = calcModelChangeLogEntriesIsUnexplainedModification(tc); });
  calcGuard(tc, modelChangeLogEntriesFieldTypes, "rationale_without_question", () => { tc.rationale_without_question = calcModelChangeLogEntriesRationaleWithoutQuestion(tc); });
  calcGuard(tc, modelChangeLogEntriesFieldTypes, "is_schema_change_without_increment", () => { tc.is_schema_change_without_increment = calcModelChangeLogEntriesIsSchemaChangeWithoutIncrement(tc); });
  calcGuard(tc, modelChangeLogEntriesFieldTypes, "is_instance_change_in_schema_release", () => { tc.is_instance_change_in_schema_release = calcModelChangeLogEntriesIsInstanceChangeInSchemaRelease(tc); });
  calcGuard(tc, modelChangeLogEntriesFieldTypes, "schema_change_without_request", () => { tc.schema_change_without_request = calcModelChangeLogEntriesSchemaChangeWithoutRequest(tc); });
  calcGuard(tc, modelChangeLogEntriesFieldTypes, "cannot_be_audited", () => { tc.cannot_be_audited = calcModelChangeLogEntriesCannotBeAudited(tc); });
  calcGuard(tc, modelChangeLogEntriesFieldTypes, "cannot_be_rolled_back", () => { tc.cannot_be_rolled_back = calcModelChangeLogEntriesCannotBeRolledBack(tc); });
  // Level 2
  calcGuard(tc, modelChangeLogEntriesFieldTypes, "is_backward_incompatible", () => { tc.is_backward_incompatible = calcModelChangeLogEntriesIsBackwardIncompatible(tc); });
  // Level 3
  calcGuard(tc, modelChangeLogEntriesFieldTypes, "is_untraceable_breaking_change", () => { tc.is_untraceable_breaking_change = calcModelChangeLogEntriesIsUntraceableBreakingChange(tc); });
  return tc;
}

/** Reads ModelChangeLogEntries rows from a JSON array file. */
export function loadModelChangeLogEntriesRows(file: string): ModelChangeLogEntriesRow[] {
  return loadRows(file, { fields: modelChangeLogEntriesFieldTypes }) as unknown as ModelChangeLogEntriesRow[];
}

// =============================================================================
// DRIFTOBSERVATIONS TABLE
// Observed drift: places where a model no longer matches the organization it describes, how each was detected, and what drove it.
// =============================================================================

/** A row in the DriftObservations table. */
export interface DriftObservationsRow {
  /** Stored identifier. */
  drift_observation_id: string;
  /** Display name. */
  name: string | null;
  /** Model that drifted. */
  governed_model: string | null;
  /** Representation that no longer matches, when one. */
  procedure_version: string | null;
  /** When observed. */
  observed_at: string | null;
  /** Who observed it. */
  observed_by_agent: string | null;
  /** StewardReview, StalenessQuery, ValidationSuite or ExpertWrongAnswer. */
  detected_by: string | null;
  /** PracticeMismatch, ScopeExpansion or DependencyChange. */
  drift_kind: string | null;
  /** ShiftingRequirement, NewTechnology or CompetitivePressure. */
  drift_cause: string | null;
  /** What no longer matches. */
  description: string | null;
  /** Release the model was at when the drift began. */
  since_release: string | null;
  /** When resolved. */
  resolved_at: string | null;
  /** Whether that release passed every acceptance validation. */
  release_passed_validation: boolean | null;
  /** When that release was issued. */
  release_issued_at: string | null;
  /** TRUE for an unresolved observation that a representation no longer matches how the process runs. */
  is_open_practice_mismatch: boolean | null;
  /** TRUE when drift on a release that passed its validation was found by something other than the validation suite. */
  went_undetected_by_passing_suite: boolean | null;
  /** TRUE when a release that passed all its validation drifted afterwards anyway. */
  drift_follows_clean_release: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const driftObservationsFieldTypes: Record<string, FieldType> = {
  drift_observation_id: "string",
  name: "*string",
  governed_model: "*string",
  procedure_version: "*string",
  observed_at: "*string",
  observed_by_agent: "*string",
  detected_by: "*string",
  drift_kind: "*string",
  drift_cause: "*string",
  description: "*string",
  since_release: "*string",
  resolved_at: "*string",
  release_passed_validation: "*bool",
  release_issued_at: "*string",
  is_open_practice_mismatch: "*bool",
  went_undetected_by_passing_suite: "*bool",
  drift_follows_clean_release: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{GovernedModel}} & ": " & LEFT({{Description}}, 50) */
export function calcDriftObservationsName(tc: DriftObservationsRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.governed_model)), vS(": "), erbText(erbLeft(vStr(tc.description), vI(50)))));
}

/** Computes the IsOpenPracticeMismatch calculated field.
 *  TRUE for an unresolved observation that a representation no longer matches how the process runs.
 *  Formula: =AND({{DriftKind}} = "PracticeMismatch", {{ResolvedAt}} = "") */
export function calcDriftObservationsIsOpenPracticeMismatch(tc: DriftObservationsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.drift_kind)), vS("PracticeMismatch"))), erbBool3(erbIsBlank(vStr(tc.resolved_at)))));
}

/** Computes the WentUndetectedByPassingSuite calculated field.
 *  TRUE when drift on a release that passed its validation was found by something other than the validation suite.
 *  Formula: =AND({{SinceRelease}} <> "", {{ReleasePassedValidation}}, {{DetectedBy}} <> "ValidationSuite") */
export function calcDriftObservationsWentUndetectedByPassingSuite(tc: DriftObservationsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.since_release))), erbBool3(vBool(tc.release_passed_validation)), erbBool3(erbNe(erbNullif(vStr(tc.detected_by)), vS("ValidationSuite")))));
}

/** Computes the DriftFollowsCleanRelease calculated field.
 *  TRUE when a release that passed all its validation drifted afterwards anyway.
 *  Formula: =AND({{SinceRelease}} <> "", {{ReleasePassedValidation}}, {{ObservedAt}} > {{ReleaseIssuedAt}}) */
export function calcDriftObservationsDriftFollowsCleanRelease(tc: DriftObservationsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.since_release))), erbBool3(vBool(tc.release_passed_validation)), erbBool3(erbCmp(erbNullif(vStr(tc.observed_at)), ">", vStr(tc.release_issued_at)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeDriftObservations(tc: DriftObservationsRow): DriftObservationsRow {
  // Level 1
  calcGuard(tc, driftObservationsFieldTypes, "name", () => { tc.name = calcDriftObservationsName(tc); });
  calcGuard(tc, driftObservationsFieldTypes, "is_open_practice_mismatch", () => { tc.is_open_practice_mismatch = calcDriftObservationsIsOpenPracticeMismatch(tc); });
  calcGuard(tc, driftObservationsFieldTypes, "went_undetected_by_passing_suite", () => { tc.went_undetected_by_passing_suite = calcDriftObservationsWentUndetectedByPassingSuite(tc); });
  calcGuard(tc, driftObservationsFieldTypes, "drift_follows_clean_release", () => { tc.drift_follows_clean_release = calcDriftObservationsDriftFollowsCleanRelease(tc); });
  return tc;
}

/** Reads DriftObservations rows from a JSON array file. */
export function loadDriftObservationsRows(file: string): DriftObservationsRow[] {
  return loadRows(file, { fields: driftObservationsFieldTypes }) as unknown as DriftObservationsRow[];
}

// =============================================================================
// SOURCINGFUNCTIONS TABLE
// Business functions an organization classifies as retained core or sends out for execution, with who executes them and who holds the knowledge of what is built and of how it is built.
// =============================================================================

/** A row in the SourcingFunctions table. */
export interface SourcingFunctionsRow {
  /** Stored identifier. */
  sourcing_function_id: string;
  /** Display name. */
  name: string | null;
  /** The function. */
  label: string | null;
  /** The organization whose function this is. */
  client_organization: string | null;
  /** The modeled procedure that carries the function, when there is one. */
  procedure: string | null;
  /** RetainedCore, or SentOutExecution for a function classified as execution to be sent out. */
  sourcing_class: string | null;
  /** Transactional (routine) or ExpertiseHeavy (analytical, design or engineering judgment). */
  work_nature: string | null;
  /** TRUE when the organization cannot deliver its strategy without the function. */
  is_strategically_vital: boolean | null;
  /** TRUE when the function is part of delivering the organization's own products. */
  delivers_own_product: boolean | null;
  /** The organization that actually performs the work. */
  executing_organization: string | null;
  /** The party that holds what is to be built or delivered. */
  specification_holder: string | null;
  /** The party that holds how it is built or performed. */
  method_holder: string | null;
  /** When the current execution arrangement began. */
  sourced_since: string | null;
  /** Why the function was placed where it is (CoreCompetencyFocus, CostReduction, Capability). */
  sourcing_rationale: string | null;
  /** TRUE when an organization other than the client performs the work. */
  is_outsourced: boolean | null;
  /** TRUE for routine transactional work performed by a provider. */
  is_business_process_outsourcing: boolean | null;
  /** TRUE for expertise-heavy work performed by a provider, the kind that builds deep process knowledge. */
  is_knowledge_process_outsourcing: boolean | null;
  /** TRUE when strategically vital, expertise-heavy work is classified as execution to send out rather than retained core. */
  is_vital_expertise_classed_non_core: boolean | null;
  /** TRUE when different parties hold what is to be built and how it is built. */
  is_what_how_split: boolean | null;
  /** TRUE when the knowledge of how the work is really performed is held by a party other than the client. */
  is_method_knowledge_held_outside: boolean | null;
  /** TRUE when the client declares it holds the method knowledge of a function a provider executes. */
  claims_how_without_doing: boolean | null;
  /** TRUE for a strategically vital, expertise-heavy function. */
  is_vital_expertise_process: boolean | null;
  /** TRUE for a strategically vital, expertise-heavy function a provider performs. */
  is_outsourced_vital_expertise_process: boolean | null;
  /** Audit items comparing held and needed knowledge for this function. */
  audit_item_count: number | null;
  /** Audit items that found knowledge the client relies on a provider for. */
  dependency_count: number | null;
  /** Audit items that found knowledge nobody available to the client holds. */
  coverage_gap_count: number | null;
  /** Audit items about specification knowledge. */
  specification_audit_count: number | null;
  /** Specification items where the client holds less than it needs. */
  specification_shortfall_count: number | null;
  /** Method items where the client holds less than it needs. */
  method_shortfall_count: number | null;
  /** Engagements for this function whose documentation stays the provider's property. */
  provider_ip_documentation_count: number | null;
  /** TRUE when a product-delivering function is performed by a provider that keeps the documentation, the client's audited specification knowledge is complete, and its method knowledge falls short. */
  designs_what_it_cannot_build: boolean | null;
  /** TRUE when an outsourced or strategically vital function has never been audited for held against needed knowledge. */
  is_unaudited_function: boolean | null;
  /** Deliberate knowledge capture initiatives for this function. */
  capture_initiative_count: number | null;
  /** TRUE for a vital, expertise-heavy function that is outsourced or has a coverage gap and has no deliberate capture initiative. */
  is_uncaptured_priority_process: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const sourcingFunctionsFieldTypes: Record<string, FieldType> = {
  sourcing_function_id: "string",
  name: "*string",
  label: "*string",
  client_organization: "*string",
  procedure: "*string",
  sourcing_class: "*string",
  work_nature: "*string",
  is_strategically_vital: "*bool",
  delivers_own_product: "*bool",
  executing_organization: "*string",
  specification_holder: "*string",
  method_holder: "*string",
  sourced_since: "*string",
  sourcing_rationale: "*string",
  is_outsourced: "*bool",
  is_business_process_outsourcing: "*bool",
  is_knowledge_process_outsourcing: "*bool",
  is_vital_expertise_classed_non_core: "*bool",
  is_what_how_split: "*bool",
  is_method_knowledge_held_outside: "*bool",
  claims_how_without_doing: "*bool",
  is_vital_expertise_process: "*bool",
  is_outsourced_vital_expertise_process: "*bool",
  audit_item_count: "*int",
  dependency_count: "*int",
  coverage_gap_count: "*int",
  specification_audit_count: "*int",
  specification_shortfall_count: "*int",
  method_shortfall_count: "*int",
  provider_ip_documentation_count: "*int",
  designs_what_it_cannot_build: "*bool",
  is_unaudited_function: "*bool",
  capture_initiative_count: "*int",
  is_uncaptured_priority_process: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{ClientOrganization}} & ": " & {{Label}} */
export function calcSourcingFunctionsName(tc: SourcingFunctionsRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.client_organization)), vS(": "), erbText(vStr(tc.label))));
}

/** Computes the IsOutsourced calculated field.
 *  TRUE when an organization other than the client performs the work.
 *  Formula: ={{ExecutingOrganization}} <> {{ClientOrganization}} */
export function calcSourcingFunctionsIsOutsourced(tc: SourcingFunctionsRow): boolean | null {
  return toBoolPtr(erbNe(erbNullif(vStr(tc.executing_organization)), erbNullif(vStr(tc.client_organization))));
}

/** Computes the IsBusinessProcessOutsourcing calculated field.
 *  TRUE for routine transactional work performed by a provider.
 *  Formula: =AND({{IsOutsourced}}, {{WorkNature}} = "Transactional") */
export function calcSourcingFunctionsIsBusinessProcessOutsourcing(tc: SourcingFunctionsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_outsourced)), erbBool3(erbEq(erbNullif(vStr(tc.work_nature)), vS("Transactional")))));
}

/** Computes the IsKnowledgeProcessOutsourcing calculated field.
 *  TRUE for expertise-heavy work performed by a provider, the kind that builds deep process knowledge.
 *  Formula: =AND({{IsOutsourced}}, {{WorkNature}} = "ExpertiseHeavy") */
export function calcSourcingFunctionsIsKnowledgeProcessOutsourcing(tc: SourcingFunctionsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_outsourced)), erbBool3(erbEq(erbNullif(vStr(tc.work_nature)), vS("ExpertiseHeavy")))));
}

/** Computes the IsVitalExpertiseClassedNonCore calculated field.
 *  TRUE when strategically vital, expertise-heavy work is classified as execution to send out rather than retained core.
 *  Formula: =AND({{SourcingClass}} = "SentOutExecution", {{IsStrategicallyVital}}, {{WorkNature}} = "ExpertiseHeavy") */
export function calcSourcingFunctionsIsVitalExpertiseClassedNonCore(tc: SourcingFunctionsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.sourcing_class)), vS("SentOutExecution"))), erbIsTrue(vBool(tc.is_strategically_vital)), erbBool3(erbEq(erbNullif(vStr(tc.work_nature)), vS("ExpertiseHeavy")))));
}

/** Computes the IsWhatHowSplit calculated field.
 *  TRUE when different parties hold what is to be built and how it is built.
 *  Formula: ={{SpecificationHolder}} <> {{MethodHolder}} */
export function calcSourcingFunctionsIsWhatHowSplit(tc: SourcingFunctionsRow): boolean | null {
  return toBoolPtr(erbNe(erbNullif(vStr(tc.specification_holder)), erbNullif(vStr(tc.method_holder))));
}

/** Computes the IsMethodKnowledgeHeldOutside calculated field.
 *  TRUE when the knowledge of how the work is really performed is held by a party other than the client.
 *  Formula: ={{MethodHolder}} <> {{ClientOrganization}} */
export function calcSourcingFunctionsIsMethodKnowledgeHeldOutside(tc: SourcingFunctionsRow): boolean | null {
  return toBoolPtr(erbNe(erbNullif(vStr(tc.method_holder)), erbNullif(vStr(tc.client_organization))));
}

/** Computes the ClaimsHowWithoutDoing calculated field.
 *  TRUE when the client declares it holds the method knowledge of a function a provider executes.
 *  Formula: =AND({{MethodHolder}} = {{ClientOrganization}}, {{IsOutsourced}}) */
export function calcSourcingFunctionsClaimsHowWithoutDoing(tc: SourcingFunctionsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.method_holder)), erbNullif(vStr(tc.client_organization)))), erbBool3(vBool(tc.is_outsourced))));
}

/** Computes the IsVitalExpertiseProcess calculated field.
 *  TRUE for a strategically vital, expertise-heavy function.
 *  Formula: =AND({{IsStrategicallyVital}}, {{WorkNature}} = "ExpertiseHeavy") */
export function calcSourcingFunctionsIsVitalExpertiseProcess(tc: SourcingFunctionsRow): boolean | null {
  return toBoolPtr(erbAnd(erbIsTrue(vBool(tc.is_strategically_vital)), erbBool3(erbEq(erbNullif(vStr(tc.work_nature)), vS("ExpertiseHeavy")))));
}

/** Computes the IsOutsourcedVitalExpertiseProcess calculated field.
 *  TRUE for a strategically vital, expertise-heavy function a provider performs.
 *  Formula: =AND({{IsVitalExpertiseProcess}}, {{IsOutsourced}}) */
export function calcSourcingFunctionsIsOutsourcedVitalExpertiseProcess(tc: SourcingFunctionsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_vital_expertise_process)), erbBool3(vBool(tc.is_outsourced))));
}

/** Computes the DesignsWhatItCannotBuild calculated field.
 *  TRUE when a product-delivering function is performed by a provider that keeps the documentation, the client's audited specification knowledge is complete, and its method knowledge falls short.
 *  Formula: =AND({{DeliversOwnProduct}}, {{IsOutsourced}}, {{ProviderIpDocumentationCount}} > 0, {{SpecificationAuditCount}} > 0, {{SpecificationShortfallCount}} = 0, {{MethodShortfallCount}} > 0) */
export function calcSourcingFunctionsDesignsWhatItCannotBuild(tc: SourcingFunctionsRow): boolean | null {
  return toBoolPtr(erbAnd(erbIsTrue(vBool(tc.delivers_own_product)), erbBool3(vBool(tc.is_outsourced)), erbBool3(erbCmp(vInt(tc.provider_ip_documentation_count), ">", vI(0))), erbBool3(erbCmp(vInt(tc.specification_audit_count), ">", vI(0))), erbBool3(erbEq(vInt(tc.specification_shortfall_count), vI(0))), erbBool3(erbCmp(vInt(tc.method_shortfall_count), ">", vI(0)))));
}

/** Computes the IsUnauditedFunction calculated field.
 *  TRUE when an outsourced or strategically vital function has never been audited for held against needed knowledge.
 *  Formula: =AND(OR({{IsOutsourced}}, {{IsStrategicallyVital}}), {{AuditItemCount}} = 0) */
export function calcSourcingFunctionsIsUnauditedFunction(tc: SourcingFunctionsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbOr(erbBool3(vBool(tc.is_outsourced)), erbIsTrue(vBool(tc.is_strategically_vital)))), erbBool3(erbEq(vInt(tc.audit_item_count), vI(0)))));
}

/** Computes the IsUncapturedPriorityProcess calculated field.
 *  TRUE for a vital, expertise-heavy function that is outsourced or has a coverage gap and has no deliberate capture initiative.
 *  Formula: =AND({{IsVitalExpertiseProcess}}, OR({{IsOutsourced}}, {{CoverageGapCount}} > 0), {{CaptureInitiativeCount}} = 0) */
export function calcSourcingFunctionsIsUncapturedPriorityProcess(tc: SourcingFunctionsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_vital_expertise_process)), erbBool3(erbOr(erbBool3(vBool(tc.is_outsourced)), erbBool3(erbCmp(vInt(tc.coverage_gap_count), ">", vI(0))))), erbBool3(erbEq(vInt(tc.capture_initiative_count), vI(0)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeSourcingFunctions(tc: SourcingFunctionsRow): SourcingFunctionsRow {
  // Level 1
  calcGuard(tc, sourcingFunctionsFieldTypes, "name", () => { tc.name = calcSourcingFunctionsName(tc); });
  calcGuard(tc, sourcingFunctionsFieldTypes, "is_outsourced", () => { tc.is_outsourced = calcSourcingFunctionsIsOutsourced(tc); });
  calcGuard(tc, sourcingFunctionsFieldTypes, "is_vital_expertise_classed_non_core", () => { tc.is_vital_expertise_classed_non_core = calcSourcingFunctionsIsVitalExpertiseClassedNonCore(tc); });
  calcGuard(tc, sourcingFunctionsFieldTypes, "is_what_how_split", () => { tc.is_what_how_split = calcSourcingFunctionsIsWhatHowSplit(tc); });
  calcGuard(tc, sourcingFunctionsFieldTypes, "is_method_knowledge_held_outside", () => { tc.is_method_knowledge_held_outside = calcSourcingFunctionsIsMethodKnowledgeHeldOutside(tc); });
  calcGuard(tc, sourcingFunctionsFieldTypes, "is_vital_expertise_process", () => { tc.is_vital_expertise_process = calcSourcingFunctionsIsVitalExpertiseProcess(tc); });
  // Level 2
  calcGuard(tc, sourcingFunctionsFieldTypes, "is_business_process_outsourcing", () => { tc.is_business_process_outsourcing = calcSourcingFunctionsIsBusinessProcessOutsourcing(tc); });
  calcGuard(tc, sourcingFunctionsFieldTypes, "is_knowledge_process_outsourcing", () => { tc.is_knowledge_process_outsourcing = calcSourcingFunctionsIsKnowledgeProcessOutsourcing(tc); });
  calcGuard(tc, sourcingFunctionsFieldTypes, "claims_how_without_doing", () => { tc.claims_how_without_doing = calcSourcingFunctionsClaimsHowWithoutDoing(tc); });
  calcGuard(tc, sourcingFunctionsFieldTypes, "is_outsourced_vital_expertise_process", () => { tc.is_outsourced_vital_expertise_process = calcSourcingFunctionsIsOutsourcedVitalExpertiseProcess(tc); });
  calcGuard(tc, sourcingFunctionsFieldTypes, "designs_what_it_cannot_build", () => { tc.designs_what_it_cannot_build = calcSourcingFunctionsDesignsWhatItCannotBuild(tc); });
  calcGuard(tc, sourcingFunctionsFieldTypes, "is_unaudited_function", () => { tc.is_unaudited_function = calcSourcingFunctionsIsUnauditedFunction(tc); });
  calcGuard(tc, sourcingFunctionsFieldTypes, "is_uncaptured_priority_process", () => { tc.is_uncaptured_priority_process = calcSourcingFunctionsIsUncapturedPriorityProcess(tc); });
  return tc;
}

/** Reads SourcingFunctions rows from a JSON array file. */
export function loadSourcingFunctionsRows(file: string): SourcingFunctionsRow[] {
  return loadRows(file, { fields: sourcingFunctionsFieldTypes }) as unknown as SourcingFunctionsRow[];
}

// =============================================================================
// KNOWLEDGEAUDITS TABLE
// Audits of the procedural knowledge an organization holds against what it needs.
// =============================================================================

/** A row in the KnowledgeAudits table. */
export interface KnowledgeAuditsRow {
  /** Stored identifier. */
  knowledge_audit_id: string;
  /** Display name. */
  name: string | null;
  /** Audited organization. */
  organization: string | null;
  /** Audit title. */
  title: string | null;
  /** When the audit was concluded. */
  conducted_at: string | null;
  /** Who led it. */
  conducted_by_agent: string | null;
  /** How the audit states its problem: KnowledgeDeficit, or CostEfficiency. */
  problem_framing: string | null;
  /** Items where held knowledge falls short of what is needed. */
  finding_count: number | null;
  /** TRUE when an audit finds knowledge shortfalls but frames them as a cost or efficiency problem instead of acknowledging a knowledge deficit. */
  treats_deficit_as_cost_problem: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const knowledgeAuditsFieldTypes: Record<string, FieldType> = {
  knowledge_audit_id: "string",
  name: "*string",
  organization: "*string",
  title: "*string",
  conducted_at: "*string",
  conducted_by_agent: "*string",
  problem_framing: "*string",
  finding_count: "*int",
  treats_deficit_as_cost_problem: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{Organization}} & ": " & {{Title}} */
export function calcKnowledgeAuditsName(tc: KnowledgeAuditsRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.organization)), vS(": "), erbText(vStr(tc.title))));
}

/** Computes the TreatsDeficitAsCostProblem calculated field.
 *  TRUE when an audit finds knowledge shortfalls but frames them as a cost or efficiency problem instead of acknowledging a knowledge deficit.
 *  Formula: =AND({{FindingCount}} > 0, {{ProblemFraming}} <> "KnowledgeDeficit") */
export function calcKnowledgeAuditsTreatsDeficitAsCostProblem(tc: KnowledgeAuditsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.finding_count), ">", vI(0))), erbBool3(erbNe(erbNullif(vStr(tc.problem_framing)), vS("KnowledgeDeficit")))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeKnowledgeAudits(tc: KnowledgeAuditsRow): KnowledgeAuditsRow {
  // Level 1
  calcGuard(tc, knowledgeAuditsFieldTypes, "name", () => { tc.name = calcKnowledgeAuditsName(tc); });
  calcGuard(tc, knowledgeAuditsFieldTypes, "treats_deficit_as_cost_problem", () => { tc.treats_deficit_as_cost_problem = calcKnowledgeAuditsTreatsDeficitAsCostProblem(tc); });
  return tc;
}

/** Reads KnowledgeAudits rows from a JSON array file. */
export function loadKnowledgeAuditsRows(file: string): KnowledgeAuditsRow[] {
  return loadRows(file, { fields: knowledgeAuditsFieldTypes }) as unknown as KnowledgeAuditsRow[];
}

// =============================================================================
// KNOWLEDGEAUDITITEMS TABLE
// One knowledge area an audit assessed: the level needed, the level the client holds, and any provider that holds it.
// =============================================================================

/** A row in the KnowledgeAuditItems table. */
export interface KnowledgeAuditItemsRow {
  /** Stored identifier. */
  knowledge_audit_item_id: string;
  /** Display name. */
  name: string | null;
  /** Audit. */
  knowledge_audit: string | null;
  /** Function the knowledge belongs to. */
  sourcing_function: string | null;
  /** What must be known. */
  knowledge_area: string | null;
  /** Specification (what is built) or Method (how it is built). */
  knowledge_kind: string | null;
  /** Level needed: 0 none, 1 aware, 2 can perform with help, 3 can perform and teach. */
  needed_level: number | null;
  /** Level the client's own people hold, on the same scale. */
  held_internal_level: number | null;
  /** Provider that holds the knowledge, when one does. */
  provider_holding_knowledge: string | null;
  /** Level the provider holds. */
  provider_held_level: number | null;
  /** Internal teams that hold the knowledge at the needed level. */
  internal_holding_team_count: number | null;
  /** The knowledge gap row that names this finding. */
  named_knowledge_gap: string | null;
  /** The audited organization. */
  client_organization: string | null;
  /** TRUE when the client holds less than it needs. */
  has_internal_shortfall: boolean | null;
  /** TRUE when the client falls short and relies on a provider that holds the knowledge at the needed level. */
  is_knowledge_dependency: boolean | null;
  /** TRUE when the client falls short and no provider available to it holds the knowledge either. */
  is_coverage_gap: boolean | null;
  /** TRUE when an audit found a gap or dependency and nobody recorded it as a named knowledge gap. */
  is_unnamed_finding: boolean | null;
  /** TRUE when knowledge the client does hold sits with exactly one internal team. */
  is_single_team_silo: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const knowledgeAuditItemsFieldTypes: Record<string, FieldType> = {
  knowledge_audit_item_id: "string",
  name: "*string",
  knowledge_audit: "*string",
  sourcing_function: "*string",
  knowledge_area: "*string",
  knowledge_kind: "*string",
  needed_level: "*int",
  held_internal_level: "*int",
  provider_holding_knowledge: "*string",
  provider_held_level: "*int",
  internal_holding_team_count: "*int",
  named_knowledge_gap: "*string",
  client_organization: "*string",
  has_internal_shortfall: "*bool",
  is_knowledge_dependency: "*bool",
  is_coverage_gap: "*bool",
  is_unnamed_finding: "*bool",
  is_single_team_silo: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{KnowledgeAudit}} & " / " & {{KnowledgeArea}} */
export function calcKnowledgeAuditItemsName(tc: KnowledgeAuditItemsRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.knowledge_audit)), vS(" / "), erbText(vStr(tc.knowledge_area))));
}

/** Computes the HasInternalShortfall calculated field.
 *  TRUE when the client holds less than it needs.
 *  Formula: ={{HeldInternalLevel}} < {{NeededLevel}} */
export function calcKnowledgeAuditItemsHasInternalShortfall(tc: KnowledgeAuditItemsRow): boolean | null {
  return toBoolPtr(erbCmp(erbNullif(vInt(tc.held_internal_level)), "<", erbNullif(vInt(tc.needed_level))));
}

/** Computes the IsKnowledgeDependency calculated field.
 *  TRUE when the client falls short and relies on a provider that holds the knowledge at the needed level.
 *  Formula: =AND({{HasInternalShortfall}}, {{ProviderHoldingKnowledge}} <> "", {{ProviderHeldLevel}} >= {{NeededLevel}}) */
export function calcKnowledgeAuditItemsIsKnowledgeDependency(tc: KnowledgeAuditItemsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.has_internal_shortfall)), erbBool3(erbIsNotBlank(vStr(tc.provider_holding_knowledge))), erbBool3(erbCmp(erbNullif(vInt(tc.provider_held_level)), ">=", erbNullif(vInt(tc.needed_level))))));
}

/** Computes the IsCoverageGap calculated field.
 *  TRUE when the client falls short and no provider available to it holds the knowledge either.
 *  Formula: =AND({{HasInternalShortfall}}, NOT({{IsKnowledgeDependency}})) */
export function calcKnowledgeAuditItemsIsCoverageGap(tc: KnowledgeAuditItemsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.has_internal_shortfall)), erbBool3(erbNot(erbBool3(vBool(tc.is_knowledge_dependency))))));
}

/** Computes the IsUnnamedFinding calculated field.
 *  TRUE when an audit found a gap or dependency and nobody recorded it as a named knowledge gap.
 *  Formula: =AND({{HasInternalShortfall}}, {{NamedKnowledgeGap}} = "") */
export function calcKnowledgeAuditItemsIsUnnamedFinding(tc: KnowledgeAuditItemsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.has_internal_shortfall)), erbBool3(erbIsBlank(vStr(tc.named_knowledge_gap)))));
}

/** Computes the IsSingleTeamSilo calculated field.
 *  TRUE when knowledge the client does hold sits with exactly one internal team.
 *  Formula: =AND({{HeldInternalLevel}} >= {{NeededLevel}}, {{InternalHoldingTeamCount}} = 1) */
export function calcKnowledgeAuditItemsIsSingleTeamSilo(tc: KnowledgeAuditItemsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbCmp(erbNullif(vInt(tc.held_internal_level)), ">=", erbNullif(vInt(tc.needed_level)))), erbBool3(erbEq(erbNullif(vInt(tc.internal_holding_team_count)), vI(1)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeKnowledgeAuditItems(tc: KnowledgeAuditItemsRow): KnowledgeAuditItemsRow {
  // Level 1
  calcGuard(tc, knowledgeAuditItemsFieldTypes, "name", () => { tc.name = calcKnowledgeAuditItemsName(tc); });
  calcGuard(tc, knowledgeAuditItemsFieldTypes, "has_internal_shortfall", () => { tc.has_internal_shortfall = calcKnowledgeAuditItemsHasInternalShortfall(tc); });
  calcGuard(tc, knowledgeAuditItemsFieldTypes, "is_single_team_silo", () => { tc.is_single_team_silo = calcKnowledgeAuditItemsIsSingleTeamSilo(tc); });
  // Level 2
  calcGuard(tc, knowledgeAuditItemsFieldTypes, "is_knowledge_dependency", () => { tc.is_knowledge_dependency = calcKnowledgeAuditItemsIsKnowledgeDependency(tc); });
  calcGuard(tc, knowledgeAuditItemsFieldTypes, "is_unnamed_finding", () => { tc.is_unnamed_finding = calcKnowledgeAuditItemsIsUnnamedFinding(tc); });
  // Level 3
  calcGuard(tc, knowledgeAuditItemsFieldTypes, "is_coverage_gap", () => { tc.is_coverage_gap = calcKnowledgeAuditItemsIsCoverageGap(tc); });
  return tc;
}

/** Reads KnowledgeAuditItems rows from a JSON array file. */
export function loadKnowledgeAuditItemsRows(file: string): KnowledgeAuditItemsRow[] {
  return loadRows(file, { fields: knowledgeAuditItemsFieldTypes }) as unknown as KnowledgeAuditItemsRow[];
}

