// =============================================================================
// PROVIDERENGAGEMENTS TABLE
// A client's relationship with a provider for one function, with the knowledge terms it carries.
// =============================================================================

/** A row in the ProviderEngagements table. */
export interface ProviderEngagementsRow {
  /** Stored identifier. */
  provider_engagement_id: string;
  /** Display name. */
  name: string | null;
  /** Client. */
  client_organization: string | null;
  /** Provider. */
  provider: string | null;
  /** Function the provider performs. */
  sourcing_function: string | null;
  /** When the engagement started. */
  started_at: string | null;
  /** Contract term in months. */
  term_months: number | null;
  /** Active or Ended. */
  status: string | null;
  /** ProviderIP when the documentation the provider produces stays its intellectual property; ClientOwned or Joint otherwise. */
  documentation_ownership: string | null;
  /** Any duty the provider carries to build up the client's knowledge; blank when there is none. */
  knowledge_duty_terms: string | null;
  /** TRUE when the provider positions its procedural know-how as its competitive differentiator. */
  provider_treats_know_how_as_differentiator: boolean | null;
  /** TRUE when the contract gives the client access to the process knowledge needed to run the operation. */
  has_knowledge_access_clause: boolean | null;
  /** How the knowledge comes back to the client; blank when nobody planned it. */
  knowledge_return_plan: string | null;
  /** TRUE for a running engagement. */
  is_active: boolean | null;
  /** Audit findings where the client relies on this provider's knowledge. */
  relied_dependency_count: number | null;
  /** TRUE when the client relies on a provider's knowledge, the provider keeps the documentation as its property, and nobody planned how the knowledge comes back. */
  is_unplanned_knowledge_return: boolean | null;
  /** TRUE when a running engagement is a knowledge dependency and the client has no contractual access to that knowledge. */
  is_knowledge_access_unsecured: boolean | null;
  /** Knowledge deliverables the engagement requires. */
  required_deliverable_count: number | null;
  /** Deliverables that move knowledge from the provider to the client. */
  to_client_required_count: number | null;
  /** Delivered knowledge moving from provider to client. */
  to_client_delivered_count: number | null;
  /** Delivered knowledge moving from client to provider. */
  to_provider_delivered_count: number | null;
  /** Knowledge assets the client and provider build jointly. */
  joint_deliverable_count: number | null;
  /** TRUE when a running engagement requires no knowledge deliverable at all. */
  lacks_knowledge_deliverables: boolean | null;
  /** TRUE when a running engagement has knowledge deliverables but knowledge has actually moved in only one direction. */
  is_one_way_learning: boolean | null;
  /** TRUE when a running engagement is contracted for under three years and builds no knowledge jointly. */
  is_short_term_without_joint_knowledge: boolean | null;
  /** TRUE when the engagement requires knowledge deliverables to the client and plans how the knowledge comes back. */
  obliges_knowledge_flow_back: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const providerEngagementsFieldTypes: Record<string, FieldType> = {
  provider_engagement_id: "string",
  name: "*string",
  client_organization: "*string",
  provider: "*string",
  sourcing_function: "*string",
  started_at: "*string",
  term_months: "*int",
  status: "*string",
  documentation_ownership: "*string",
  knowledge_duty_terms: "*string",
  provider_treats_know_how_as_differentiator: "*bool",
  has_knowledge_access_clause: "*bool",
  knowledge_return_plan: "*string",
  is_active: "*bool",
  relied_dependency_count: "*int",
  is_unplanned_knowledge_return: "*bool",
  is_knowledge_access_unsecured: "*bool",
  required_deliverable_count: "*int",
  to_client_required_count: "*int",
  to_client_delivered_count: "*int",
  to_provider_delivered_count: "*int",
  joint_deliverable_count: "*int",
  lacks_knowledge_deliverables: "*bool",
  is_one_way_learning: "*bool",
  is_short_term_without_joint_knowledge: "*bool",
  obliges_knowledge_flow_back: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{ClientOrganization}} & " <- " & {{Provider}} */
export function calcProviderEngagementsName(tc: ProviderEngagementsRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.client_organization)), vS(" <- "), erbText(vStr(tc.provider))));
}

/** Computes the IsActive calculated field.
 *  TRUE for a running engagement.
 *  Formula: ={{Status}} = "Active" */
export function calcProviderEngagementsIsActive(tc: ProviderEngagementsRow): boolean | null {
  return toBoolPtr(erbEq(erbNullif(vStr(tc.status)), vS("Active")));
}

/** Computes the IsUnplannedKnowledgeReturn calculated field.
 *  TRUE when the client relies on a provider's knowledge, the provider keeps the documentation as its property, and nobody planned how the knowledge comes back.
 *  Formula: =AND({{ReliedDependencyCount}} > 0, {{DocumentationOwnership}} = "ProviderIP", {{KnowledgeReturnPlan}} = "") */
export function calcProviderEngagementsIsUnplannedKnowledgeReturn(tc: ProviderEngagementsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.relied_dependency_count), ">", vI(0))), erbBool3(erbEq(erbNullif(vStr(tc.documentation_ownership)), vS("ProviderIP"))), erbBool3(erbIsBlank(vStr(tc.knowledge_return_plan)))));
}

/** Computes the IsKnowledgeAccessUnsecured calculated field.
 *  TRUE when a running engagement is a knowledge dependency and the client has no contractual access to that knowledge.
 *  Formula: =AND({{IsActive}}, {{ReliedDependencyCount}} > 0, {{HasKnowledgeAccessClause}} = FALSE) */
export function calcProviderEngagementsIsKnowledgeAccessUnsecured(tc: ProviderEngagementsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_active)), erbBool3(erbCmp(vInt(tc.relied_dependency_count), ">", vI(0))), erbBool3(erbEq(erbNullif(vBool(tc.has_knowledge_access_clause)), vB(false)))));
}

/** Computes the LacksKnowledgeDeliverables calculated field.
 *  TRUE when a running engagement requires no knowledge deliverable at all.
 *  Formula: =AND({{IsActive}}, {{RequiredDeliverableCount}} = 0) */
export function calcProviderEngagementsLacksKnowledgeDeliverables(tc: ProviderEngagementsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_active)), erbBool3(erbEq(vInt(tc.required_deliverable_count), vI(0)))));
}

/** Computes the IsOneWayLearning calculated field.
 *  TRUE when a running engagement has knowledge deliverables but knowledge has actually moved in only one direction.
 *  Formula: =AND({{IsActive}}, {{RequiredDeliverableCount}} > 0, OR({{ToClientDeliveredCount}} = 0, {{ToProviderDeliveredCount}} = 0)) */
export function calcProviderEngagementsIsOneWayLearning(tc: ProviderEngagementsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_active)), erbBool3(erbCmp(vInt(tc.required_deliverable_count), ">", vI(0))), erbBool3(erbOr(erbBool3(erbEq(vInt(tc.to_client_delivered_count), vI(0))), erbBool3(erbEq(vInt(tc.to_provider_delivered_count), vI(0)))))));
}

/** Computes the IsShortTermWithoutJointKnowledge calculated field.
 *  TRUE when a running engagement is contracted for under three years and builds no knowledge jointly.
 *  Formula: =AND({{IsActive}}, {{TermMonths}} < 36, {{JointDeliverableCount}} = 0) */
export function calcProviderEngagementsIsShortTermWithoutJointKnowledge(tc: ProviderEngagementsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_active)), erbBool3(erbCmp(erbNullif(vInt(tc.term_months)), "<", vI(36))), erbBool3(erbEq(vInt(tc.joint_deliverable_count), vI(0)))));
}

/** Computes the ObligesKnowledgeFlowBack calculated field.
 *  TRUE when the engagement requires knowledge deliverables to the client and plans how the knowledge comes back.
 *  Formula: =AND({{ToClientRequiredCount}} > 0, {{KnowledgeReturnPlan}} <> "") */
export function calcProviderEngagementsObligesKnowledgeFlowBack(tc: ProviderEngagementsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.to_client_required_count), ">", vI(0))), erbBool3(erbIsNotBlank(vStr(tc.knowledge_return_plan)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeProviderEngagements(tc: ProviderEngagementsRow): ProviderEngagementsRow {
  // Level 1
  calcGuard(tc, providerEngagementsFieldTypes, "name", () => { tc.name = calcProviderEngagementsName(tc); });
  calcGuard(tc, providerEngagementsFieldTypes, "is_active", () => { tc.is_active = calcProviderEngagementsIsActive(tc); });
  calcGuard(tc, providerEngagementsFieldTypes, "is_unplanned_knowledge_return", () => { tc.is_unplanned_knowledge_return = calcProviderEngagementsIsUnplannedKnowledgeReturn(tc); });
  calcGuard(tc, providerEngagementsFieldTypes, "obliges_knowledge_flow_back", () => { tc.obliges_knowledge_flow_back = calcProviderEngagementsObligesKnowledgeFlowBack(tc); });
  // Level 2
  calcGuard(tc, providerEngagementsFieldTypes, "is_knowledge_access_unsecured", () => { tc.is_knowledge_access_unsecured = calcProviderEngagementsIsKnowledgeAccessUnsecured(tc); });
  calcGuard(tc, providerEngagementsFieldTypes, "lacks_knowledge_deliverables", () => { tc.lacks_knowledge_deliverables = calcProviderEngagementsLacksKnowledgeDeliverables(tc); });
  calcGuard(tc, providerEngagementsFieldTypes, "is_one_way_learning", () => { tc.is_one_way_learning = calcProviderEngagementsIsOneWayLearning(tc); });
  calcGuard(tc, providerEngagementsFieldTypes, "is_short_term_without_joint_knowledge", () => { tc.is_short_term_without_joint_knowledge = calcProviderEngagementsIsShortTermWithoutJointKnowledge(tc); });
  return tc;
}

/** Reads ProviderEngagements rows from a JSON array file. */
export function loadProviderEngagementsRows(file: string): ProviderEngagementsRow[] {
  return loadRows(file, { fields: providerEngagementsFieldTypes }) as unknown as ProviderEngagementsRow[];
}

