/** Computes the IsLiveInProduction calculated field.
 *  TRUE for a production deployment running at the evaluation instant.
 *  Formula: =AND({{Environment}} = "Production", {{DeployedAt}} <= {{AsOfInstant}}, OR({{RetiredAt}} = "", {{RetiredAt}} > {{AsOfInstant}})) */
export function calcAiModelDeploymentsIsLiveInProduction(tc: AiModelDeploymentsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.environment)), vS("Production"))), erbBool3(erbCmp(erbNullif(vStr(tc.deployed_at)), "<=", vStr(tc.as_of_instant))), erbBool3(erbOr(erbBool3(erbIsBlank(vStr(tc.retired_at))), erbBool3(erbCmp(erbNullif(vStr(tc.retired_at)), ">", vStr(tc.as_of_instant)))))));
}

/** Computes the IsIsolatedRegistryFact calculated field.
 *  TRUE for a live production deployment whose agent fills no role and has produced no artifact the graph knows: a registry row with no context.
 *  Formula: =AND({{IsLiveInProduction}}, {{AssignmentLinkCount}} = 0, {{ArtifactLinkCount}} = 0) */
export function calcAiModelDeploymentsIsIsolatedRegistryFact(tc: AiModelDeploymentsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_live_in_production)), erbBool3(erbEq(vInt(tc.assignment_link_count), vI(0))), erbBool3(erbEq(vInt(tc.artifact_link_count), vI(0)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeAiModelDeployments(tc: AiModelDeploymentsRow): AiModelDeploymentsRow {
  // Level 1
  calcGuard(tc, aiModelDeploymentsFieldTypes, "name", () => { tc.name = calcAiModelDeploymentsName(tc); });
  calcGuard(tc, aiModelDeploymentsFieldTypes, "is_live_in_production", () => { tc.is_live_in_production = calcAiModelDeploymentsIsLiveInProduction(tc); });
  // Level 2
  calcGuard(tc, aiModelDeploymentsFieldTypes, "is_isolated_registry_fact", () => { tc.is_isolated_registry_fact = calcAiModelDeploymentsIsIsolatedRegistryFact(tc); });
  return tc;
}

