  calcGuard(tc, aiAgentAccountabilitiesFieldTypes, "is_accountable_to_non_person", () => { tc.is_accountable_to_non_person = calcAiAgentAccountabilitiesIsAccountableToNonPerson(tc); });
  // Level 2
