/** Computes the MissedTraversedImpact calculated field.
 *  TRUE when an assessment listed fewer affected steps than traversal of the artifact flow finds.
 *  Formula: ={{ListedAffectedStepCount}} < {{TraversedDownstreamStepCount}} */
export function calcAgentUpgradeAssessmentsMissedTraversedImpact(tc: AgentUpgradeAssessmentsRow): boolean | null {
  return toBoolPtr(erbCmp(erbNullif(vInt(tc.listed_affected_step_count)), "<", vInt(tc.traversed_downstream_step_count)));
}

/** Computes every calculated field of the row in dependency order. */
export function computeAgentUpgradeAssessments(tc: AgentUpgradeAssessmentsRow): AgentUpgradeAssessmentsRow {
  // Level 1
  calcGuard(tc, agentUpgradeAssessmentsFieldTypes, "name", () => { tc.name = calcAgentUpgradeAssessmentsName(tc); });
  calcGuard(tc, agentUpgradeAssessmentsFieldTypes, "missed_traversed_impact", () => { tc.missed_traversed_impact = calcAgentUpgradeAssessmentsMissedTraversedImpact(tc); });
  return tc;
}

/** Reads AgentUpgradeAssessments rows from a JSON array file. */
export function loadAgentUpgradeAssessmentsRows(file: string): AgentUpgradeAssessmentsRow[] {
  return loadRows(file, { fields: agentUpgradeAssessmentsFieldTypes }) as unknown as AgentUpgradeAssessmentsRow[];
}

