// =============================================================================
// ROLEASSIGNMENTUPDATETASKS TABLE
// The audit record of one change to who fills a role: what triggered it, who triggered it, when it was completed, and the run that depended on it.
// =============================================================================

/** A row in the RoleAssignmentUpdateTasks table. */
export interface RoleAssignmentUpdateTasksRow {
  /** Stored identifier. */
  role_assignment_update_task_id: string;
  /** Display name. */
  name: string | null;
  /** Role whose filler changes. */
  role: string | null;
  /** Policy governing the update. */
  governing_policy: string | null;
  /** Departure, ModelUpgrade, AiToHumanHandover or HumanToAutomationHandover. */
  trigger_event: string | null;
  /** Why the change was made. */
  reason: string | null;
  /** When the triggering event happened. */
  trigger_occurred_at: string | null;
  /** When someone triggered the update; blank when nobody did. */
  triggered_at: string | null;
  /** Who triggered it. */
  triggered_by_agent: string | null;
  /** When the assignment change was recorded in the model; blank when not yet. */
  completed_at: string | null;
  /** Assignment that ends. */
  ending_assignment: string | null;
  /** Assignment that replaces it, when there is one. */
  replacement_assignment: string | null;
  /** The first procedure run after the trigger that needed the role. */
  dependent_execution: string | null;
  /** The instant the row is judged against. */
  evaluation_context: string | null;
  /** The modeled evaluation instant. */
  as_of_instant: string | null;
  /** Role the policy makes responsible for triggering. */
  policy_trigger_owner_role: string | null;
  /** Assignments currently covering that role. */
  trigger_owner_cover_count: number | null;
  /** TRUE when governance names no role responsible for triggering the update, or names one nobody holds. */
  lacks_named_trigger_owner: boolean | null;
  /** Service level in hours. */
  policy_sla_hours: number | null;
  /** Minutes from the trigger to completion, or to the evaluation instant while incomplete. */
  elapsed_minutes: number | null;
  /** TRUE when no service level is defined, or the update took longer than it allows. */
  exceeded_update_sla: boolean | null;
  /** Role of the ending assignment. */
  ending_role: string | null;
  /** Role of the replacement assignment. */
  replacement_role: string | null;
  /** TRUE when a change of who does the work was made by moving it to a different role, so the steps bound to the old role had to be re-pointed. */
  changed_role_instead_of_assignment: boolean | null;
  /** Version the dependent run enacted. */
  dependent_run_version: string | null;
  /** When the dependent run started. */
  dependent_run_started_at: string | null;
  /** Steps of the dependent run's version assigned to the role. */
  dependent_run_role_step_count: number | null;
  /** TRUE when a run that needs the role started after the trigger and before the assignment change was recorded. */
  missed_next_dependent_run: boolean | null;
  /** Notices for the role in the dependent run that reached the wrong person or nobody. */
  failed_notice_count: number | null;
  /** TRUE when the assignment was still stale at a run that needed it and that run's notice for the role reached the wrong person or nobody. */
  stale_assignment_broke_routing: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const roleAssignmentUpdateTasksFieldTypes: Record<string, FieldType> = {
  role_assignment_update_task_id: "string",
  name: "*string",
  role: "*string",
  governing_policy: "*string",
  trigger_event: "*string",
  reason: "*string",
  trigger_occurred_at: "*string",
  triggered_at: "*string",
  triggered_by_agent: "*string",
  completed_at: "*string",
  ending_assignment: "*string",
  replacement_assignment: "*string",
  dependent_execution: "*string",
  evaluation_context: "*string",
  as_of_instant: "*string",
  policy_trigger_owner_role: "*string",
  trigger_owner_cover_count: "*int",
  lacks_named_trigger_owner: "*bool",
  policy_sla_hours: "*int",
  elapsed_minutes: "*float64",
  exceeded_update_sla: "*bool",
  ending_role: "*string",
  replacement_role: "*string",
  changed_role_instead_of_assignment: "*bool",
  dependent_run_version: "*string",
  dependent_run_started_at: "*string",
  dependent_run_role_step_count: "*int",
  missed_next_dependent_run: "*bool",
  failed_notice_count: "*int",
  stale_assignment_broke_routing: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{Role}} & " " & {{TriggerEvent}} & " @ " & {{TriggerOccurredAt}} */
export function calcRoleAssignmentUpdateTasksName(tc: RoleAssignmentUpdateTasksRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.role)), vS(" "), erbText(vStr(tc.trigger_event)), vS(" @ "), erbDatetimeText(vStr(tc.trigger_occurred_at))));
}

/** Computes the LacksNamedTriggerOwner calculated field.
 *  TRUE when governance names no role responsible for triggering the update, or names one nobody holds.
 *  Formula: =OR({{PolicyTriggerOwnerRole}} = "", {{TriggerOwnerCoverCount}} = 0) */
export function calcRoleAssignmentUpdateTasksLacksNamedTriggerOwner(tc: RoleAssignmentUpdateTasksRow): boolean | null {
  return toBoolPtr(erbOr(erbBool3(erbIsBlank(vStr(tc.policy_trigger_owner_role))), erbBool3(erbEq(vInt(tc.trigger_owner_cover_count), vI(0)))));
}

/** Computes the ElapsedMinutes calculated field.
 *  Minutes from the trigger to completion, or to the evaluation instant while incomplete.
 *  Formula: =IF({{CompletedAt}} = "", DATETIME_DIFF({{AsOfInstant}}, {{TriggerOccurredAt}}, "minutes"), DATETIME_DIFF({{CompletedAt}}, {{TriggerOccurredAt}}, "minutes")) */
export function calcRoleAssignmentUpdateTasksElapsedMinutes(tc: RoleAssignmentUpdateTasksRow): number | null {
  return toFloatPtr(erbIf(erbBool3(erbIsBlank(vStr(tc.completed_at))), () => erbDatetimeDiff(vStr(tc.as_of_instant), vStr(tc.trigger_occurred_at), vS("minutes")), () => erbDatetimeDiff(vStr(tc.completed_at), vStr(tc.trigger_occurred_at), vS("minutes"))));
}

/** Computes the ExceededUpdateSla calculated field.
 *  TRUE when no service level is defined, or the update took longer than it allows.
 *  Formula: =OR({{PolicySlaHours}} = 0, {{ElapsedMinutes}} > ({{PolicySlaHours}} * 60)) */
export function calcRoleAssignmentUpdateTasksExceededUpdateSla(tc: RoleAssignmentUpdateTasksRow): boolean | null {
  return toBoolPtr(erbOr(erbBool3(erbEq(vInt(tc.policy_sla_hours), vI(0))), erbBool3(erbCmp(vNum(tc.elapsed_minutes), ">", erbMul(vInt(tc.policy_sla_hours), vI(60))))));
}

/** Computes the ChangedRoleInsteadOfAssignment calculated field.
 *  TRUE when a change of who does the work was made by moving it to a different role, so the steps bound to the old role had to be re-pointed.
 *  Formula: =AND({{ReplacementAssignment}} <> "", {{ReplacementRole}} <> {{EndingRole}}) */
export function calcRoleAssignmentUpdateTasksChangedRoleInsteadOfAssignment(tc: RoleAssignmentUpdateTasksRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.replacement_assignment))), erbBool3(erbNe(vStr(tc.replacement_role), vStr(tc.ending_role)))));
}

/** Computes the MissedNextDependentRun calculated field.
 *  TRUE when a run that needs the role started after the trigger and before the assignment change was recorded.
 *  Formula: =AND({{DependentRunRoleStepCount}} > 0, {{DependentRunStartedAt}} > {{TriggerOccurredAt}}, OR({{CompletedAt}} = "", {{CompletedAt}} > {{DependentRunStartedAt}})) */
export function calcRoleAssignmentUpdateTasksMissedNextDependentRun(tc: RoleAssignmentUpdateTasksRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.dependent_run_role_step_count), ">", vI(0))), erbBool3(erbCmp(vStr(tc.dependent_run_started_at), ">", erbNullif(vStr(tc.trigger_occurred_at)))), erbBool3(erbOr(erbBool3(erbIsBlank(vStr(tc.completed_at))), erbBool3(erbCmp(erbNullif(vStr(tc.completed_at)), ">", vStr(tc.dependent_run_started_at)))))));
}

/** Computes the StaleAssignmentBrokeRouting calculated field.
 *  TRUE when the assignment was still stale at a run that needed it and that run's notice for the role reached the wrong person or nobody.
 *  Formula: =AND({{MissedNextDependentRun}}, {{FailedNoticeCount}} > 0) */
export function calcRoleAssignmentUpdateTasksStaleAssignmentBrokeRouting(tc: RoleAssignmentUpdateTasksRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.missed_next_dependent_run)), erbBool3(erbCmp(vInt(tc.failed_notice_count), ">", vI(0)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeRoleAssignmentUpdateTasks(tc: RoleAssignmentUpdateTasksRow): RoleAssignmentUpdateTasksRow {
  // Level 1
  calcGuard(tc, roleAssignmentUpdateTasksFieldTypes, "name", () => { tc.name = calcRoleAssignmentUpdateTasksName(tc); });
  calcGuard(tc, roleAssignmentUpdateTasksFieldTypes, "lacks_named_trigger_owner", () => { tc.lacks_named_trigger_owner = calcRoleAssignmentUpdateTasksLacksNamedTriggerOwner(tc); });
  calcGuard(tc, roleAssignmentUpdateTasksFieldTypes, "elapsed_minutes", () => { tc.elapsed_minutes = calcRoleAssignmentUpdateTasksElapsedMinutes(tc); });
  calcGuard(tc, roleAssignmentUpdateTasksFieldTypes, "changed_role_instead_of_assignment", () => { tc.changed_role_instead_of_assignment = calcRoleAssignmentUpdateTasksChangedRoleInsteadOfAssignment(tc); });
  calcGuard(tc, roleAssignmentUpdateTasksFieldTypes, "missed_next_dependent_run", () => { tc.missed_next_dependent_run = calcRoleAssignmentUpdateTasksMissedNextDependentRun(tc); });
  // Level 2
  calcGuard(tc, roleAssignmentUpdateTasksFieldTypes, "exceeded_update_sla", () => { tc.exceeded_update_sla = calcRoleAssignmentUpdateTasksExceededUpdateSla(tc); });
  calcGuard(tc, roleAssignmentUpdateTasksFieldTypes, "stale_assignment_broke_routing", () => { tc.stale_assignment_broke_routing = calcRoleAssignmentUpdateTasksStaleAssignmentBrokeRouting(tc); });
  return tc;
}

/** Reads RoleAssignmentUpdateTasks rows from a JSON array file. */
export function loadRoleAssignmentUpdateTasksRows(file: string): RoleAssignmentUpdateTasksRow[] {
  return loadRows(file, { fields: roleAssignmentUpdateTasksFieldTypes }) as unknown as RoleAssignmentUpdateTasksRow[];
}

// =============================================================================
// ASSIGNMENTROUTEDNOTICES TABLE
// Approval and verification notices a deployment pipeline sent for a run, where it read the recipient from, and who received it.
// =============================================================================

/** A row in the AssignmentRoutedNotices table. */
export interface AssignmentRoutedNoticesRow {
  /** Stored identifier. */
  assignment_routed_notice_id: string;
  /** Display name. */
  name: string | null;
  /** Run the notice belongs to. */
  procedure_execution: string | null;
  /** Step the notice asks someone to act on. */
  notice_step: string | null;
  /** ReleaseApproval or HealthVerification. */
  notice_kind: string | null;
  /** When sent. */
  sent_at: string | null;
  /** RoleAssignments (read from the model) or OpsSpreadsheet (a separately maintained list). */
  routing_source: string | null;
  /** Who received it; blank when nobody did. */
  routed_to_agent: string | null;
  /** Role assigned to the step. */
  notice_role: string | null;
  /** Recipient and role, as one key. */
  recipient_role_key: string | null;
  /** Assignments of the recipient to the role, at any time. */
  recipient_pair_assignment_count: number | null;
  /** Start of the recipient's assignment to the role. */
  recipient_valid_from: string | null;
  /** End of the recipient's assignment to the role. */
  recipient_latest_valid_to: string | null;
  /** Open-ended assignments of the recipient to the role. */
  recipient_open_ended_count: number | null;
  /** TRUE when the recipient's assignment to the step's role was valid at the moment the notice was sent. */
  recipient_held_role_when_sent: boolean | null;
  /** TRUE when a notice went to someone who did not hold the step's role when it was sent, or to nobody. */
  reached_wrong_person_or_nobody: boolean | null;
  /** TRUE when a notice was routed from a separately maintained list and reached someone the model's assignments did not name for the role. */
  routed_around_model: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const assignmentRoutedNoticesFieldTypes: Record<string, FieldType> = {
  assignment_routed_notice_id: "string",
  name: "*string",
  procedure_execution: "*string",
  notice_step: "*string",
  notice_kind: "*string",
  sent_at: "*string",
  routing_source: "*string",
  routed_to_agent: "*string",
  notice_role: "*string",
  recipient_role_key: "*string",
  recipient_pair_assignment_count: "*int",
  recipient_valid_from: "*string",
  recipient_latest_valid_to: "*string",
  recipient_open_ended_count: "*int",
  recipient_held_role_when_sent: "*bool",
  reached_wrong_person_or_nobody: "*bool",
  routed_around_model: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{ProcedureExecution}} & " / " & {{NoticeStep}} & " -> " & {{RoutedToAgent}} */
export function calcAssignmentRoutedNoticesName(tc: AssignmentRoutedNoticesRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.procedure_execution)), vS(" / "), erbText(vStr(tc.notice_step)), vS(" -> "), erbText(vStr(tc.routed_to_agent))));
}

/** Computes the RecipientRoleKey calculated field.
 *  Recipient and role, as one key.
 *  Formula: ={{RoutedToAgent}} & "|" & {{NoticeRole}} */
export function calcAssignmentRoutedNoticesRecipientRoleKey(tc: AssignmentRoutedNoticesRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.routed_to_agent)), vS("|"), erbText(vStr(tc.notice_role))));
}

/** Computes the RecipientHeldRoleWhenSent calculated field.
 *  TRUE when the recipient's assignment to the step's role was valid at the moment the notice was sent.
 *  Formula: =AND({{RoutedToAgent}} <> "", {{RecipientPairAssignmentCount}} > 0, {{RecipientValidFrom}} <= {{SentAt}}, OR({{RecipientOpenEndedCount}} > 0, {{RecipientLatestValidTo}} > {{SentAt}})) */
export function calcAssignmentRoutedNoticesRecipientHeldRoleWhenSent(tc: AssignmentRoutedNoticesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.routed_to_agent))), erbBool3(erbCmp(vInt(tc.recipient_pair_assignment_count), ">", vI(0))), erbBool3(erbCmp(vStr(tc.recipient_valid_from), "<=", erbNullif(vStr(tc.sent_at)))), erbBool3(erbOr(erbBool3(erbCmp(vInt(tc.recipient_open_ended_count), ">", vI(0))), erbBool3(erbCmp(vStr(tc.recipient_latest_valid_to), ">", erbNullif(vStr(tc.sent_at))))))));
}

/** Computes the ReachedWrongPersonOrNobody calculated field.
 *  TRUE when a notice went to someone who did not hold the step's role when it was sent, or to nobody.
 *  Formula: =NOT({{RecipientHeldRoleWhenSent}}) */
export function calcAssignmentRoutedNoticesReachedWrongPersonOrNobody(tc: AssignmentRoutedNoticesRow): boolean | null {
  return toBoolPtr(erbNot(erbBool3(vBool(tc.recipient_held_role_when_sent))));
}

/** Computes the RoutedAroundModel calculated field.
 *  TRUE when a notice was routed from a separately maintained list and reached someone the model's assignments did not name for the role.
 *  Formula: =AND({{RoutingSource}} <> "RoleAssignments", NOT({{RecipientHeldRoleWhenSent}})) */
export function calcAssignmentRoutedNoticesRoutedAroundModel(tc: AssignmentRoutedNoticesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbNe(erbNullif(vStr(tc.routing_source)), vS("RoleAssignments"))), erbBool3(erbNot(erbBool3(vBool(tc.recipient_held_role_when_sent))))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeAssignmentRoutedNotices(tc: AssignmentRoutedNoticesRow): AssignmentRoutedNoticesRow {
  // Level 1
  calcGuard(tc, assignmentRoutedNoticesFieldTypes, "name", () => { tc.name = calcAssignmentRoutedNoticesName(tc); });
  calcGuard(tc, assignmentRoutedNoticesFieldTypes, "recipient_role_key", () => { tc.recipient_role_key = calcAssignmentRoutedNoticesRecipientRoleKey(tc); });
  calcGuard(tc, assignmentRoutedNoticesFieldTypes, "recipient_held_role_when_sent", () => { tc.recipient_held_role_when_sent = calcAssignmentRoutedNoticesRecipientHeldRoleWhenSent(tc); });
  // Level 2
  calcGuard(tc, assignmentRoutedNoticesFieldTypes, "reached_wrong_person_or_nobody", () => { tc.reached_wrong_person_or_nobody = calcAssignmentRoutedNoticesReachedWrongPersonOrNobody(tc); });
  calcGuard(tc, assignmentRoutedNoticesFieldTypes, "routed_around_model", () => { tc.routed_around_model = calcAssignmentRoutedNoticesRoutedAroundModel(tc); });
  return tc;
}

/** Reads AssignmentRoutedNotices rows from a JSON array file. */
export function loadAssignmentRoutedNoticesRows(file: string): AssignmentRoutedNoticesRow[] {
  return loadRows(file, { fields: assignmentRoutedNoticesFieldTypes }) as unknown as AssignmentRoutedNoticesRow[];
}

// =============================================================================
// PRACTITIONEREXPERTISE TABLE
// Expertise a practitioner demonstrably holds, with the basis they could not put into words recorded as a property of that knowledge source.
// =============================================================================

/** A row in the PractitionerExpertise table. */
export interface PractitionerExpertiseRow {
  /** Stored identifier. */
  practitioner_expertise_id: string;
  /** Display name. */
  name: string | null;
  /** The practitioner who holds the expertise. */
  agent: string | null;
  /** The procedure the expertise is exercised in. */
  procedure: string | null;
  /** The step the expertise is exercised at. */
  step: string | null;
  /** The session in which the expertise was probed. */
  elicitation_session: string | null;
  /** Detection (sensing a condition in the moment) or DesignForesight (sensing a future cost). */
  expert_kind: string | null;
  /** What the practitioner senses or judges. */
  cue: string | null;
  /** The basis the practitioner could not articulate, in the elicitor's words; blank when the basis was stated. */
  unstated_basis: string | null;
  /** Observed occasions on which the practitioner's call proved right. */
  reliable_call_count: number | null;
  /** For design foresight: TRUE when later experience confirmed the call. */
  foresight_confirmed: boolean | null;
  /** TRUE when a practitioner reliably detects a condition whose basis they cannot state. */
  knows_more_than_can_say: boolean | null;
  /** TRUE when a design judgment later proved right although its holder could not say why. */
  is_unexplained_foresight: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const practitionerExpertiseFieldTypes: Record<string, FieldType> = {
  practitioner_expertise_id: "string",
  name: "*string",
  agent: "*string",
  procedure: "*string",
  step: "*string",
  elicitation_session: "*string",
  expert_kind: "*string",
  cue: "*string",
  unstated_basis: "*string",
  reliable_call_count: "*int",
  foresight_confirmed: "*bool",
  knows_more_than_can_say: "*bool",
  is_unexplained_foresight: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{Agent}} & ": " & {{Cue}} */
export function calcPractitionerExpertiseName(tc: PractitionerExpertiseRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.agent)), vS(": "), erbText(vStr(tc.cue))));
}

/** Computes the KnowsMoreThanCanSay calculated field.
 *  TRUE when a practitioner reliably detects a condition whose basis they cannot state.
 *  Formula: =AND({{ExpertKind}} = "Detection", {{UnstatedBasis}} <> "", {{ReliableCallCount}} >= 3) */
export function calcPractitionerExpertiseKnowsMoreThanCanSay(tc: PractitionerExpertiseRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.expert_kind)), vS("Detection"))), erbBool3(erbIsNotBlank(vStr(tc.unstated_basis))), erbBool3(erbCmp(erbNullif(vInt(tc.reliable_call_count)), ">=", vI(3)))));
}

/** Computes the IsUnexplainedForesight calculated field.
 *  TRUE when a design judgment later proved right although its holder could not say why.
 *  Formula: =AND({{ExpertKind}} = "DesignForesight", {{UnstatedBasis}} <> "", {{ForesightConfirmed}}) */
export function calcPractitionerExpertiseIsUnexplainedForesight(tc: PractitionerExpertiseRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.expert_kind)), vS("DesignForesight"))), erbBool3(erbIsNotBlank(vStr(tc.unstated_basis))), erbIsTrue(vBool(tc.foresight_confirmed))));
}

/** Computes every calculated field of the row in dependency order. */
export function computePractitionerExpertise(tc: PractitionerExpertiseRow): PractitionerExpertiseRow {
  // Level 1
  calcGuard(tc, practitionerExpertiseFieldTypes, "name", () => { tc.name = calcPractitionerExpertiseName(tc); });
  calcGuard(tc, practitionerExpertiseFieldTypes, "knows_more_than_can_say", () => { tc.knows_more_than_can_say = calcPractitionerExpertiseKnowsMoreThanCanSay(tc); });
  calcGuard(tc, practitionerExpertiseFieldTypes, "is_unexplained_foresight", () => { tc.is_unexplained_foresight = calcPractitionerExpertiseIsUnexplainedForesight(tc); });
  return tc;
}

/** Reads PractitionerExpertise rows from a JSON array file. */
export function loadPractitionerExpertiseRows(file: string): PractitionerExpertiseRow[] {
  return loadRows(file, { fields: practitionerExpertiseFieldTypes }) as unknown as PractitionerExpertiseRow[];
}

