/** A row in the CriticalIncidents table. */
export interface CriticalIncidentsRow {
  /** Stored identifier. */
  critical_incident_id: string;
  /** Display name. */
  name: string | null;
  /** The version the episode is elicited for. */
  procedure_version: string | null;
  /** The step where the episode turned. */
  step: string | null;
  /** The critical incident session that collected it. */
  elicitation_session: string | null;
  /** The practitioner who recounted the episode. */
  narrator: string | null;
  /** When the episode happened. */
  occurred_at: string | null;
  /** WentWell, WentBadly or Improvised. */
  outcome: string | null;
  /** The practitioner's account of the episode. */
  account: string | null;
  /** The judgment call the episode brought out that the written procedure hides; blank when none. */
  revealed_judgment: string | null;
  /** The knowledge fragment the revealed judgment was recorded as. */
  judgment_fragment: string | null;
  /** TRUE for an episode that went badly or had to be improvised. */
  is_adverse_or_improvised: boolean | null;
  /** TRUE when the episode revealed a judgment call. */
  has_surfaced_judgment: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const criticalIncidentsFieldTypes: Record<string, FieldType> = {
  critical_incident_id: "string",
  name: "*string",
  procedure_version: "*string",
  step: "*string",
  elicitation_session: "*string",
  narrator: "*string",
  occurred_at: "*string",
  outcome: "*string",
  account: "*string",
  revealed_judgment: "*string",
  judgment_fragment: "*string",
  is_adverse_or_improvised: "*bool",
  has_surfaced_judgment: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{Outcome}} & ": " & LEFT({{Account}}, 60) */
export function calcCriticalIncidentsName(tc: CriticalIncidentsRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.outcome)), vS(": "), erbText(erbLeft(vStr(tc.account), vI(60)))));
}

/** Computes the IsAdverseOrImprovised calculated field.
 *  TRUE for an episode that went badly or had to be improvised.
 *  Formula: =OR({{Outcome}} = "WentBadly", {{Outcome}} = "Improvised") */
export function calcCriticalIncidentsIsAdverseOrImprovised(tc: CriticalIncidentsRow): boolean | null {
  return toBoolPtr(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.outcome)), vS("WentBadly"))), erbBool3(erbEq(erbNullif(vStr(tc.outcome)), vS("Improvised")))));
}

/** Computes the HasSurfacedJudgment calculated field.
 *  TRUE when the episode revealed a judgment call.
 *  Formula: ={{RevealedJudgment}} <> "" */
export function calcCriticalIncidentsHasSurfacedJudgment(tc: CriticalIncidentsRow): boolean | null {
  return toBoolPtr(erbIsNotBlank(vStr(tc.revealed_judgment)));
}

/** Computes every calculated field of the row in dependency order. */
export function computeCriticalIncidents(tc: CriticalIncidentsRow): CriticalIncidentsRow {
  // Level 1
  calcGuard(tc, criticalIncidentsFieldTypes, "name", () => { tc.name = calcCriticalIncidentsName(tc); });
  calcGuard(tc, criticalIncidentsFieldTypes, "is_adverse_or_improvised", () => { tc.is_adverse_or_improvised = calcCriticalIncidentsIsAdverseOrImprovised(tc); });
  calcGuard(tc, criticalIncidentsFieldTypes, "has_surfaced_judgment", () => { tc.has_surfaced_judgment = calcCriticalIncidentsHasSurfacedJudgment(tc); });
  return tc;
}

/** Reads CriticalIncidents rows from a JSON array file. */
export function loadCriticalIncidentsRows(file: string): CriticalIncidentsRow[] {
  return loadRows(file, { fields: criticalIncidentsFieldTypes }) as unknown as CriticalIncidentsRow[];
}

// =============================================================================
// INTERVIEWPROBES TABLE
// Questions put in an elicitation interview, typed by what they probe: why a choice is made, what the practitioner would do if a condition changed, or what happens when the procedure falls short.
// =============================================================================

/** A row in the InterviewProbes table. */
export interface InterviewProbesRow {
  /** Stored identifier. */
  interview_probe_id: string;
  /** Display name. */
  name: string | null;
  /** The interview the probe was asked in. */
  elicitation_session: string | null;
  /** The step the probe is about. */
  step: string | null;
  /** Why, WhatIf or ProcedureFallsShort. */
  probe_kind: string | null;
  /** The question asked. */
  prompt: string | null;
  /** The practitioner's answer. */
  answer: string | null;
  /** The reason a practitioner gave for a choice. */
  why_answer: string | null;
  /** What the practitioner does when the standard procedure proves insufficient. */
  shortfall_answer: string | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const interviewProbesFieldTypes: Record<string, FieldType> = {
  interview_probe_id: "string",
  name: "*string",
  elicitation_session: "*string",
  step: "*string",
  probe_kind: "*string",
  prompt: "*string",
  answer: "*string",
  why_answer: "*string",
  shortfall_answer: "*string",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{ProbeKind}} & ": " & LEFT({{Prompt}}, 60) */
export function calcInterviewProbesName(tc: InterviewProbesRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.probe_kind)), vS(": "), erbText(erbLeft(vStr(tc.prompt), vI(60)))));
}

/** Computes the WhyAnswer calculated field.
 *  The reason a practitioner gave for a choice.
 *  Formula: =IF({{ProbeKind}} = "Why", {{Answer}}, "") */
export function calcInterviewProbesWhyAnswer(tc: InterviewProbesRow): string | null {
  return toStringPtr(erbIf(erbBool3(erbEq(erbNullif(vStr(tc.probe_kind)), vS("Why"))), () => vStr(tc.answer), () => vS("")));
}

/** Computes the ShortfallAnswer calculated field.
 *  What the practitioner does when the standard procedure proves insufficient.
 *  Formula: =IF({{ProbeKind}} = "ProcedureFallsShort", {{Answer}}, "") */
export function calcInterviewProbesShortfallAnswer(tc: InterviewProbesRow): string | null {
  return toStringPtr(erbIf(erbBool3(erbEq(erbNullif(vStr(tc.probe_kind)), vS("ProcedureFallsShort"))), () => vStr(tc.answer), () => vS("")));
}

/** Computes every calculated field of the row in dependency order. */
export function computeInterviewProbes(tc: InterviewProbesRow): InterviewProbesRow {
  // Level 1
  calcGuard(tc, interviewProbesFieldTypes, "name", () => { tc.name = calcInterviewProbesName(tc); });
  calcGuard(tc, interviewProbesFieldTypes, "why_answer", () => { tc.why_answer = calcInterviewProbesWhyAnswer(tc); });
  calcGuard(tc, interviewProbesFieldTypes, "shortfall_answer", () => { tc.shortfall_answer = calcInterviewProbesShortfallAnswer(tc); });
  return tc;
}

/** Reads InterviewProbes rows from a JSON array file. */
export function loadInterviewProbesRows(file: string): InterviewProbesRow[] {
  return loadRows(file, { fields: interviewProbesFieldTypes }) as unknown as InterviewProbesRow[];
}

// =============================================================================
// OBSERVEDACTIONS TABLE
// Actions an observer saw during shadowing or observation, typed as small choices, unofficial workarounds, steps omitted from the practitioner's own account, or documented steps, with the reason given when the observer asked.
// =============================================================================

/** A row in the ObservedActions table. */
export interface ObservedActionsRow {
  /** Stored identifier. */
  observed_action_id: string;
  /** Display name. */
  name: string | null;
  /** The observation session. */
  elicitation_session: string | null;
  /** The step the action belongs to. */
  step: string | null;
  /** The practitioner observed. */
  practitioner: string | null;
  /** What the observer saw. */
  action_description: string | null;
  /** SmallChoice, Workaround, OmittedObviousStep or DocumentedStep. */
  action_kind: string | null;
  /** TRUE when the practitioner's own interview account included the action. */
  mentioned_in_own_account: boolean | null;
  /** The reason the practitioner gave when the observer asked; blank when nobody asked. */
  stated_reason: string | null;
  /** The different condition the observer asked about. */
  counterfactual_condition: string | null;
  /** What the practitioner said they would do under that condition. */
  counterfactual_answer: string | null;
  /** The knowledge fragment the action was captured as. */
  captured_as_fragment: string | null;
  /** TRUE for a small choice made during actual practice. */
  is_small_choice: boolean | null;
  /** TRUE for an unofficial workaround. */
  is_unofficial_workaround: boolean | null;
  /** TRUE when observation saw an action the practitioner's own account left out. */
  is_omitted_from_own_account: boolean | null;
  /** TRUE when an action the interview missed was observed but never captured as knowledge. */
  is_missed_step_left_uncaptured: boolean | null;
  /** TRUE when a small choice or workaround was watched but no reason was asked for and recorded. */
  is_watched_not_questioned: boolean | null;
  /** TRUE when a reason is recorded against the observed action. */
  has_recorded_reason: boolean | null;
  /** TRUE when the practitioner said what they would do if a condition were different. */
  has_counterfactual_answer: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const observedActionsFieldTypes: Record<string, FieldType> = {
  observed_action_id: "string",
  name: "*string",
  elicitation_session: "*string",
  step: "*string",
  practitioner: "*string",
  action_description: "*string",
  action_kind: "*string",
  mentioned_in_own_account: "*bool",
  stated_reason: "*string",
  counterfactual_condition: "*string",
  counterfactual_answer: "*string",
  captured_as_fragment: "*string",
  is_small_choice: "*bool",
  is_unofficial_workaround: "*bool",
  is_omitted_from_own_account: "*bool",
  is_missed_step_left_uncaptured: "*bool",
  is_watched_not_questioned: "*bool",
  has_recorded_reason: "*bool",
  has_counterfactual_answer: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{ActionKind}} & ": " & LEFT({{ActionDescription}}, 60) */
export function calcObservedActionsName(tc: ObservedActionsRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.action_kind)), vS(": "), erbText(erbLeft(vStr(tc.action_description), vI(60)))));
}

/** Computes the IsSmallChoice calculated field.
 *  TRUE for a small choice made during actual practice.
 *  Formula: ={{ActionKind}} = "SmallChoice" */
export function calcObservedActionsIsSmallChoice(tc: ObservedActionsRow): boolean | null {
  return toBoolPtr(erbEq(erbNullif(vStr(tc.action_kind)), vS("SmallChoice")));
}

/** Computes the IsUnofficialWorkaround calculated field.
 *  TRUE for an unofficial workaround.
 *  Formula: ={{ActionKind}} = "Workaround" */
export function calcObservedActionsIsUnofficialWorkaround(tc: ObservedActionsRow): boolean | null {
  return toBoolPtr(erbEq(erbNullif(vStr(tc.action_kind)), vS("Workaround")));
}

/** Computes the IsOmittedFromOwnAccount calculated field.
 *  TRUE when observation saw an action the practitioner's own account left out.
 *  Formula: =AND({{ElicitationSession}} <> "", NOT({{MentionedInOwnAccount}})) */
export function calcObservedActionsIsOmittedFromOwnAccount(tc: ObservedActionsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.elicitation_session))), erbBool3(erbNot(erbIsTrue(vBool(tc.mentioned_in_own_account))))));
}

/** Computes the IsMissedStepLeftUncaptured calculated field.
 *  TRUE when an action the interview missed was observed but never captured as knowledge.
 *  Formula: =AND({{IsOmittedFromOwnAccount}}, {{CapturedAsFragment}} = "") */
export function calcObservedActionsIsMissedStepLeftUncaptured(tc: ObservedActionsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_omitted_from_own_account)), erbBool3(erbIsBlank(vStr(tc.captured_as_fragment)))));
}

/** Computes the IsWatchedNotQuestioned calculated field.
 *  TRUE when a small choice or workaround was watched but no reason was asked for and recorded.
 *  Formula: =AND(OR({{ActionKind}} = "SmallChoice", {{ActionKind}} = "Workaround"), {{StatedReason}} = "") */
export function calcObservedActionsIsWatchedNotQuestioned(tc: ObservedActionsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.action_kind)), vS("SmallChoice"))), erbBool3(erbEq(erbNullif(vStr(tc.action_kind)), vS("Workaround"))))), erbBool3(erbIsBlank(vStr(tc.stated_reason)))));
}

/** Computes the HasRecordedReason calculated field.
 *  TRUE when a reason is recorded against the observed action.
 *  Formula: ={{StatedReason}} <> "" */
export function calcObservedActionsHasRecordedReason(tc: ObservedActionsRow): boolean | null {
  return toBoolPtr(erbIsNotBlank(vStr(tc.stated_reason)));
}

/** Computes the HasCounterfactualAnswer calculated field.
 *  TRUE when the practitioner said what they would do if a condition were different.
 *  Formula: =AND({{CounterfactualCondition}} <> "", {{CounterfactualAnswer}} <> "") */
export function calcObservedActionsHasCounterfactualAnswer(tc: ObservedActionsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.counterfactual_condition))), erbBool3(erbIsNotBlank(vStr(tc.counterfactual_answer)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeObservedActions(tc: ObservedActionsRow): ObservedActionsRow {
  // Level 1
  calcGuard(tc, observedActionsFieldTypes, "name", () => { tc.name = calcObservedActionsName(tc); });
  calcGuard(tc, observedActionsFieldTypes, "is_small_choice", () => { tc.is_small_choice = calcObservedActionsIsSmallChoice(tc); });
  calcGuard(tc, observedActionsFieldTypes, "is_unofficial_workaround", () => { tc.is_unofficial_workaround = calcObservedActionsIsUnofficialWorkaround(tc); });
  calcGuard(tc, observedActionsFieldTypes, "is_omitted_from_own_account", () => { tc.is_omitted_from_own_account = calcObservedActionsIsOmittedFromOwnAccount(tc); });
  calcGuard(tc, observedActionsFieldTypes, "is_watched_not_questioned", () => { tc.is_watched_not_questioned = calcObservedActionsIsWatchedNotQuestioned(tc); });
  calcGuard(tc, observedActionsFieldTypes, "has_recorded_reason", () => { tc.has_recorded_reason = calcObservedActionsHasRecordedReason(tc); });
  calcGuard(tc, observedActionsFieldTypes, "has_counterfactual_answer", () => { tc.has_counterfactual_answer = calcObservedActionsHasCounterfactualAnswer(tc); });
  // Level 2
  calcGuard(tc, observedActionsFieldTypes, "is_missed_step_left_uncaptured", () => { tc.is_missed_step_left_uncaptured = calcObservedActionsIsMissedStepLeftUncaptured(tc); });
  return tc;
}

/** Reads ObservedActions rows from a JSON array file. */
export function loadObservedActionsRows(file: string): ObservedActionsRow[] {
  return loadRows(file, { fields: observedActionsFieldTypes }) as unknown as ObservedActionsRow[];
}

// =============================================================================
// ELICITATIONPARTICIPANTS TABLE
// Who took part in an elicitation session: their part in the session, whether they produce or consume the knowledge, their stake in the process, and whether people in their position are normally invited.
// =============================================================================

/** A row in the ElicitationParticipants table. */
export interface ElicitationParticipantsRow {
  /** Stored identifier. */
  elicitation_participant_id: string;
  /** Display name. */
  name: string | null;
  /** The session. */
  elicitation_session: string | null;
  /** The participant. */
  agent: string | null;
  /** Practitioner, SubjectMatterExpert or KnowledgeEngineer. */
  participation_role: string | null;
  /** Producer, Consumer or Both. */
  knowledge_flow: string | null;
  /** Initiates, Executes or DependsOnResults; blank for a facilitator with no stake. */
  process_stake: string | null;
  /** FALSE for a participant whose position is normally left out of such sessions. */
  is_usually_invited: boolean | null;
  /** TRUE for a practitioner who holds process knowledge. */
  is_practitioner: boolean | null;
  /** TRUE for a subject matter expert. */
  is_subject_matter_expert: boolean | null;
  /** TRUE for the knowledge engineer collecting the knowledge. */
  is_knowledge_engineer: boolean | null;
  /** TRUE for a participant who produces the knowledge. */
  is_knowledge_producer: boolean | null;
  /** TRUE for a participant who consumes the knowledge. */
  is_knowledge_consumer: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const elicitationParticipantsFieldTypes: Record<string, FieldType> = {
  elicitation_participant_id: "string",
  name: "*string",
  elicitation_session: "*string",
  agent: "*string",
  participation_role: "*string",
  knowledge_flow: "*string",
  process_stake: "*string",
  is_usually_invited: "*bool",
  is_practitioner: "*bool",
  is_subject_matter_expert: "*bool",
  is_knowledge_engineer: "*bool",
  is_knowledge_producer: "*bool",
  is_knowledge_consumer: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{Agent}} & " in " & {{ElicitationSession}} */
export function calcElicitationParticipantsName(tc: ElicitationParticipantsRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.agent)), vS(" in "), erbText(vStr(tc.elicitation_session))));
}

/** Computes the IsPractitioner calculated field.
 *  TRUE for a practitioner who holds process knowledge.
 *  Formula: ={{ParticipationRole}} = "Practitioner" */
export function calcElicitationParticipantsIsPractitioner(tc: ElicitationParticipantsRow): boolean | null {
  return toBoolPtr(erbEq(erbNullif(vStr(tc.participation_role)), vS("Practitioner")));
}

/** Computes the IsSubjectMatterExpert calculated field.
 *  TRUE for a subject matter expert.
 *  Formula: ={{ParticipationRole}} = "SubjectMatterExpert" */
export function calcElicitationParticipantsIsSubjectMatterExpert(tc: ElicitationParticipantsRow): boolean | null {
  return toBoolPtr(erbEq(erbNullif(vStr(tc.participation_role)), vS("SubjectMatterExpert")));
}

/** Computes the IsKnowledgeEngineer calculated field.
 *  TRUE for the knowledge engineer collecting the knowledge.
 *  Formula: ={{ParticipationRole}} = "KnowledgeEngineer" */
export function calcElicitationParticipantsIsKnowledgeEngineer(tc: ElicitationParticipantsRow): boolean | null {
  return toBoolPtr(erbEq(erbNullif(vStr(tc.participation_role)), vS("KnowledgeEngineer")));
}

/** Computes the IsKnowledgeProducer calculated field.
 *  TRUE for a participant who produces the knowledge.
 *  Formula: =OR({{KnowledgeFlow}} = "Producer", {{KnowledgeFlow}} = "Both") */
export function calcElicitationParticipantsIsKnowledgeProducer(tc: ElicitationParticipantsRow): boolean | null {
  return toBoolPtr(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.knowledge_flow)), vS("Producer"))), erbBool3(erbEq(erbNullif(vStr(tc.knowledge_flow)), vS("Both")))));
}

/** Computes the IsKnowledgeConsumer calculated field.
 *  TRUE for a participant who consumes the knowledge.
 *  Formula: =OR({{KnowledgeFlow}} = "Consumer", {{KnowledgeFlow}} = "Both") */
export function calcElicitationParticipantsIsKnowledgeConsumer(tc: ElicitationParticipantsRow): boolean | null {
  return toBoolPtr(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.knowledge_flow)), vS("Consumer"))), erbBool3(erbEq(erbNullif(vStr(tc.knowledge_flow)), vS("Both")))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeElicitationParticipants(tc: ElicitationParticipantsRow): ElicitationParticipantsRow {
  // Level 1
  calcGuard(tc, elicitationParticipantsFieldTypes, "name", () => { tc.name = calcElicitationParticipantsName(tc); });
  calcGuard(tc, elicitationParticipantsFieldTypes, "is_practitioner", () => { tc.is_practitioner = calcElicitationParticipantsIsPractitioner(tc); });
  calcGuard(tc, elicitationParticipantsFieldTypes, "is_subject_matter_expert", () => { tc.is_subject_matter_expert = calcElicitationParticipantsIsSubjectMatterExpert(tc); });
  calcGuard(tc, elicitationParticipantsFieldTypes, "is_knowledge_engineer", () => { tc.is_knowledge_engineer = calcElicitationParticipantsIsKnowledgeEngineer(tc); });
  calcGuard(tc, elicitationParticipantsFieldTypes, "is_knowledge_producer", () => { tc.is_knowledge_producer = calcElicitationParticipantsIsKnowledgeProducer(tc); });
  calcGuard(tc, elicitationParticipantsFieldTypes, "is_knowledge_consumer", () => { tc.is_knowledge_consumer = calcElicitationParticipantsIsKnowledgeConsumer(tc); });
  return tc;
}

/** Reads ElicitationParticipants rows from a JSON array file. */
