// =============================================================================
// WORKFLOWVIEWDIVERGENCES TABLE
// Differing views of how work flows, brought into the open in an elicitation session, and the reconciled account when one was reached.
// =============================================================================

/** A row in the WorkflowViewDivergences table. */
export interface WorkflowViewDivergencesRow {
  /** Stored identifier. */
  workflow_view_divergence_id: string;
  /** Display name. */
  name: string | null;
  /** The session where the views surfaced. */
  elicitation_session: string | null;
  /** The version the divergence is about. */
  procedure_version: string | null;
  /** The step the views differ on. */
  step: string | null;
  /** One account of how the work flows. */
  view_a: string | null;
  /** Who holds the first account. */
  holder_a: string | null;
  /** The differing account. */
  view_b: string | null;
  /** Who holds the second account. */
  holder_b: string | null;
  /** The account the participants settled on; blank while unsettled. */
  reconciled_statement: string | null;
  /** When it was settled. */
  reconciled_at: string | null;
  /** The fragment recording the settled account. */
  reconciled_into_fragment: string | null;
  /** TRUE when a settled account is recorded. */
  is_reconciled: boolean | null;
  /** TRUE when two differing views were brought into the open but never reconciled. */
  is_surfaced_but_unreconciled: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const workflowViewDivergencesFieldTypes: Record<string, FieldType> = {
  workflow_view_divergence_id: "string",
  name: "*string",
  elicitation_session: "*string",
  procedure_version: "*string",
  step: "*string",
  view_a: "*string",
  holder_a: "*string",
  view_b: "*string",
  holder_b: "*string",
  reconciled_statement: "*string",
  reconciled_at: "*string",
  reconciled_into_fragment: "*string",
  is_reconciled: "*bool",
  is_surfaced_but_unreconciled: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{Step}} & ": " & LEFT({{ViewA}}, 40) & " / " & LEFT({{ViewB}}, 40) */
export function calcWorkflowViewDivergencesName(tc: WorkflowViewDivergencesRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.step)), vS(": "), erbText(erbLeft(vStr(tc.view_a), vI(40))), vS(" / "), erbText(erbLeft(vStr(tc.view_b), vI(40)))));
}

/** Computes the IsReconciled calculated field.
 *  TRUE when a settled account is recorded.
 *  Formula: ={{ReconciledStatement}} <> "" */
export function calcWorkflowViewDivergencesIsReconciled(tc: WorkflowViewDivergencesRow): boolean | null {
  return toBoolPtr(erbIsNotBlank(vStr(tc.reconciled_statement)));
}

/** Computes the IsSurfacedButUnreconciled calculated field.
 *  TRUE when two differing views were brought into the open but never reconciled.
 *  Formula: =AND({{ViewA}} <> "", {{ViewB}} <> "", {{ReconciledStatement}} = "") */
export function calcWorkflowViewDivergencesIsSurfacedButUnreconciled(tc: WorkflowViewDivergencesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.view_a))), erbBool3(erbIsNotBlank(vStr(tc.view_b))), erbBool3(erbIsBlank(vStr(tc.reconciled_statement)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeWorkflowViewDivergences(tc: WorkflowViewDivergencesRow): WorkflowViewDivergencesRow {
  // Level 1
  calcGuard(tc, workflowViewDivergencesFieldTypes, "name", () => { tc.name = calcWorkflowViewDivergencesName(tc); });
  calcGuard(tc, workflowViewDivergencesFieldTypes, "is_reconciled", () => { tc.is_reconciled = calcWorkflowViewDivergencesIsReconciled(tc); });
  calcGuard(tc, workflowViewDivergencesFieldTypes, "is_surfaced_but_unreconciled", () => { tc.is_surfaced_but_unreconciled = calcWorkflowViewDivergencesIsSurfacedButUnreconciled(tc); });
  return tc;
}

