  procedure_version: "*string",
  step: "*string",
  snapshot: "*string",
  knowledge_form: "*string",
  carrier: "*string",
  holder_agent: "*string",
  statement: "*string",
  is_unsaid_in_sop: "*bool",
  holder_is_veteran: "*bool",
  handles_exception_or_discretion: "*bool",
  formalized_as: "*string",
  formalized_fragment_session: "*string",
  is_unformalized_process_knowledge: "*bool",
  is_procedural_knowledge: "*bool",
  is_judgment_outside_document: "*bool",
