// =============================================================================
// KNOWLEDGETESTOUTCOMES TABLE
// Outcomes a process knowledge test programme is expected to improve, measured before and after testing.
// =============================================================================

/** A row in the KnowledgeTestOutcomes table. */
export interface KnowledgeTestOutcomesRow {
  /** Stored identifier. */
  knowledge_test_outcome_id: string;
  /** Display name. */
  name: string | null;
  /** The procedure tested. */
  procedure: string | null;
  /** CompetencyGaps, ProcessQuality, Efficiency, JobSatisfaction or Consistency. */
  outcome_area: string | null;
  /** What was measured. */
  measure: string | null;
  /** Measured before the tests. */
  baseline_value: number | null;
  /** Measured after the tests. */
  after_test_value: number | null;
  /** TRUE when a higher value is an improvement. */
  higher_is_better: boolean | null;
  /** TRUE when the outcome moved in the better direction after testing. */
  is_improved: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const knowledgeTestOutcomesFieldTypes: Record<string, FieldType> = {
  knowledge_test_outcome_id: "string",
  name: "*string",
  procedure: "*string",
  outcome_area: "*string",
  measure: "*string",
  baseline_value: "*float64",
  after_test_value: "*float64",
  higher_is_better: "*bool",
  is_improved: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{Procedure}} & ": " & {{OutcomeArea}} */
export function calcKnowledgeTestOutcomesName(tc: KnowledgeTestOutcomesRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.procedure)), vS(": "), erbText(vStr(tc.outcome_area))));
}

/** Computes the IsImproved calculated field.
 *  TRUE when the outcome moved in the better direction after testing.
 *  Formula: =OR(AND({{HigherIsBetter}}, {{AfterTestValue}} > {{BaselineValue}}), AND(NOT({{HigherIsBetter}}), {{AfterTestValue}} < {{BaselineValue}})) */
export function calcKnowledgeTestOutcomesIsImproved(tc: KnowledgeTestOutcomesRow): boolean | null {
  return toBoolPtr(erbOr(erbBool3(erbAnd(erbIsTrue(vBool(tc.higher_is_better)), erbBool3(erbCmp(erbNullif(vNum(tc.after_test_value)), ">", erbNullif(vNum(tc.baseline_value)))))), erbBool3(erbAnd(erbBool3(erbNot(erbIsTrue(vBool(tc.higher_is_better)))), erbBool3(erbCmp(erbNullif(vNum(tc.after_test_value)), "<", erbNullif(vNum(tc.baseline_value))))))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeKnowledgeTestOutcomes(tc: KnowledgeTestOutcomesRow): KnowledgeTestOutcomesRow {
  // Level 1
  calcGuard(tc, knowledgeTestOutcomesFieldTypes, "name", () => { tc.name = calcKnowledgeTestOutcomesName(tc); });
  calcGuard(tc, knowledgeTestOutcomesFieldTypes, "is_improved", () => { tc.is_improved = calcKnowledgeTestOutcomesIsImproved(tc); });
  return tc;
}

/** Reads KnowledgeTestOutcomes rows from a JSON array file. */
export function loadKnowledgeTestOutcomesRows(file: string): KnowledgeTestOutcomesRow[] {
  return loadRows(file, { fields: knowledgeTestOutcomesFieldTypes }) as unknown as KnowledgeTestOutcomesRow[];
}

// =============================================================================
// KNOWHOWCARRIERS TABLE
// One piece of an organization's process know-how and what carries it: a person, a facility or a system, with the community it belongs to, the forms it is held in, and how long it took to build.
// =============================================================================

/** A row in the KnowHowCarriers table. */
export interface KnowHowCarriersRow {
  /** Stored identifier. */
  know_how_carrier_id: string;
  /** Display name. */
  name: string | null;
  /** What the know-how is about. */
  topic: string | null;
  /** The organization whose know-how this is. */
  organization: string | null;
  /** The procedure the know-how serves. */
  procedure: string | null;
  /** The community in which the know-how circulates. */
  community_of_practice: string | null;
  /** Person, Facility or System. */
  carrier_kind: string | null;
  /** The person who carries it, when the carrier is a person. */
  holder_agent: string | null;
  /** The plant that carries it in its layout and equipment, when the carrier is a facility. */
  holder_facility: string | null;
  /** WhatFails, Diagnosis, Improvisation or Refinement: the kind of practitioner know-how. */
  know_how_kind: string | null;
  /** TRUE when the know-how is written into a procedure. */
  is_in_written_procedure: boolean | null;
  /** TRUE when the know-how is carried as trained skill of seasoned workers. */
  is_trained_skill: boolean | null;
  /** Physical or Digital work. */
  work_medium: string | null;
  /** When the carrier began to hold the know-how. */
  held_since: string | null;
  /** Know-how about a related component or system this know-how depends on. */
  builds_on_know_how: string | null;
  /** TRUE when the know-how can be found in public references. */
  is_in_public_references: boolean | null;
  /** How the organization plans to replace the know-how if lost: PublicReference, AiGeneration, Apprenticeship, or blank. */
  replacement_plan: string | null;
  /** The instant the row is judged against. */
  evaluation_context: string | null;
  /** The modeled evaluation instant. */
  as_of_instant: string | null;
  /** Whether the holding person still holds a current role. */
  holder_is_still_engaged: boolean | null;
  /** When the holder began service. */
  holder_service_started_at: string | null;
  /** The holder's planned or actual departure. */
  holder_departure_at: string | null;
  /** Days from the evaluation instant to the holder's departure; negative once gone. */
  days_until_holder_departure: number | null;
  /** Days of service up to the evaluation instant. */
  days_served_to_as_of: number | null;
  /** Days of service up to departure. */
  days_served_to_departure: number | null;
  /** Years the holder practised: to departure when gone, else to the evaluation instant. */
  holder_tenure_years: number | null;
  /** TRUE when a person with ten or more years of practice carries the know-how. */
  is_veteran_held: boolean | null;
  /** TRUE when the holder leaves within 120 days of the evaluation instant. */
  is_holder_leaving_soon: boolean | null;
  /** Recorded transfers of this know-how to someone else. */
  transfer_count: number | null;
  /** Repository entries that capture this know-how. */
  repository_entry_count: number | null;
  /** Collection relationships with this holder on this procedure. */
  source_relationship_count: number | null;
  /** TRUE when the know-how is at once a written procedure and trained skill. */
  is_held_in_both_forms: boolean | null;
  /** TRUE when a person who still holds a role carries the know-how. */
  is_held_by_current_practitioner: boolean | null;
  /** TRUE when a serving veteran carries know-how never transferred or captured. */
  is_untransferred_veteran_know_how: boolean | null;
  /** TRUE when untransferred veteran know-how belongs to someone leaving within 120 days. */
  is_at_risk_of_imminent_loss: boolean | null;
  /** TRUE when the only carrier has left and the know-how was neither transferred nor captured. */
  is_held_only_by_departed: boolean | null;
  /** TRUE when the person who carried the know-how has left. */
  is_held_by_departed_holder: boolean | null;
  /** TRUE when a repository entry captures the know-how. */
  is_captured: boolean | null;
  /** TRUE when a serving holder's know-how has nothing captured for a successor. */
  must_be_relearned_if_holder_leaves: boolean | null;
  /** TRUE when uncaptured know-how has a serving holder no collection relationship has approached. */
  is_overlooked_living_holder: boolean | null;
  /** TRUE when veteran know-how has only been passed person to person with nothing captured, so the next newcomer still needs the veteran. */
  transfer_stops_without_veteran: boolean | null;
  /** The community of the know-how this builds on. */
  dependency_community: string | null;
  /** TRUE when the know-how depends on related know-how concentrated in the same community. */
  builds_on_same_community_know_how: boolean | null;
  /** Years of practice lost with a departed sole carrier; zero otherwise. */
  lost_accumulation_years: number | null;
  /** TRUE when the plan is to replace the know-how from public references or AI generation although it is not in public references. */
  is_delegated_to_unfit_source: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const knowHowCarriersFieldTypes: Record<string, FieldType> = {
  know_how_carrier_id: "string",
  name: "*string",
  topic: "*string",
  organization: "*string",
  procedure: "*string",
  community_of_practice: "*string",
  carrier_kind: "*string",
  holder_agent: "*string",
  holder_facility: "*string",
  know_how_kind: "*string",
  is_in_written_procedure: "*bool",
  is_trained_skill: "*bool",
  work_medium: "*string",
  held_since: "*string",
  builds_on_know_how: "*string",
  is_in_public_references: "*bool",
  replacement_plan: "*string",
  evaluation_context: "*string",
  as_of_instant: "*string",
  holder_is_still_engaged: "*bool",
  holder_service_started_at: "*string",
  holder_departure_at: "*string",
  days_until_holder_departure: "*int",
  days_served_to_as_of: "*int",
  days_served_to_departure: "*int",
  holder_tenure_years: "*float64",
  is_veteran_held: "*bool",
  is_holder_leaving_soon: "*bool",
  transfer_count: "*int",
  repository_entry_count: "*int",
  source_relationship_count: "*int",
  is_held_in_both_forms: "*bool",
  is_held_by_current_practitioner: "*bool",
  is_untransferred_veteran_know_how: "*bool",
  is_at_risk_of_imminent_loss: "*bool",
  is_held_only_by_departed: "*bool",
  is_held_by_departed_holder: "*bool",
  is_captured: "*bool",
  must_be_relearned_if_holder_leaves: "*bool",
  is_overlooked_living_holder: "*bool",
  transfer_stops_without_veteran: "*bool",
  dependency_community: "*string",
  builds_on_same_community_know_how: "*bool",
  lost_accumulation_years: "*float64",
  is_delegated_to_unfit_source: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{Topic}} & " / " & {{CarrierKind}} */
export function calcKnowHowCarriersName(tc: KnowHowCarriersRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.topic)), vS(" / "), erbText(vStr(tc.carrier_kind))));
}

/** Computes the DaysUntilHolderDeparture calculated field.
 *  Days from the evaluation instant to the holder's departure; negative once gone.
 *  Formula: =IF({{HolderDepartureAt}} = "", 99999, DATETIME_DIFF({{HolderDepartureAt}}, {{AsOfInstant}}, "days")) */
export function calcKnowHowCarriersDaysUntilHolderDeparture(tc: KnowHowCarriersRow): number | null {
  return toIntPtr(erbInteger(erbIf(erbBool3(erbIsBlank(vStr(tc.holder_departure_at))), () => vI(99999), () => erbDatetimeDiff(vStr(tc.holder_departure_at), vStr(tc.as_of_instant), vS("days")))));
}

/** Computes the DaysServedToAsOf calculated field.
 *  Days of service up to the evaluation instant.
 *  Formula: =IF({{HolderServiceStartedAt}} = "", 0, DATETIME_DIFF({{AsOfInstant}}, {{HolderServiceStartedAt}}, "days")) */
export function calcKnowHowCarriersDaysServedToAsOf(tc: KnowHowCarriersRow): number | null {
  return toIntPtr(erbInteger(erbIf(erbBool3(erbIsBlank(vStr(tc.holder_service_started_at))), () => vI(0), () => erbDatetimeDiff(vStr(tc.as_of_instant), vStr(tc.holder_service_started_at), vS("days")))));
}

/** Computes the DaysServedToDeparture calculated field.
 *  Days of service up to departure.
 *  Formula: =IF(OR({{HolderServiceStartedAt}} = "", {{HolderDepartureAt}} = ""), 0, DATETIME_DIFF({{HolderDepartureAt}}, {{HolderServiceStartedAt}}, "days")) */
export function calcKnowHowCarriersDaysServedToDeparture(tc: KnowHowCarriersRow): number | null {
  return toIntPtr(erbInteger(erbIf(erbBool3(erbOr(erbBool3(erbIsBlank(vStr(tc.holder_service_started_at))), erbBool3(erbIsBlank(vStr(tc.holder_departure_at))))), () => vI(0), () => erbDatetimeDiff(vStr(tc.holder_departure_at), vStr(tc.holder_service_started_at), vS("days")))));
}

/** Computes the HolderTenureYears calculated field.
 *  Years the holder practised: to departure when gone, else to the evaluation instant.
 *  Formula: =ROUND(IF(AND({{HolderDepartureAt}} <> "", {{DaysUntilHolderDeparture}} < 0), {{DaysServedToDeparture}}, {{DaysServedToAsOf}}) / 365, 1) */
export function calcKnowHowCarriersHolderTenureYears(tc: KnowHowCarriersRow): number | null {
  return toFloatPtr(erbRound(erbDiv(erbIf(erbBool3(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.holder_departure_at))), erbBool3(erbCmp(vInt(tc.days_until_holder_departure), "<", vI(0))))), () => vInt(tc.days_served_to_departure), () => vInt(tc.days_served_to_as_of)), vI(365)), vI(1)));
}

/** Computes the IsVeteranHeld calculated field.
 *  TRUE when a person with ten or more years of practice carries the know-how.
 *  Formula: =AND({{HolderAgent}} <> "", {{HolderTenureYears}} >= 10) */
export function calcKnowHowCarriersIsVeteranHeld(tc: KnowHowCarriersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.holder_agent))), erbBool3(erbCmp(vNum(tc.holder_tenure_years), ">=", vI(10)))));
}

/** Computes the IsHolderLeavingSoon calculated field.
 *  TRUE when the holder leaves within 120 days of the evaluation instant.
 *  Formula: =AND({{HolderDepartureAt}} <> "", {{DaysUntilHolderDeparture}} >= 0, {{DaysUntilHolderDeparture}} <= 120) */
export function calcKnowHowCarriersIsHolderLeavingSoon(tc: KnowHowCarriersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.holder_departure_at))), erbBool3(erbCmp(vInt(tc.days_until_holder_departure), ">=", vI(0))), erbBool3(erbCmp(vInt(tc.days_until_holder_departure), "<=", vI(120)))));
}

/** Computes the IsHeldInBothForms calculated field.
 *  TRUE when the know-how is at once a written procedure and trained skill.
 *  Formula: =AND({{IsInWrittenProcedure}}, {{IsTrainedSkill}}) */
export function calcKnowHowCarriersIsHeldInBothForms(tc: KnowHowCarriersRow): boolean | null {
  return toBoolPtr(erbAnd(erbIsTrue(vBool(tc.is_in_written_procedure)), erbIsTrue(vBool(tc.is_trained_skill))));
}

/** Computes the IsHeldByCurrentPractitioner calculated field.
 *  TRUE when a person who still holds a role carries the know-how.
 *  Formula: =AND({{HolderAgent}} <> "", {{HolderIsStillEngaged}} = TRUE) */
export function calcKnowHowCarriersIsHeldByCurrentPractitioner(tc: KnowHowCarriersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.holder_agent))), erbBool3(erbEq(vBool(tc.holder_is_still_engaged), vB(true)))));
}

/** Computes the IsUntransferredVeteranKnowHow calculated field.
 *  TRUE when a serving veteran carries know-how never transferred or captured.
 *  Formula: =AND({{IsVeteranHeld}}, {{HolderIsStillEngaged}} = TRUE, {{TransferCount}} = 0, {{RepositoryEntryCount}} = 0) */
export function calcKnowHowCarriersIsUntransferredVeteranKnowHow(tc: KnowHowCarriersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_veteran_held)), erbBool3(erbEq(vBool(tc.holder_is_still_engaged), vB(true))), erbBool3(erbEq(vInt(tc.transfer_count), vI(0))), erbBool3(erbEq(vInt(tc.repository_entry_count), vI(0)))));
}

/** Computes the IsAtRiskOfImminentLoss calculated field.
 *  TRUE when untransferred veteran know-how belongs to someone leaving within 120 days.
 *  Formula: =AND({{IsUntransferredVeteranKnowHow}}, {{IsHolderLeavingSoon}}) */
export function calcKnowHowCarriersIsAtRiskOfImminentLoss(tc: KnowHowCarriersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_untransferred_veteran_know_how)), erbBool3(vBool(tc.is_holder_leaving_soon))));
}

/** Computes the IsHeldOnlyByDeparted calculated field.
 *  TRUE when the only carrier has left and the know-how was neither transferred nor captured.
 *  Formula: =AND({{HolderAgent}} <> "", {{HolderIsStillEngaged}} = FALSE, {{TransferCount}} = 0, {{RepositoryEntryCount}} = 0) */
export function calcKnowHowCarriersIsHeldOnlyByDeparted(tc: KnowHowCarriersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.holder_agent))), erbBool3(erbEq(vBool(tc.holder_is_still_engaged), vB(false))), erbBool3(erbEq(vInt(tc.transfer_count), vI(0))), erbBool3(erbEq(vInt(tc.repository_entry_count), vI(0)))));
}

/** Computes the IsHeldByDepartedHolder calculated field.
 *  TRUE when the person who carried the know-how has left.
 *  Formula: =AND({{HolderAgent}} <> "", {{HolderIsStillEngaged}} = FALSE) */
export function calcKnowHowCarriersIsHeldByDepartedHolder(tc: KnowHowCarriersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.holder_agent))), erbBool3(erbEq(vBool(tc.holder_is_still_engaged), vB(false)))));
}

/** Computes the IsCaptured calculated field.
 *  TRUE when a repository entry captures the know-how.
 *  Formula: ={{RepositoryEntryCount}} > 0 */
export function calcKnowHowCarriersIsCaptured(tc: KnowHowCarriersRow): boolean | null {
  return toBoolPtr(erbCmp(vInt(tc.repository_entry_count), ">", vI(0)));
}

/** Computes the MustBeRelearnedIfHolderLeaves calculated field.
 *  TRUE when a serving holder's know-how has nothing captured for a successor.
 *  Formula: =AND({{HolderAgent}} <> "", {{HolderIsStillEngaged}} = TRUE, {{RepositoryEntryCount}} = 0) */
export function calcKnowHowCarriersMustBeRelearnedIfHolderLeaves(tc: KnowHowCarriersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.holder_agent))), erbBool3(erbEq(vBool(tc.holder_is_still_engaged), vB(true))), erbBool3(erbEq(vInt(tc.repository_entry_count), vI(0)))));
}

/** Computes the IsOverlookedLivingHolder calculated field.
 *  TRUE when uncaptured know-how has a serving holder no collection relationship has approached.
 *  Formula: =AND({{HolderAgent}} <> "", {{HolderIsStillEngaged}} = TRUE, {{RepositoryEntryCount}} = 0, {{SourceRelationshipCount}} = 0) */
export function calcKnowHowCarriersIsOverlookedLivingHolder(tc: KnowHowCarriersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.holder_agent))), erbBool3(erbEq(vBool(tc.holder_is_still_engaged), vB(true))), erbBool3(erbEq(vInt(tc.repository_entry_count), vI(0))), erbBool3(erbEq(vInt(tc.source_relationship_count), vI(0)))));
}

/** Computes the TransferStopsWithoutVeteran calculated field.
 *  TRUE when veteran know-how has only been passed person to person with nothing captured, so the next newcomer still needs the veteran.
 *  Formula: =AND({{IsVeteranHeld}}, {{HolderIsStillEngaged}} = TRUE, {{TransferCount}} > 0, {{RepositoryEntryCount}} = 0) */
export function calcKnowHowCarriersTransferStopsWithoutVeteran(tc: KnowHowCarriersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_veteran_held)), erbBool3(erbEq(vBool(tc.holder_is_still_engaged), vB(true))), erbBool3(erbCmp(vInt(tc.transfer_count), ">", vI(0))), erbBool3(erbEq(vInt(tc.repository_entry_count), vI(0)))));
}

/** Computes the BuildsOnSameCommunityKnowHow calculated field.
 *  TRUE when the know-how depends on related know-how concentrated in the same community.
 *  Formula: =AND({{BuildsOnKnowHow}} <> "", {{CommunityOfPractice}} <> "", {{DependencyCommunity}} = {{CommunityOfPractice}}) */
export function calcKnowHowCarriersBuildsOnSameCommunityKnowHow(tc: KnowHowCarriersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.builds_on_know_how))), erbBool3(erbIsNotBlank(vStr(tc.community_of_practice))), erbBool3(erbEq(vStr(tc.dependency_community), erbNullif(vStr(tc.community_of_practice))))));
}

/** Computes the LostAccumulationYears calculated field.
 *  Years of practice lost with a departed sole carrier; zero otherwise.
 *  Formula: =IF({{IsHeldOnlyByDeparted}}, {{HolderTenureYears}}, 0) */
export function calcKnowHowCarriersLostAccumulationYears(tc: KnowHowCarriersRow): number | null {
  return toFloatPtr(erbIf(erbBool3(vBool(tc.is_held_only_by_departed)), () => vNum(tc.holder_tenure_years), () => vI(0)));
}

/** Computes the IsDelegatedToUnfitSource calculated field.
 *  TRUE when the plan is to replace the know-how from public references or AI generation although it is not in public references.
 *  Formula: =AND(OR({{ReplacementPlan}} = "PublicReference", {{ReplacementPlan}} = "AiGeneration"), {{IsInPublicReferences}} = FALSE) */
export function calcKnowHowCarriersIsDelegatedToUnfitSource(tc: KnowHowCarriersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.replacement_plan)), vS("PublicReference"))), erbBool3(erbEq(erbNullif(vStr(tc.replacement_plan)), vS("AiGeneration"))))), erbBool3(erbEq(erbNullif(vBool(tc.is_in_public_references)), vB(false)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeKnowHowCarriers(tc: KnowHowCarriersRow): KnowHowCarriersRow {
  // Level 1
  calcGuard(tc, knowHowCarriersFieldTypes, "name", () => { tc.name = calcKnowHowCarriersName(tc); });
  calcGuard(tc, knowHowCarriersFieldTypes, "days_until_holder_departure", () => { tc.days_until_holder_departure = calcKnowHowCarriersDaysUntilHolderDeparture(tc); });
  calcGuard(tc, knowHowCarriersFieldTypes, "days_served_to_as_of", () => { tc.days_served_to_as_of = calcKnowHowCarriersDaysServedToAsOf(tc); });
  calcGuard(tc, knowHowCarriersFieldTypes, "days_served_to_departure", () => { tc.days_served_to_departure = calcKnowHowCarriersDaysServedToDeparture(tc); });
  calcGuard(tc, knowHowCarriersFieldTypes, "is_held_in_both_forms", () => { tc.is_held_in_both_forms = calcKnowHowCarriersIsHeldInBothForms(tc); });
  calcGuard(tc, knowHowCarriersFieldTypes, "is_held_by_current_practitioner", () => { tc.is_held_by_current_practitioner = calcKnowHowCarriersIsHeldByCurrentPractitioner(tc); });
  calcGuard(tc, knowHowCarriersFieldTypes, "is_held_only_by_departed", () => { tc.is_held_only_by_departed = calcKnowHowCarriersIsHeldOnlyByDeparted(tc); });
  calcGuard(tc, knowHowCarriersFieldTypes, "is_held_by_departed_holder", () => { tc.is_held_by_departed_holder = calcKnowHowCarriersIsHeldByDepartedHolder(tc); });
  calcGuard(tc, knowHowCarriersFieldTypes, "is_captured", () => { tc.is_captured = calcKnowHowCarriersIsCaptured(tc); });
  calcGuard(tc, knowHowCarriersFieldTypes, "must_be_relearned_if_holder_leaves", () => { tc.must_be_relearned_if_holder_leaves = calcKnowHowCarriersMustBeRelearnedIfHolderLeaves(tc); });
  calcGuard(tc, knowHowCarriersFieldTypes, "is_overlooked_living_holder", () => { tc.is_overlooked_living_holder = calcKnowHowCarriersIsOverlookedLivingHolder(tc); });
  calcGuard(tc, knowHowCarriersFieldTypes, "builds_on_same_community_know_how", () => { tc.builds_on_same_community_know_how = calcKnowHowCarriersBuildsOnSameCommunityKnowHow(tc); });
  calcGuard(tc, knowHowCarriersFieldTypes, "is_delegated_to_unfit_source", () => { tc.is_delegated_to_unfit_source = calcKnowHowCarriersIsDelegatedToUnfitSource(tc); });
  // Level 2
  calcGuard(tc, knowHowCarriersFieldTypes, "holder_tenure_years", () => { tc.holder_tenure_years = calcKnowHowCarriersHolderTenureYears(tc); });
  calcGuard(tc, knowHowCarriersFieldTypes, "is_holder_leaving_soon", () => { tc.is_holder_leaving_soon = calcKnowHowCarriersIsHolderLeavingSoon(tc); });
  // Level 3
  calcGuard(tc, knowHowCarriersFieldTypes, "is_veteran_held", () => { tc.is_veteran_held = calcKnowHowCarriersIsVeteranHeld(tc); });
  calcGuard(tc, knowHowCarriersFieldTypes, "lost_accumulation_years", () => { tc.lost_accumulation_years = calcKnowHowCarriersLostAccumulationYears(tc); });
  // Level 4
  calcGuard(tc, knowHowCarriersFieldTypes, "is_untransferred_veteran_know_how", () => { tc.is_untransferred_veteran_know_how = calcKnowHowCarriersIsUntransferredVeteranKnowHow(tc); });
  calcGuard(tc, knowHowCarriersFieldTypes, "transfer_stops_without_veteran", () => { tc.transfer_stops_without_veteran = calcKnowHowCarriersTransferStopsWithoutVeteran(tc); });
  // Level 5
  calcGuard(tc, knowHowCarriersFieldTypes, "is_at_risk_of_imminent_loss", () => { tc.is_at_risk_of_imminent_loss = calcKnowHowCarriersIsAtRiskOfImminentLoss(tc); });
  return tc;
}

/** Reads KnowHowCarriers rows from a JSON array file. */
export function loadKnowHowCarriersRows(file: string): KnowHowCarriersRow[] {
  return loadRows(file, { fields: knowHowCarriersFieldTypes }) as unknown as KnowHowCarriersRow[];
}

// =============================================================================
// KNOWLEDGETRANSFERS TABLE
// One occasion on which know-how passed from one person to another, and the channel it travelled through.
// =============================================================================

/** A row in the KnowledgeTransfers table. */
export interface KnowledgeTransfersRow {
  /** Stored identifier. */
  knowledge_transfer_id: string;
  /** Display name. */
  name: string | null;
  /** The know-how that passed. */
  know_how: string | null;
  /** Who passed it on. */
  from_agent: string | null;
  /** Who received it, when one person did. */
  recipient_agent: string | null;
  /** Document, TrainingProgram, Mentoring, PersonalRelationship, Collaboration, DesignProductionIteration, EmployerChange or AmbientExposure. */
  channel: string | null;
  /** The community the transfer took place in. */
  community_of_practice: string | null;
  /** When the transfer took place. */
  occurred_at: string | null;
  /** TRUE when the transfer was done on time the organization allotted for it. */
  on_allocated_time: boolean | null;
  /** The giver's organization. */
  from_organization: string | null;
  /** Current role assignments the recipient holds. */
  recipient_role_count: number | null;
  /** TRUE for the traditional channels: documents, training programs and mentoring. */
  is_traditional_channel: boolean | null;
  /** TRUE for relationships, collaboration, design-production iteration and people changing employers. */
  is_social_network_channel: boolean | null;
  /** TRUE when someone holding no role absorbed the know-how by living among the trade. */
  is_ambient_absorption_by_non_practitioner: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  /** What was handed over, in words: the topic of the know-how. */
  know_how_topic: string | null;
  _erb_errors?: Record<string, string>;
}

const knowledgeTransfersFieldTypes: Record<string, FieldType> = {
  knowledge_transfer_id: "string",
  name: "*string",
  know_how: "*string",
  from_agent: "*string",
  recipient_agent: "*string",
  channel: "*string",
  community_of_practice: "*string",
  occurred_at: "*string",
  on_allocated_time: "*bool",
  from_organization: "*string",
  recipient_role_count: "*int",
  is_traditional_channel: "*bool",
  is_social_network_channel: "*bool",
  is_ambient_absorption_by_non_practitioner: "*bool",
  semantic_type_iri: "*string",
  know_how_topic: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{KnowHow}} & " via " & {{Channel}} */
export function calcKnowledgeTransfersName(tc: KnowledgeTransfersRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.know_how)), vS(" via "), erbText(vStr(tc.channel))));
}

/** Computes the IsTraditionalChannel calculated field.
 *  TRUE for the traditional channels: documents, training programs and mentoring.
 *  Formula: =OR({{Channel}} = "Document", {{Channel}} = "TrainingProgram", {{Channel}} = "Mentoring") */
export function calcKnowledgeTransfersIsTraditionalChannel(tc: KnowledgeTransfersRow): boolean | null {
  return toBoolPtr(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.channel)), vS("Document"))), erbBool3(erbEq(erbNullif(vStr(tc.channel)), vS("TrainingProgram"))), erbBool3(erbEq(erbNullif(vStr(tc.channel)), vS("Mentoring")))));
}

/** Computes the IsSocialNetworkChannel calculated field.
 *  TRUE for relationships, collaboration, design-production iteration and people changing employers.
 *  Formula: =OR({{Channel}} = "PersonalRelationship", {{Channel}} = "Collaboration", {{Channel}} = "DesignProductionIteration", {{Channel}} = "EmployerChange") */
export function calcKnowledgeTransfersIsSocialNetworkChannel(tc: KnowledgeTransfersRow): boolean | null {
  return toBoolPtr(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.channel)), vS("PersonalRelationship"))), erbBool3(erbEq(erbNullif(vStr(tc.channel)), vS("Collaboration"))), erbBool3(erbEq(erbNullif(vStr(tc.channel)), vS("DesignProductionIteration"))), erbBool3(erbEq(erbNullif(vStr(tc.channel)), vS("EmployerChange")))));
}

/** Computes the IsAmbientAbsorptionByNonPractitioner calculated field.
 *  TRUE when someone holding no role absorbed the know-how by living among the trade.
 *  Formula: =AND({{RecipientAgent}} <> "", {{Channel}} = "AmbientExposure", {{RecipientRoleCount}} = 0) */
export function calcKnowledgeTransfersIsAmbientAbsorptionByNonPractitioner(tc: KnowledgeTransfersRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.recipient_agent))), erbBool3(erbEq(erbNullif(vStr(tc.channel)), vS("AmbientExposure"))), erbBool3(erbEq(vInt(tc.recipient_role_count), vI(0)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeKnowledgeTransfers(tc: KnowledgeTransfersRow): KnowledgeTransfersRow {
  // Level 1
  calcGuard(tc, knowledgeTransfersFieldTypes, "name", () => { tc.name = calcKnowledgeTransfersName(tc); });
  calcGuard(tc, knowledgeTransfersFieldTypes, "is_traditional_channel", () => { tc.is_traditional_channel = calcKnowledgeTransfersIsTraditionalChannel(tc); });
  calcGuard(tc, knowledgeTransfersFieldTypes, "is_social_network_channel", () => { tc.is_social_network_channel = calcKnowledgeTransfersIsSocialNetworkChannel(tc); });
  calcGuard(tc, knowledgeTransfersFieldTypes, "is_ambient_absorption_by_non_practitioner", () => { tc.is_ambient_absorption_by_non_practitioner = calcKnowledgeTransfersIsAmbientAbsorptionByNonPractitioner(tc); });
  return tc;
}

/** Reads KnowledgeTransfers rows from a JSON array file. */
export function loadKnowledgeTransfersRows(file: string): KnowledgeTransfersRow[] {
  return loadRows(file, { fields: knowledgeTransfersFieldTypes }) as unknown as KnowledgeTransfersRow[];
}

// =============================================================================
// KNOWLEDGEREPOSITORYENTRIES TABLE
// Captured procedural knowledge kept in a repository: who wrote it, whose know-how it records, for whom, whether it came back from executing the work, and whether it is kept current.
// =============================================================================

/** A row in the KnowledgeRepositoryEntries table. */
export interface KnowledgeRepositoryEntriesRow {
  /** Stored identifier. */
  knowledge_repository_entry_id: string;
  /** Display name. */
  name: string | null;
  /** Entry title. */
  title: string | null;
  /** The procedure the entry documents. */
  procedure: string | null;
  /** The know-how the entry captures, when it captures a recorded carrier's know-how. */
  know_how: string | null;
  /** Who wrote the entry. */
  author_agent: string | null;
  /** Whose expertise the entry records. */
  source_expert: string | null;
  /** TRUE when the entry names and credits the source expert. */
  credits_source_expert: boolean | null;
  /** LaterColleagues (written as part of the craft) or ComplianceAudit. */
  written_for_audience: string | null;
  /** TRUE when the writing was done on time the organization allotted for it. */
  authored_on_allocated_time: boolean | null;
  /** The execution whose experience the entry wrote back. */
  fed_from_execution: string | null;
  /** When the entry was created. */
  created_at: string | null;
  /** When the entry was last revised. */
  last_updated_at: string | null;
  /** How often the entry must be revised to stay current. */
  review_interval_days: number | null;
  /** The instant the row is judged against. */
  evaluation_context: string | null;
  /** The modeled evaluation instant. */
  as_of_instant: string | null;
  /** Whether the author still holds a role. */
  author_is_still_engaged: boolean | null;
  /** The author's kind. */
  author_agent_kind: string | null;
  /** The organization that owns the procedure. */
  owner_organization: string | null;
  /** Days since the last revision. */
  days_since_updated: number | null;
  /** TRUE when the entry has gone longer than its review interval without revision. */
  is_stale: boolean | null;
  /** TRUE when the entry wrote back what an execution taught. */
  is_execution_feedback: boolean | null;
  /** TRUE when an AI agent or pipeline wrote the entry. */
  is_machine_authored: boolean | null;
  /** TRUE when the entry is still current although its author has left. */
  outlives_author_tenure: boolean | null;
  /** TRUE when an entry records another person's expertise without crediting them. */
  is_uncredited_expert_know_how: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const knowledgeRepositoryEntriesFieldTypes: Record<string, FieldType> = {
  knowledge_repository_entry_id: "string",
  name: "*string",
  title: "*string",
  procedure: "*string",
  know_how: "*string",
  author_agent: "*string",
  source_expert: "*string",
  credits_source_expert: "*bool",
  written_for_audience: "*string",
  authored_on_allocated_time: "*bool",
  fed_from_execution: "*string",
  created_at: "*string",
  last_updated_at: "*string",
  review_interval_days: "*int",
  evaluation_context: "*string",
  as_of_instant: "*string",
  author_is_still_engaged: "*bool",
  author_agent_kind: "*string",
  owner_organization: "*string",
  days_since_updated: "*int",
  is_stale: "*bool",
  is_execution_feedback: "*bool",
  is_machine_authored: "*bool",
  outlives_author_tenure: "*bool",
  is_uncredited_expert_know_how: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{Title}} */
export function calcKnowledgeRepositoryEntriesName(tc: KnowledgeRepositoryEntriesRow): string | null {
  return toStringPtr(vStr(tc.title));
}

/** Computes the DaysSinceUpdated calculated field.
 *  Days since the last revision.
 *  Formula: =IF({{LastUpdatedAt}} = "", 0, DATETIME_DIFF({{AsOfInstant}}, {{LastUpdatedAt}}, "days")) */
export function calcKnowledgeRepositoryEntriesDaysSinceUpdated(tc: KnowledgeRepositoryEntriesRow): number | null {
  return toIntPtr(erbInteger(erbIf(erbBool3(erbIsBlank(vStr(tc.last_updated_at))), () => vI(0), () => erbDatetimeDiff(vStr(tc.as_of_instant), vStr(tc.last_updated_at), vS("days")))));
}

/** Computes the IsStale calculated field.
 *  TRUE when the entry has gone longer than its review interval without revision.
 *  Formula: =AND({{ReviewIntervalDays}} > 0, {{DaysSinceUpdated}} > {{ReviewIntervalDays}}) */
export function calcKnowledgeRepositoryEntriesIsStale(tc: KnowledgeRepositoryEntriesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbCmp(erbNullif(vInt(tc.review_interval_days)), ">", vI(0))), erbBool3(erbCmp(vInt(tc.days_since_updated), ">", erbNullif(vInt(tc.review_interval_days))))));
}

/** Computes the IsExecutionFeedback calculated field.
 *  TRUE when the entry wrote back what an execution taught.
 *  Formula: ={{FedFromExecution}} <> "" */
export function calcKnowledgeRepositoryEntriesIsExecutionFeedback(tc: KnowledgeRepositoryEntriesRow): boolean | null {
  return toBoolPtr(erbIsNotBlank(vStr(tc.fed_from_execution)));
}

/** Computes the IsMachineAuthored calculated field.
 *  TRUE when an AI agent or pipeline wrote the entry.
 *  Formula: =AND({{AuthorAgent}} <> "", OR({{AuthorAgentKind}} = "AIAgent", {{AuthorAgentKind}} = "AutomatedPipeline")) */
export function calcKnowledgeRepositoryEntriesIsMachineAuthored(tc: KnowledgeRepositoryEntriesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.author_agent))), erbBool3(erbOr(erbBool3(erbEq(vStr(tc.author_agent_kind), vS("AIAgent"))), erbBool3(erbEq(vStr(tc.author_agent_kind), vS("AutomatedPipeline")))))));
}

/** Computes the OutlivesAuthorTenure calculated field.
 *  TRUE when the entry is still current although its author has left.
 *  Formula: =AND({{AuthorAgent}} <> "", {{AuthorIsStillEngaged}} = FALSE, {{IsStale}} = FALSE) */
export function calcKnowledgeRepositoryEntriesOutlivesAuthorTenure(tc: KnowledgeRepositoryEntriesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.author_agent))), erbBool3(erbEq(vBool(tc.author_is_still_engaged), vB(false))), erbBool3(erbEq(vBool(tc.is_stale), vB(false)))));
}

/** Computes the IsUncreditedExpertKnowHow calculated field.
 *  TRUE when an entry records another person's expertise without crediting them.
 *  Formula: =AND({{SourceExpert}} <> "", {{SourceExpert}} <> {{AuthorAgent}}, {{CreditsSourceExpert}} = FALSE) */
export function calcKnowledgeRepositoryEntriesIsUncreditedExpertKnowHow(tc: KnowledgeRepositoryEntriesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.source_expert))), erbBool3(erbNe(erbNullif(vStr(tc.source_expert)), erbNullif(vStr(tc.author_agent)))), erbBool3(erbEq(erbNullif(vBool(tc.credits_source_expert)), vB(false)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeKnowledgeRepositoryEntries(tc: KnowledgeRepositoryEntriesRow): KnowledgeRepositoryEntriesRow {
  // Level 1
  calcGuard(tc, knowledgeRepositoryEntriesFieldTypes, "name", () => { tc.name = calcKnowledgeRepositoryEntriesName(tc); });
  calcGuard(tc, knowledgeRepositoryEntriesFieldTypes, "days_since_updated", () => { tc.days_since_updated = calcKnowledgeRepositoryEntriesDaysSinceUpdated(tc); });
  calcGuard(tc, knowledgeRepositoryEntriesFieldTypes, "is_execution_feedback", () => { tc.is_execution_feedback = calcKnowledgeRepositoryEntriesIsExecutionFeedback(tc); });
  calcGuard(tc, knowledgeRepositoryEntriesFieldTypes, "is_machine_authored", () => { tc.is_machine_authored = calcKnowledgeRepositoryEntriesIsMachineAuthored(tc); });
  calcGuard(tc, knowledgeRepositoryEntriesFieldTypes, "is_uncredited_expert_know_how", () => { tc.is_uncredited_expert_know_how = calcKnowledgeRepositoryEntriesIsUncreditedExpertKnowHow(tc); });
  // Level 2
  calcGuard(tc, knowledgeRepositoryEntriesFieldTypes, "is_stale", () => { tc.is_stale = calcKnowledgeRepositoryEntriesIsStale(tc); });
  // Level 3
  calcGuard(tc, knowledgeRepositoryEntriesFieldTypes, "outlives_author_tenure", () => { tc.outlives_author_tenure = calcKnowledgeRepositoryEntriesOutlivesAuthorTenure(tc); });
  return tc;
}

/** Reads KnowledgeRepositoryEntries rows from a JSON array file. */
export function loadKnowledgeRepositoryEntriesRows(file: string): KnowledgeRepositoryEntriesRow[] {
  return loadRows(file, { fields: knowledgeRepositoryEntriesFieldTypes }) as unknown as KnowledgeRepositoryEntriesRow[];
}

