// =============================================================================
// SOURCERELATIONSHIPS TABLE
// The standing relationship between a knowledge engineer and a knowledge source on one procedure: the power dynamic, what was negotiated, the state of trust, and what the source withholds and why.
// =============================================================================

/** A row in the SourceRelationships table. */
export interface SourceRelationshipsRow {
  /** Stored identifier. */
  source_relationship_id: string;
  /** Display name. */
  name: string | null;
  /** The knowledge engineer collecting. */
  knowledge_engineer: string | null;
  /** The knowledge source. */
  source_agent: string | null;
  /** The procedure the knowledge serves. */
  procedure: string | null;
  /** The source's standing relative to the engineer (SeniorVeteran, Peer, Manager). */
  source_standing: string | null;
  /** Balanced, SourceOutranksEngineer, SupervisorPresent or JobSecurityThreat. */
  power_dynamic: string | null;
  /** What was negotiated with the source about how their knowledge is collected and used. */
  negotiated_agreement: string | null;
  /** Low, Building or Established. */
  trust_level: string | null;
  /** What the engineer does to build trust with the source. */
  trust_building_practice: string | null;
  /** TRUE when the source was seen to hold information back. */
  withholding_observed: boolean | null;
  /** Why the source holds information back (status, job security). */
  withholding_motive: string | null;
  /** When the relationship began. */
  started_at: string | null;
  /** TRUE when a power imbalance shapes the relationship and nothing was negotiated. */
  is_unnegotiated_power_gap: boolean | null;
  /** TRUE when trust is not established and no trust-building practice is recorded. */
  is_extractive_relationship: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const sourceRelationshipsFieldTypes: Record<string, FieldType> = {
  source_relationship_id: "string",
  name: "*string",
  knowledge_engineer: "*string",
  source_agent: "*string",
  procedure: "*string",
  source_standing: "*string",
  power_dynamic: "*string",
  negotiated_agreement: "*string",
  trust_level: "*string",
  trust_building_practice: "*string",
  withholding_observed: "*bool",
  withholding_motive: "*string",
  started_at: "*string",
  is_unnegotiated_power_gap: "*bool",
  is_extractive_relationship: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{KnowledgeEngineer}} & " with " & {{SourceAgent}} */
export function calcSourceRelationshipsName(tc: SourceRelationshipsRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.knowledge_engineer)), vS(" with "), erbText(vStr(tc.source_agent))));
}

/** Computes the IsUnnegotiatedPowerGap calculated field.
 *  TRUE when a power imbalance shapes the relationship and nothing was negotiated.
 *  Formula: =AND({{PowerDynamic}} <> "", {{PowerDynamic}} <> "Balanced", {{NegotiatedAgreement}} = "") */
export function calcSourceRelationshipsIsUnnegotiatedPowerGap(tc: SourceRelationshipsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.power_dynamic))), erbBool3(erbNe(erbNullif(vStr(tc.power_dynamic)), vS("Balanced"))), erbBool3(erbIsBlank(vStr(tc.negotiated_agreement)))));
}

/** Computes the IsExtractiveRelationship calculated field.
 *  TRUE when trust is not established and no trust-building practice is recorded.
 *  Formula: =AND({{TrustLevel}} <> "", {{TrustLevel}} <> "Established", {{TrustBuildingPractice}} = "") */
export function calcSourceRelationshipsIsExtractiveRelationship(tc: SourceRelationshipsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.trust_level))), erbBool3(erbNe(erbNullif(vStr(tc.trust_level)), vS("Established"))), erbBool3(erbIsBlank(vStr(tc.trust_building_practice)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeSourceRelationships(tc: SourceRelationshipsRow): SourceRelationshipsRow {
  // Level 1
  calcGuard(tc, sourceRelationshipsFieldTypes, "name", () => { tc.name = calcSourceRelationshipsName(tc); });
  calcGuard(tc, sourceRelationshipsFieldTypes, "is_unnegotiated_power_gap", () => { tc.is_unnegotiated_power_gap = calcSourceRelationshipsIsUnnegotiatedPowerGap(tc); });
  calcGuard(tc, sourceRelationshipsFieldTypes, "is_extractive_relationship", () => { tc.is_extractive_relationship = calcSourceRelationshipsIsExtractiveRelationship(tc); });
  return tc;
}

/** Reads SourceRelationships rows from a JSON array file. */
export function loadSourceRelationshipsRows(file: string): SourceRelationshipsRow[] {
  return loadRows(file, { fields: sourceRelationshipsFieldTypes }) as unknown as SourceRelationshipsRow[];
}

// =============================================================================
// DEPARTMENTPROCESSACCOUNTS TABLE
// The account a stakeholder department gives of a process, the interest shaping it, any conflicting account from another department, and the practice used to resolve the disagreement.
