const departmentProcessAccountsFieldTypes: Record<string, FieldType> = {
  department_process_account_id: "string",
  name: "*string",
  procedure: "*string",
  department: "*string",
  stakeholder_agent: "*string",
  engaged_at: "*string",
  account_summary: "*string",
  shaping_interest: "*string",
  conflicts_with_account: "*string",
  resolution_practice: "*string",
  resolved_at: "*string",
  conflicting_department: "*string",
  is_awaiting_engagement: "*bool",
  is_conflicting_account: "*bool",
  is_unresolved_disagreement: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{Department}} & " on " & {{Procedure}} */
export function calcDepartmentProcessAccountsName(tc: DepartmentProcessAccountsRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.department)), vS(" on "), erbText(vStr(tc.procedure))));
}

/** Computes the IsAwaitingEngagement calculated field.
 *  TRUE when the stakeholder department has not been engaged.
 *  Formula: ={{EngagedAt}} = "" */
export function calcDepartmentProcessAccountsIsAwaitingEngagement(tc: DepartmentProcessAccountsRow): boolean | null {
  return toBoolPtr(erbIsBlank(vStr(tc.engaged_at)));
}

/** Computes the IsConflictingAccount calculated field.
 *  TRUE when another department gives a contradicting account of the same process.
 *  Formula: =AND({{ConflictsWithAccount}} <> "", {{ConflictingDepartment}} <> {{Department}}) */
export function calcDepartmentProcessAccountsIsConflictingAccount(tc: DepartmentProcessAccountsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.conflicts_with_account))), erbBool3(erbNe(vStr(tc.conflicting_department), erbNullif(vStr(tc.department))))));
}

/** Computes the IsUnresolvedDisagreement calculated field.
 *  TRUE when a cross-department conflict has no resolution practice.
 *  Formula: =AND({{IsConflictingAccount}}, {{ResolutionPractice}} = "") */
export function calcDepartmentProcessAccountsIsUnresolvedDisagreement(tc: DepartmentProcessAccountsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_conflicting_account)), erbBool3(erbIsBlank(vStr(tc.resolution_practice)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeDepartmentProcessAccounts(tc: DepartmentProcessAccountsRow): DepartmentProcessAccountsRow {
  // Level 1
  calcGuard(tc, departmentProcessAccountsFieldTypes, "name", () => { tc.name = calcDepartmentProcessAccountsName(tc); });
  calcGuard(tc, departmentProcessAccountsFieldTypes, "is_awaiting_engagement", () => { tc.is_awaiting_engagement = calcDepartmentProcessAccountsIsAwaitingEngagement(tc); });
  calcGuard(tc, departmentProcessAccountsFieldTypes, "is_conflicting_account", () => { tc.is_conflicting_account = calcDepartmentProcessAccountsIsConflictingAccount(tc); });
  // Level 2
  calcGuard(tc, departmentProcessAccountsFieldTypes, "is_unresolved_disagreement", () => { tc.is_unresolved_disagreement = calcDepartmentProcessAccountsIsUnresolvedDisagreement(tc); });
  return tc;
}

