// =============================================================================
// PROBLEMOCCURRENCES TABLE
// One occurrence of a recurring work problem: who solved it, whether the solution was recorded, and the earlier occurrence of the same problem.
// =============================================================================

/** A row in the ProblemOccurrences table. */
export interface ProblemOccurrencesRow {
  /** Stored identifier. */
  problem_occurrence_id: string;
  /** Display name. */
  name: string | null;
  /** The recognizable problem. */
  problem_signature: string | null;
  /** The procedure in which it occurred. */
  procedure: string | null;
  /** When it occurred. */
  occurred_at: string | null;
  /** Who solved it. */
  solved_by_agent: string | null;
  /** When it was solved; blank while open. */
  solved_at: string | null;
  /** The repository entry recording the solution. */
  solution_entry: string | null;
  /** The earlier occurrence of the same problem. */
  prior_occurrence: string | null;
  /** Whether the solver still holds a role. */
  solver_is_still_engaged: boolean | null;
  /** TRUE once the occurrence was solved. */
  is_solved: boolean | null;
  /** Whether the earlier occurrence was solved. */
  prior_was_solved: boolean | null;
  /** The earlier occurrence's recorded solution. */
  prior_solution_entry: string | null;
  /** Who solved the earlier occurrence. */
  prior_solver: string | null;
  /** Whether the earlier solver still holds a role. */
  prior_solver_is_still_engaged: boolean | null;
  /** TRUE when the problem was solved and the solution was not recorded. */
  is_solved_without_recorded_solution: boolean | null;
  /** TRUE when an earlier occurrence of the same problem was solved. */
  has_been_solved_before: boolean | null;
  /** TRUE when whoever solved the earlier occurrence still holds a role and can be consulted. */
  has_consultable_specialist: boolean | null;
  /** TRUE when a problem solved before came back and its earlier fix had not been recorded. */
  is_relearned_solved_problem: boolean | null;
  /** TRUE when an unrecorded fix came back after the person who made it left. */
  is_turnover_regression: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const problemOccurrencesFieldTypes: Record<string, FieldType> = {
  problem_occurrence_id: "string",
  name: "*string",
  problem_signature: "*string",
  procedure: "*string",
  occurred_at: "*string",
  solved_by_agent: "*string",
  solved_at: "*string",
  solution_entry: "*string",
  prior_occurrence: "*string",
  solver_is_still_engaged: "*bool",
  is_solved: "*bool",
  prior_was_solved: "*bool",
  prior_solution_entry: "*string",
  prior_solver: "*string",
  prior_solver_is_still_engaged: "*bool",
  is_solved_without_recorded_solution: "*bool",
  has_been_solved_before: "*bool",
  has_consultable_specialist: "*bool",
  is_relearned_solved_problem: "*bool",
  is_turnover_regression: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{ProblemSignature}} & " / " & {{ProblemOccurrenceId}} */
export function calcProblemOccurrencesName(tc: ProblemOccurrencesRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.problem_signature)), vS(" / "), erbText(vStrPlain(tc.problem_occurrence_id))));
}

/** Computes the IsSolved calculated field.
 *  TRUE once the occurrence was solved.
 *  Formula: ={{SolvedAt}} <> "" */
export function calcProblemOccurrencesIsSolved(tc: ProblemOccurrencesRow): boolean | null {
  return toBoolPtr(erbIsNotBlank(vStr(tc.solved_at)));
}

/** Computes the IsSolvedWithoutRecordedSolution calculated field.
 *  TRUE when the problem was solved and the solution was not recorded.
 *  Formula: =AND({{IsSolved}}, {{SolutionEntry}} = "") */
export function calcProblemOccurrencesIsSolvedWithoutRecordedSolution(tc: ProblemOccurrencesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_solved)), erbBool3(erbIsBlank(vStr(tc.solution_entry)))));
}

/** Computes the HasBeenSolvedBefore calculated field.
 *  TRUE when an earlier occurrence of the same problem was solved.
 *  Formula: =AND({{PriorOccurrence}} <> "", {{PriorWasSolved}} = TRUE) */
export function calcProblemOccurrencesHasBeenSolvedBefore(tc: ProblemOccurrencesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.prior_occurrence))), erbBool3(erbEq(vBool(tc.prior_was_solved), vB(true)))));
}

/** Computes the HasConsultableSpecialist calculated field.
 *  TRUE when whoever solved the earlier occurrence still holds a role and can be consulted.
 *  Formula: =AND({{HasBeenSolvedBefore}}, {{PriorSolver}} <> "", {{PriorSolverIsStillEngaged}} = TRUE) */
export function calcProblemOccurrencesHasConsultableSpecialist(tc: ProblemOccurrencesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.has_been_solved_before)), erbBool3(erbIsNotBlank(vStr(tc.prior_solver))), erbBool3(erbEq(vBool(tc.prior_solver_is_still_engaged), vB(true)))));
}

/** Computes the IsRelearnedSolvedProblem calculated field.
 *  TRUE when a problem solved before came back and its earlier fix had not been recorded.
 *  Formula: =AND({{HasBeenSolvedBefore}}, {{PriorSolutionEntry}} = "") */
export function calcProblemOccurrencesIsRelearnedSolvedProblem(tc: ProblemOccurrencesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.has_been_solved_before)), erbBool3(erbIsBlank(vStr(tc.prior_solution_entry)))));
}

/** Computes the IsTurnoverRegression calculated field.
 *  TRUE when an unrecorded fix came back after the person who made it left.
 *  Formula: =AND({{IsRelearnedSolvedProblem}}, {{PriorSolver}} <> "", {{PriorSolverIsStillEngaged}} = FALSE) */
export function calcProblemOccurrencesIsTurnoverRegression(tc: ProblemOccurrencesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_relearned_solved_problem)), erbBool3(erbIsNotBlank(vStr(tc.prior_solver))), erbBool3(erbEq(vBool(tc.prior_solver_is_still_engaged), vB(false)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeProblemOccurrences(tc: ProblemOccurrencesRow): ProblemOccurrencesRow {
  // Level 1
  calcGuard(tc, problemOccurrencesFieldTypes, "name", () => { tc.name = calcProblemOccurrencesName(tc); });
  calcGuard(tc, problemOccurrencesFieldTypes, "is_solved", () => { tc.is_solved = calcProblemOccurrencesIsSolved(tc); });
  calcGuard(tc, problemOccurrencesFieldTypes, "has_been_solved_before", () => { tc.has_been_solved_before = calcProblemOccurrencesHasBeenSolvedBefore(tc); });
  // Level 2
  calcGuard(tc, problemOccurrencesFieldTypes, "is_solved_without_recorded_solution", () => { tc.is_solved_without_recorded_solution = calcProblemOccurrencesIsSolvedWithoutRecordedSolution(tc); });
  calcGuard(tc, problemOccurrencesFieldTypes, "has_consultable_specialist", () => { tc.has_consultable_specialist = calcProblemOccurrencesHasConsultableSpecialist(tc); });
  calcGuard(tc, problemOccurrencesFieldTypes, "is_relearned_solved_problem", () => { tc.is_relearned_solved_problem = calcProblemOccurrencesIsRelearnedSolvedProblem(tc); });
  // Level 3
  calcGuard(tc, problemOccurrencesFieldTypes, "is_turnover_regression", () => { tc.is_turnover_regression = calcProblemOccurrencesIsTurnoverRegression(tc); });
  return tc;
}

/** Reads ProblemOccurrences rows from a JSON array file. */
export function loadProblemOccurrencesRows(file: string): ProblemOccurrencesRow[] {
  return loadRows(file, { fields: problemOccurrencesFieldTypes }) as unknown as ProblemOccurrencesRow[];
}

// =============================================================================
// ONBOARDINGRECORDS TABLE
// A new starter learning a procedure: when they started, when they reached proficiency, and whether they learned from captured, formalized knowledge.
// =============================================================================

/** A row in the OnboardingRecords table. */
export interface OnboardingRecordsRow {
  /** Stored identifier. */
  onboarding_record_id: string;
  /** Display name. */
  name: string | null;
  /** The new starter. */
  new_starter: string | null;
  /** The procedure being learned. */
  procedure: string | null;
  /** When onboarding started. */
  started_at: string | null;
  /** When the starter was signed off as proficient; blank while learning. */
  proficient_at: string | null;
  /** TRUE when the starter learned from formalized repository knowledge. */
  used_captured_knowledge: boolean | null;
  /** The instant the row is judged against. */
  evaluation_context: string | null;
  /** The modeled evaluation instant. */
  as_of_instant: string | null;
  /** TRUE once signed off. */
  is_proficient: boolean | null;
  /** Days from start to proficiency. */
  days_to_proficiency: number | null;
  /** Days from start to the evaluation instant. */
  days_since_start: number | null;
  /** TRUE when the starter began within 180 days of the evaluation instant. */
  is_recent_start: boolean | null;
  /** Repository entries for the procedure. */
  procedure_repository_entry_count: number | null;
  /** Know-how of the procedure held only by people who left. */
  procedure_departed_only_count: number | null;
  /** TRUE when a newcomer joins a procedure whose previous holders left and nothing was captured. */
  is_starting_from_nothing: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const onboardingRecordsFieldTypes: Record<string, FieldType> = {
  onboarding_record_id: "string",
  name: "*string",
  new_starter: "*string",
  procedure: "*string",
  started_at: "*string",
  proficient_at: "*string",
  used_captured_knowledge: "*bool",
  evaluation_context: "*string",
  as_of_instant: "*string",
  is_proficient: "*bool",
  days_to_proficiency: "*int",
  days_since_start: "*int",
  is_recent_start: "*bool",
  procedure_repository_entry_count: "*int",
  procedure_departed_only_count: "*int",
  is_starting_from_nothing: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{NewStarter}} & " on " & {{Procedure}} */
export function calcOnboardingRecordsName(tc: OnboardingRecordsRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.new_starter)), vS(" on "), erbText(vStr(tc.procedure))));
}

/** Computes the IsProficient calculated field.
 *  TRUE once signed off.
 *  Formula: ={{ProficientAt}} <> "" */
export function calcOnboardingRecordsIsProficient(tc: OnboardingRecordsRow): boolean | null {
  return toBoolPtr(erbIsNotBlank(vStr(tc.proficient_at)));
}

/** Computes the DaysToProficiency calculated field.
 *  Days from start to proficiency.
 *  Formula: =IF(OR({{StartedAt}} = "", {{ProficientAt}} = ""), 0, DATETIME_DIFF({{ProficientAt}}, {{StartedAt}}, "days")) */
export function calcOnboardingRecordsDaysToProficiency(tc: OnboardingRecordsRow): number | null {
  return toIntPtr(erbInteger(erbIf(erbBool3(erbOr(erbBool3(erbIsBlank(vStr(tc.started_at))), erbBool3(erbIsBlank(vStr(tc.proficient_at))))), () => vI(0), () => erbDatetimeDiff(vStr(tc.proficient_at), vStr(tc.started_at), vS("days")))));
}

/** Computes the DaysSinceStart calculated field.
 *  Days from start to the evaluation instant.
 *  Formula: =IF({{StartedAt}} = "", 99999, DATETIME_DIFF({{AsOfInstant}}, {{StartedAt}}, "days")) */
export function calcOnboardingRecordsDaysSinceStart(tc: OnboardingRecordsRow): number | null {
  return toIntPtr(erbInteger(erbIf(erbBool3(erbIsBlank(vStr(tc.started_at))), () => vI(99999), () => erbDatetimeDiff(vStr(tc.as_of_instant), vStr(tc.started_at), vS("days")))));
}

/** Computes the IsRecentStart calculated field.
 *  TRUE when the starter began within 180 days of the evaluation instant.
 *  Formula: =AND({{DaysSinceStart}} >= 0, {{DaysSinceStart}} <= 180) */
export function calcOnboardingRecordsIsRecentStart(tc: OnboardingRecordsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.days_since_start), ">=", vI(0))), erbBool3(erbCmp(vInt(tc.days_since_start), "<=", vI(180)))));
}

/** Computes the IsStartingFromNothing calculated field.
 *  TRUE when a newcomer joins a procedure whose previous holders left and nothing was captured.
 *  Formula: =AND({{ProcedureRepositoryEntryCount}} = 0, {{ProcedureDepartedOnlyCount}} > 0) */
export function calcOnboardingRecordsIsStartingFromNothing(tc: OnboardingRecordsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(vInt(tc.procedure_repository_entry_count), vI(0))), erbBool3(erbCmp(vInt(tc.procedure_departed_only_count), ">", vI(0)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeOnboardingRecords(tc: OnboardingRecordsRow): OnboardingRecordsRow {
  // Level 1
  calcGuard(tc, onboardingRecordsFieldTypes, "name", () => { tc.name = calcOnboardingRecordsName(tc); });
  calcGuard(tc, onboardingRecordsFieldTypes, "is_proficient", () => { tc.is_proficient = calcOnboardingRecordsIsProficient(tc); });
  calcGuard(tc, onboardingRecordsFieldTypes, "days_to_proficiency", () => { tc.days_to_proficiency = calcOnboardingRecordsDaysToProficiency(tc); });
  calcGuard(tc, onboardingRecordsFieldTypes, "days_since_start", () => { tc.days_since_start = calcOnboardingRecordsDaysSinceStart(tc); });
  calcGuard(tc, onboardingRecordsFieldTypes, "is_starting_from_nothing", () => { tc.is_starting_from_nothing = calcOnboardingRecordsIsStartingFromNothing(tc); });
  // Level 2
  calcGuard(tc, onboardingRecordsFieldTypes, "is_recent_start", () => { tc.is_recent_start = calcOnboardingRecordsIsRecentStart(tc); });
  return tc;
}

/** Reads OnboardingRecords rows from a JSON array file. */
export function loadOnboardingRecordsRows(file: string): OnboardingRecordsRow[] {
  return loadRows(file, { fields: onboardingRecordsFieldTypes }) as unknown as OnboardingRecordsRow[];
}

