// CAPABILITYDECLINES TABLE
// When an organization's training-and-retention cycle began to decline at one stage (facility investment, engineer training, upkeep of how-to-make knowledge) and the decline of the stage before it.
// =============================================================================

/** A row in the CapabilityDeclines table. */
export interface CapabilityDeclinesRow {
  /** Stored identifier. */
  capability_decline_id: string;
  /** Display name. */
  name: string | null;
  /** The organization. */
  organization: string | null;
  /** FacilityInvestment, EngineerTraining or KnowHowUpkeep. */
  stage: string | null;
  /** When the decline started. */
  decline_started_at: string | null;
  /** The decline of the stage that feeds this one. */
  preceding_stage_decline: string | null;
  /** What shows the decline. */
  evidence: string | null;
  /** The stage of the preceding decline. */
  preceding_stage: string | null;
  /** When the preceding decline started. */
  preceding_decline_started_at: string | null;
  /** TRUE when training declined after facility investment, or upkeep after training. */
  follows_preceding_stage_decline: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const capabilityDeclinesFieldTypes: Record<string, FieldType> = {
  capability_decline_id: "string",
  name: "*string",
  organization: "*string",
  stage: "*string",
  decline_started_at: "*string",
  preceding_stage_decline: "*string",
  evidence: "*string",
  preceding_stage: "*string",
  preceding_decline_started_at: "*string",
  follows_preceding_stage_decline: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{Organization}} & ": " & {{Stage}} */
export function calcCapabilityDeclinesName(tc: CapabilityDeclinesRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.organization)), vS(": "), erbText(vStr(tc.stage))));
}

/** Computes the FollowsPrecedingStageDecline calculated field.
 *  TRUE when training declined after facility investment, or upkeep after training.
 *  Formula: =AND({{PrecedingStageDecline}} <> "", {{PrecedingDeclineStartedAt}} < {{DeclineStartedAt}}, OR(AND({{Stage}} = "EngineerTraining", {{PrecedingStage}} = "FacilityInvestment"), AND({{Stage}} = "KnowHowUpkeep", {{PrecedingStage}} = "EngineerTraining"))) */
export function calcCapabilityDeclinesFollowsPrecedingStageDecline(tc: CapabilityDeclinesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.preceding_stage_decline))), erbBool3(erbCmp(vStr(tc.preceding_decline_started_at), "<", erbNullif(vStr(tc.decline_started_at)))), erbBool3(erbOr(erbBool3(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.stage)), vS("EngineerTraining"))), erbBool3(erbEq(vStr(tc.preceding_stage), vS("FacilityInvestment"))))), erbBool3(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.stage)), vS("KnowHowUpkeep"))), erbBool3(erbEq(vStr(tc.preceding_stage), vS("EngineerTraining")))))))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeCapabilityDeclines(tc: CapabilityDeclinesRow): CapabilityDeclinesRow {
  // Level 1
  calcGuard(tc, capabilityDeclinesFieldTypes, "name", () => { tc.name = calcCapabilityDeclinesName(tc); });
  calcGuard(tc, capabilityDeclinesFieldTypes, "follows_preceding_stage_decline", () => { tc.follows_preceding_stage_decline = calcCapabilityDeclinesFollowsPrecedingStageDecline(tc); });
  return tc;
}

/** Reads CapabilityDeclines rows from a JSON array file. */
export function loadCapabilityDeclinesRows(file: string): CapabilityDeclinesRow[] {
  return loadRows(file, { fields: capabilityDeclinesFieldTypes }) as unknown as CapabilityDeclinesRow[];
}

// =============================================================================
// KNOWLEDGETRACES TABLE
// One trace from a piece of organized knowledge (a process model, an activity definition or a constraint) to the collected material it rests on, with the role the material plays (origin, validation, extension, contradiction), how the knowledge was derived, and who confirmed it.
// =============================================================================

/** A row in the KnowledgeTraces table. */
export interface KnowledgeTracesRow {
  /** Stored identifier. */
  knowledge_trace_id: string;
  /** Display name. */
  name: string | null;
  /** ProcessModel, ActivityDefinition or Constraint. */
  target_kind: string | null;
  /** The process model the traced knowledge belongs to. */
  procedure_version: string | null;
  /** The activity definition traced, when the target is a step. */
  step: string | null;
  /** The constraint traced, when the target is a requirement. */
  requirement: string | null;
  /** The collected material the knowledge traces to. */
  source_material: string | null;
  /** Origin (knowledge was taken from it), Validates, Extends, or Contradicts. */
  trace_role: string | null;
  /** What the source is cited for: Sequence, StepDescription, Workaround, ActualExecution or Constraint. */
  traced_aspect: string | null;
  /** Paraphrase of what the source says about the target. */
  source_statement: string | null;
  /** How the knowledge was produced from the source. */
  derivation_route: string | null;
  /** Who (or what) derived the knowledge from the source. */
  derived_by_agent: string | null;
  /** Who confirmed the derived knowledge. */
  validated_by_agent: string | null;
  /** When it was confirmed. */
  validated_at: string | null;
  /** Duration the source states for the traced step, when it states one. */
  source_stated_duration_minutes: number | null;
  /** For a contradiction: the document whose prescription practice departs from. */
  contradicted_document: string | null;
  /** Kind of the source material. */
  source_material_kind: string | null;
  /** When the knowledge was taken: the material's collection instant. */
  source_collected_at: string | null;
  /** Last revision of the document the material was excerpted from. */
  source_revised_at: string | null;
  /** TRUE when the source is an excerpt of an existing document. */
  source_is_document: boolean | null;
  /** TRUE when the source was captured from people (transcript or field notes). */
  source_is_people_capture: boolean | null;
  /** TRUE when the source records work as performed (field notes or an event trace). */
  source_is_practice_evidence: boolean | null;
  /** TRUE when the source document was revised after the knowledge was taken from it. */
  is_source_changed_since_taken: boolean | null;
  /** Duration the modeled step carries. */
  modeled_duration_minutes: number | null;
  /** TRUE when the modeled step's duration differs from the duration its source states. */
  is_unfaithful_to_source: boolean | null;
  /** Kind of the deriving agent. */
  derived_by_agent_kind: string | null;
  /** TRUE when a software or AI agent derived the knowledge from its source. */
  is_machine_derived: boolean | null;
  /** TRUE when the agent who derived the knowledge is the one who confirmed it. */
  is_self_validated: boolean | null;
  /** TRUE when the origin, the derivation route or the confirmation is missing. */
  has_incomplete_provenance: boolean | null;
  /** Origin, route and confirmation in one line. */
  provenance_statement: string | null;
  /** TRUE when a workaround is cited to something other than observation notes, or actual execution to something other than an event trace. */
  is_aspect_unsupported_by_source_kind: boolean | null;
  /** TRUE when the knowledge was first taken from a document. */
  is_document_origin: boolean | null;
  /** Validations of the traced step captured from people. */
  step_elicited_validation_count: number | null;
  /** Extensions of the traced step captured from people. */
  step_elicited_extension_count: number | null;
  /** TRUE when a step taken from a document has never been confirmed by capture from people. */
  is_document_start_never_validated: boolean | null;
  /** TRUE when a step taken from a document has never been extended by capture from people. */
  is_document_start_never_extended: boolean | null;
  /** Last revision of the contradicted document. */
  contradicted_document_revised_at: string | null;
  /** TRUE when practice evidence collected after the document's last revision contradicts it. */
  is_document_trailing_practice: boolean | null;
  /** For a contradiction: what the document prescribes against what practice evidence shows. */
  prescribed_versus_enacted: string | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const knowledgeTracesFieldTypes: Record<string, FieldType> = {
  knowledge_trace_id: "string",
  name: "*string",
  target_kind: "*string",
  procedure_version: "*string",
  step: "*string",
  requirement: "*string",
  source_material: "*string",
  trace_role: "*string",
  traced_aspect: "*string",
  source_statement: "*string",
  derivation_route: "*string",
  derived_by_agent: "*string",
  validated_by_agent: "*string",
  validated_at: "*string",
  source_stated_duration_minutes: "*int",
  contradicted_document: "*string",
  source_material_kind: "*string",
  source_collected_at: "*string",
  source_revised_at: "*string",
  source_is_document: "*bool",
  source_is_people_capture: "*bool",
  source_is_practice_evidence: "*bool",
  is_source_changed_since_taken: "*bool",
  modeled_duration_minutes: "*int",
  is_unfaithful_to_source: "*bool",
  derived_by_agent_kind: "*string",
  is_machine_derived: "*bool",
  is_self_validated: "*bool",
  has_incomplete_provenance: "*bool",
  provenance_statement: "*string",
  is_aspect_unsupported_by_source_kind: "*bool",
  is_document_origin: "*bool",
  step_elicited_validation_count: "*int",
  step_elicited_extension_count: "*int",
  is_document_start_never_validated: "*bool",
  is_document_start_never_extended: "*bool",
  contradicted_document_revised_at: "*string",
  is_document_trailing_practice: "*bool",
  prescribed_versus_enacted: "*string",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{TargetKind}} & " <- " & {{SourceMaterial}} & " (" & {{TraceRole}} & ")" */
export function calcKnowledgeTracesName(tc: KnowledgeTracesRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.target_kind)), vS(" <- "), erbText(vStr(tc.source_material)), vS(" ("), erbText(vStr(tc.trace_role)), vS(")")));
}

/** Computes the IsSourceChangedSinceTaken calculated field.
 *  TRUE when the source document was revised after the knowledge was taken from it.
 *  Formula: =AND({{SourceRevisedAt}} <> "", {{SourceRevisedAt}} > {{SourceCollectedAt}}) */
export function calcKnowledgeTracesIsSourceChangedSinceTaken(tc: KnowledgeTracesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.source_revised_at))), erbBool3(erbCmp(vStr(tc.source_revised_at), ">", vStr(tc.source_collected_at)))));
}

/** Computes the IsUnfaithfulToSource calculated field.
 *  TRUE when the modeled step's duration differs from the duration its source states.
 *  Formula: =AND({{Step}} <> "", {{SourceStatedDurationMinutes}} > 0, {{ModeledDurationMinutes}} <> {{SourceStatedDurationMinutes}}) */
export function calcKnowledgeTracesIsUnfaithfulToSource(tc: KnowledgeTracesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.step))), erbBool3(erbCmp(erbNullif(vInt(tc.source_stated_duration_minutes)), ">", vI(0))), erbBool3(erbNe(vInt(tc.modeled_duration_minutes), erbNullif(vInt(tc.source_stated_duration_minutes))))));
}

/** Computes the IsMachineDerived calculated field.
 *  TRUE when a software or AI agent derived the knowledge from its source.
 *  Formula: =AND({{DerivedByAgent}} <> "", {{DerivedByAgentKind}} <> "Human") */
export function calcKnowledgeTracesIsMachineDerived(tc: KnowledgeTracesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.derived_by_agent))), erbBool3(erbNe(vStr(tc.derived_by_agent_kind), vS("Human")))));
}

/** Computes the IsSelfValidated calculated field.
 *  TRUE when the agent who derived the knowledge is the one who confirmed it.
 *  Formula: =AND({{ValidatedByAgent}} <> "", {{ValidatedByAgent}} = {{DerivedByAgent}}) */
export function calcKnowledgeTracesIsSelfValidated(tc: KnowledgeTracesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.validated_by_agent))), erbBool3(erbEq(erbNullif(vStr(tc.validated_by_agent)), erbNullif(vStr(tc.derived_by_agent))))));
}

/** Computes the HasIncompleteProvenance calculated field.
 *  TRUE when the origin, the derivation route or the confirmation is missing.
 *  Formula: =OR({{SourceMaterial}} = "", {{DerivationRoute}} = "", {{ValidatedByAgent}} = "") */
export function calcKnowledgeTracesHasIncompleteProvenance(tc: KnowledgeTracesRow): boolean | null {
  return toBoolPtr(erbOr(erbBool3(erbIsBlank(vStr(tc.source_material))), erbBool3(erbIsBlank(vStr(tc.derivation_route))), erbBool3(erbIsBlank(vStr(tc.validated_by_agent)))));
}

/** Computes the ProvenanceStatement calculated field.
 *  Origin, route and confirmation in one line.
 *  Formula: ="From " & {{SourceMaterial}} & "; route: " & {{DerivationRoute}} & "; derived by " & {{DerivedByAgent}} & "; confirmed by " & {{ValidatedByAgent}} */
export function calcKnowledgeTracesProvenanceStatement(tc: KnowledgeTracesRow): string | null {
  return toStringPtr(erbConcat(vS("From "), erbText(vStr(tc.source_material)), vS("; route: "), erbText(vStr(tc.derivation_route)), vS("; derived by "), erbText(vStr(tc.derived_by_agent)), vS("; confirmed by "), erbText(vStr(tc.validated_by_agent))));
}

/** Computes the IsAspectUnsupportedBySourceKind calculated field.
 *  TRUE when a workaround is cited to something other than observation notes, or actual execution to something other than an event trace.
 *  Formula: =OR(AND({{TracedAspect}} = "Workaround", {{SourceMaterialKind}} <> "FieldNotes"), AND({{TracedAspect}} = "ActualExecution", {{SourceMaterialKind}} <> "MinedEventTrace")) */
export function calcKnowledgeTracesIsAspectUnsupportedBySourceKind(tc: KnowledgeTracesRow): boolean | null {
  return toBoolPtr(erbOr(erbBool3(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.traced_aspect)), vS("Workaround"))), erbBool3(erbNe(vStr(tc.source_material_kind), vS("FieldNotes"))))), erbBool3(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.traced_aspect)), vS("ActualExecution"))), erbBool3(erbNe(vStr(tc.source_material_kind), vS("MinedEventTrace")))))));
}

/** Computes the IsDocumentOrigin calculated field.
 *  TRUE when the knowledge was first taken from a document.
 *  Formula: =AND({{TraceRole}} = "Origin", {{SourceIsDocument}}) */
export function calcKnowledgeTracesIsDocumentOrigin(tc: KnowledgeTracesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.trace_role)), vS("Origin"))), erbBool3(vBool(tc.source_is_document))));
}

/** Computes the IsDocumentStartNeverValidated calculated field.
 *  TRUE when a step taken from a document has never been confirmed by capture from people.
 *  Formula: =AND({{IsDocumentOrigin}}, {{Step}} <> "", {{StepElicitedValidationCount}} = 0) */
export function calcKnowledgeTracesIsDocumentStartNeverValidated(tc: KnowledgeTracesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_document_origin)), erbBool3(erbIsNotBlank(vStr(tc.step))), erbBool3(erbEq(vInt(tc.step_elicited_validation_count), vI(0)))));
}

/** Computes the IsDocumentStartNeverExtended calculated field.
 *  TRUE when a step taken from a document has never been extended by capture from people.
 *  Formula: =AND({{IsDocumentOrigin}}, {{Step}} <> "", {{StepElicitedExtensionCount}} = 0) */
export function calcKnowledgeTracesIsDocumentStartNeverExtended(tc: KnowledgeTracesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_document_origin)), erbBool3(erbIsNotBlank(vStr(tc.step))), erbBool3(erbEq(vInt(tc.step_elicited_extension_count), vI(0)))));
}

/** Computes the IsDocumentTrailingPractice calculated field.
 *  TRUE when practice evidence collected after the document's last revision contradicts it.
 *  Formula: =AND({{TraceRole}} = "Contradicts", {{ContradictedDocument}} <> "", {{SourceIsPracticeEvidence}}, {{SourceCollectedAt}} > {{ContradictedDocumentRevisedAt}}) */
export function calcKnowledgeTracesIsDocumentTrailingPractice(tc: KnowledgeTracesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.trace_role)), vS("Contradicts"))), erbBool3(erbIsNotBlank(vStr(tc.contradicted_document))), erbBool3(vBool(tc.source_is_practice_evidence)), erbBool3(erbCmp(vStr(tc.source_collected_at), ">", vStr(tc.contradicted_document_revised_at)))));
}

/** Computes the PrescribedVersusEnacted calculated field.
 *  For a contradiction: what the document prescribes against what practice evidence shows.
 *  Formula: =IF({{ContradictedDocument}} = "", "", "Prescribed in " & {{ContradictedDocument}} & "; enacted per " & {{SourceMaterial}} & ": " & {{SourceStatement}}) */
export function calcKnowledgeTracesPrescribedVersusEnacted(tc: KnowledgeTracesRow): string | null {
  return toStringPtr(erbIf(erbBool3(erbIsBlank(vStr(tc.contradicted_document))), () => vS(""), () => erbConcat(vS("Prescribed in "), erbText(vStr(tc.contradicted_document)), vS("; enacted per "), erbText(vStr(tc.source_material)), vS(": "), erbText(vStr(tc.source_statement)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeKnowledgeTraces(tc: KnowledgeTracesRow): KnowledgeTracesRow {
  // Level 1
  calcGuard(tc, knowledgeTracesFieldTypes, "name", () => { tc.name = calcKnowledgeTracesName(tc); });
  calcGuard(tc, knowledgeTracesFieldTypes, "is_source_changed_since_taken", () => { tc.is_source_changed_since_taken = calcKnowledgeTracesIsSourceChangedSinceTaken(tc); });
  calcGuard(tc, knowledgeTracesFieldTypes, "is_unfaithful_to_source", () => { tc.is_unfaithful_to_source = calcKnowledgeTracesIsUnfaithfulToSource(tc); });
  calcGuard(tc, knowledgeTracesFieldTypes, "is_machine_derived", () => { tc.is_machine_derived = calcKnowledgeTracesIsMachineDerived(tc); });
  calcGuard(tc, knowledgeTracesFieldTypes, "is_self_validated", () => { tc.is_self_validated = calcKnowledgeTracesIsSelfValidated(tc); });
  calcGuard(tc, knowledgeTracesFieldTypes, "has_incomplete_provenance", () => { tc.has_incomplete_provenance = calcKnowledgeTracesHasIncompleteProvenance(tc); });
  calcGuard(tc, knowledgeTracesFieldTypes, "provenance_statement", () => { tc.provenance_statement = calcKnowledgeTracesProvenanceStatement(tc); });
  calcGuard(tc, knowledgeTracesFieldTypes, "is_aspect_unsupported_by_source_kind", () => { tc.is_aspect_unsupported_by_source_kind = calcKnowledgeTracesIsAspectUnsupportedBySourceKind(tc); });
  calcGuard(tc, knowledgeTracesFieldTypes, "is_document_origin", () => { tc.is_document_origin = calcKnowledgeTracesIsDocumentOrigin(tc); });
  calcGuard(tc, knowledgeTracesFieldTypes, "is_document_trailing_practice", () => { tc.is_document_trailing_practice = calcKnowledgeTracesIsDocumentTrailingPractice(tc); });
  calcGuard(tc, knowledgeTracesFieldTypes, "prescribed_versus_enacted", () => { tc.prescribed_versus_enacted = calcKnowledgeTracesPrescribedVersusEnacted(tc); });
  // Level 2
  calcGuard(tc, knowledgeTracesFieldTypes, "is_document_start_never_validated", () => { tc.is_document_start_never_validated = calcKnowledgeTracesIsDocumentStartNeverValidated(tc); });
  calcGuard(tc, knowledgeTracesFieldTypes, "is_document_start_never_extended", () => { tc.is_document_start_never_extended = calcKnowledgeTracesIsDocumentStartNeverExtended(tc); });
  return tc;
}

/** Reads KnowledgeTraces rows from a JSON array file. */
export function loadKnowledgeTracesRows(file: string): KnowledgeTracesRow[] {
  return loadRows(file, { fields: knowledgeTracesFieldTypes }) as unknown as KnowledgeTracesRow[];
}

// =============================================================================
// MINEDFLOWEDGES TABLE
// One step-to-step hand-off reconstructed from a system event log by a process-mining run: how many cases took it, how long cases waited before the next step, and whether it is kept as observed behavior or recorded as intended logic.
// =============================================================================

/** A row in the MinedFlowEdges table. */
export interface MinedFlowEdgesRow {
  /** Stored identifier. */
  mined_flow_edge_id: string;
  /** Display name. */
  name: string | null;
  /** The mining run that reconstructed the hand-off. */
  process_mining_run: string | null;
  /** Step the cases left. */
  from_step: string | null;
  /** Step the cases entered next. */
  to_step: string | null;
  /** Cases in the log that took this hand-off. */
  observed_case_count: number | null;
  /** Median minutes between leaving FromStep and starting ToStep. */
  median_wait_minutes: number | null;
  /** Observed (kept as mined behavior) or Intended (recorded as intended process logic). */
  recorded_stance: string | null;
  /** Who decided that mined behavior should become intended logic. */
  intent_decision_by: string | null;
  /** Documented transitions with the same origin and target. */
  documented_transition_count: number | null;
  /** TRUE when cases took a hand-off the documented model does not contain. */
  is_undocumented_path: boolean | null;
  /** Documented duration of the step entered. */
  to_step_expected_minutes: number | null;
  /** TRUE when cases wait more than four times the entered step's documented duration. */
  is_bottleneck: boolean | null;
  /** TRUE when a mined hand-off is recorded as intended logic and nobody decided it should be. */
  is_mined_path_recorded_as_intent_without_decision: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const minedFlowEdgesFieldTypes: Record<string, FieldType> = {
  mined_flow_edge_id: "string",
  name: "*string",
  process_mining_run: "*string",
  from_step: "*string",
  to_step: "*string",
  observed_case_count: "*int",
  median_wait_minutes: "*int",
  recorded_stance: "*string",
  intent_decision_by: "*string",
  documented_transition_count: "*int",
  is_undocumented_path: "*bool",
  to_step_expected_minutes: "*int",
  is_bottleneck: "*bool",
  is_mined_path_recorded_as_intent_without_decision: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{FromStep}} & " -> " & {{ToStep}} */
export function calcMinedFlowEdgesName(tc: MinedFlowEdgesRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.from_step)), vS(" -> "), erbText(vStr(tc.to_step))));
}

/** Computes the IsUndocumentedPath calculated field.
 *  TRUE when cases took a hand-off the documented model does not contain.
 *  Formula: ={{DocumentedTransitionCount}} = 0 */
export function calcMinedFlowEdgesIsUndocumentedPath(tc: MinedFlowEdgesRow): boolean | null {
  return toBoolPtr(erbEq(vInt(tc.documented_transition_count), vI(0)));
}

/** Computes the IsBottleneck calculated field.
 *  TRUE when cases wait more than four times the entered step's documented duration.
 *  Formula: =AND({{ToStepExpectedMinutes}} > 0, {{MedianWaitMinutes}} > 4 * {{ToStepExpectedMinutes}}) */
export function calcMinedFlowEdgesIsBottleneck(tc: MinedFlowEdgesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbCmp(vInt(tc.to_step_expected_minutes), ">", vI(0))), erbBool3(erbCmp(erbNullif(vInt(tc.median_wait_minutes)), ">", erbMul(vI(4), vInt(tc.to_step_expected_minutes))))));
}

/** Computes the IsMinedPathRecordedAsIntentWithoutDecision calculated field.
 *  TRUE when a mined hand-off is recorded as intended logic and nobody decided it should be.
 *  Formula: =AND({{RecordedStance}} = "Intended", {{IntentDecisionBy}} = "") */
export function calcMinedFlowEdgesIsMinedPathRecordedAsIntentWithoutDecision(tc: MinedFlowEdgesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.recorded_stance)), vS("Intended"))), erbBool3(erbIsBlank(vStr(tc.intent_decision_by)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeMinedFlowEdges(tc: MinedFlowEdgesRow): MinedFlowEdgesRow {
  // Level 1
  calcGuard(tc, minedFlowEdgesFieldTypes, "name", () => { tc.name = calcMinedFlowEdgesName(tc); });
  calcGuard(tc, minedFlowEdgesFieldTypes, "is_undocumented_path", () => { tc.is_undocumented_path = calcMinedFlowEdgesIsUndocumentedPath(tc); });
  calcGuard(tc, minedFlowEdgesFieldTypes, "is_bottleneck", () => { tc.is_bottleneck = calcMinedFlowEdgesIsBottleneck(tc); });
  calcGuard(tc, minedFlowEdgesFieldTypes, "is_mined_path_recorded_as_intent_without_decision", () => { tc.is_mined_path_recorded_as_intent_without_decision = calcMinedFlowEdgesIsMinedPathRecordedAsIntentWithoutDecision(tc); });
  return tc;
}

/** Reads MinedFlowEdges rows from a JSON array file. */
export function loadMinedFlowEdgesRows(file: string): MinedFlowEdgesRow[] {
  return loadRows(file, { fields: minedFlowEdgesFieldTypes }) as unknown as MinedFlowEdgesRow[];
}

// =============================================================================
// COLLECTIONOCCASIONS TABLE
// Recurring occasions at which process knowledge is collected: retrospectives, process reviews and improvement initiatives.
// =============================================================================

/** A row in the CollectionOccasions table. */
export interface CollectionOccasionsRow {
  /** Stored identifier. */
  collection_occasion_id: string;
  /** Display name. */
  name: string | null;
  /** The occasion. */
  label: string | null;
  /** Retrospective, ProcessReview or ImprovementInitiative. */
  occasion_kind: string | null;
  /** The procedure the occasion collects knowledge about. */
  procedure: string | null;
  /** Days between occurrences. */
  cadence_days: number | null;
  /** When it was last held. */
  last_held_at: string | null;
  /** The instant the row is judged against. */
  evaluation_context: string | null;
  /** The modeled evaluation instant. */
  as_of_instant: string | null;
  /** Days since the occasion was last held. */
  days_since_held: number | null;
  /** TRUE when the occasion has not been held within its cadence. */
  is_lapsed: boolean | null;
  /** Collected materials captured at the occasion. */
  captured_material_count: number | null;
  /** TRUE when the occasion was held and nothing it surfaced was collected. */
  is_held_without_capture: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const collectionOccasionsFieldTypes: Record<string, FieldType> = {
  collection_occasion_id: "string",
  name: "*string",
  label: "*string",
  occasion_kind: "*string",
  procedure: "*string",
  cadence_days: "*int",
  last_held_at: "*string",
  evaluation_context: "*string",
  as_of_instant: "*string",
  days_since_held: "*int",
  is_lapsed: "*bool",
  captured_material_count: "*int",
  is_held_without_capture: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{OccasionKind}} & ": " & {{Label}} */
export function calcCollectionOccasionsName(tc: CollectionOccasionsRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.occasion_kind)), vS(": "), erbText(vStr(tc.label))));
}

/** Computes the DaysSinceHeld calculated field.
 *  Days since the occasion was last held.
 *  Formula: =IF({{LastHeldAt}} = "", 0, DATETIME_DIFF({{AsOfInstant}}, {{LastHeldAt}}, "days")) */
export function calcCollectionOccasionsDaysSinceHeld(tc: CollectionOccasionsRow): number | null {
  return toIntPtr(erbInteger(erbIf(erbBool3(erbIsBlank(vStr(tc.last_held_at))), () => vI(0), () => erbDatetimeDiff(vStr(tc.as_of_instant), vStr(tc.last_held_at), vS("days")))));
}

/** Computes the IsLapsed calculated field.
 *  TRUE when the occasion has not been held within its cadence.
 *  Formula: ={{DaysSinceHeld}} > {{CadenceDays}} */
export function calcCollectionOccasionsIsLapsed(tc: CollectionOccasionsRow): boolean | null {
  return toBoolPtr(erbCmp(vInt(tc.days_since_held), ">", erbNullif(vInt(tc.cadence_days))));
}

/** Computes the IsHeldWithoutCapture calculated field.
 *  TRUE when the occasion was held and nothing it surfaced was collected.
 *  Formula: =AND({{LastHeldAt}} <> "", {{CapturedMaterialCount}} = 0) */
export function calcCollectionOccasionsIsHeldWithoutCapture(tc: CollectionOccasionsRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.last_held_at))), erbBool3(erbEq(vInt(tc.captured_material_count), vI(0)))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeCollectionOccasions(tc: CollectionOccasionsRow): CollectionOccasionsRow {
  // Level 1
  calcGuard(tc, collectionOccasionsFieldTypes, "name", () => { tc.name = calcCollectionOccasionsName(tc); });
  calcGuard(tc, collectionOccasionsFieldTypes, "days_since_held", () => { tc.days_since_held = calcCollectionOccasionsDaysSinceHeld(tc); });
  calcGuard(tc, collectionOccasionsFieldTypes, "is_held_without_capture", () => { tc.is_held_without_capture = calcCollectionOccasionsIsHeldWithoutCapture(tc); });
  // Level 2
  calcGuard(tc, collectionOccasionsFieldTypes, "is_lapsed", () => { tc.is_lapsed = calcCollectionOccasionsIsLapsed(tc); });
  return tc;
}

