// =============================================================================
// STAKEHOLDERPERSPECTIVES TABLE
// One stakeholder's view of how a step should be performed, kept with the collected material it comes from and the perspective it conflicts with, rather than merged into a single agreed version.
// =============================================================================

/** A row in the StakeholderPerspectives table. */
export interface StakeholderPerspectivesRow {
  /** Stored identifier. */
  stakeholder_perspective_id: string;
  /** Display name. */
  name: string | null;
  /** The process model the view is about. */
  procedure_version: string | null;
  /** The step the view is about. */
  step: string | null;
  /** The role whose view this is. */
  holder_role: string | null;
  /** The view, paraphrased. */
  position: string | null;
  /** The collected material the view comes from. */
  source_material: string | null;
  /** The perspective this one conflicts with. */
  conflicts_with_perspective: string | null;
  /** Retained (kept alongside the other views) or OverriddenByConsensus. */
  disposition: string | null;
  /** Kind of material the view comes from. */
  source_material_kind: string | null;
  /** Perspectives that name this one as their conflict. */
  conflict_partner_count: number | null;
  /** TRUE when the perspective conflicts with another in either direction. */
  is_in_conflict: boolean | null;
  /** TRUE when a conflicting view was overridden into one version or kept without the source it comes from. */
  is_dissenting_view_not_kept_with_source: boolean | null;
  /** Semantic type IRI. */
  semantic_type_iri: string | null;
  _erb_errors?: Record<string, string>;
}

const stakeholderPerspectivesFieldTypes: Record<string, FieldType> = {
  stakeholder_perspective_id: "string",
  name: "*string",
  procedure_version: "*string",
  step: "*string",
  holder_role: "*string",
  position: "*string",
  source_material: "*string",
  conflicts_with_perspective: "*string",
  disposition: "*string",
  source_material_kind: "*string",
  conflict_partner_count: "*int",
  is_in_conflict: "*bool",
  is_dissenting_view_not_kept_with_source: "*bool",
  semantic_type_iri: "*string",
};

/** Computes the Name calculated field.
 *  Display name.
 *  Formula: ={{HolderRole}} & " on " & {{Step}} */
export function calcStakeholderPerspectivesName(tc: StakeholderPerspectivesRow): string | null {
  return toStringPtr(erbConcat(erbText(vStr(tc.holder_role)), vS(" on "), erbText(vStr(tc.step))));
}

/** Computes the IsInConflict calculated field.
 *  TRUE when the perspective conflicts with another in either direction.
 *  Formula: =OR({{ConflictsWithPerspective}} <> "", {{ConflictPartnerCount}} > 0) */
export function calcStakeholderPerspectivesIsInConflict(tc: StakeholderPerspectivesRow): boolean | null {
  return toBoolPtr(erbOr(erbBool3(erbIsNotBlank(vStr(tc.conflicts_with_perspective))), erbBool3(erbCmp(vInt(tc.conflict_partner_count), ">", vI(0)))));
}

/** Computes the IsDissentingViewNotKeptWithSource calculated field.
 *  TRUE when a conflicting view was overridden into one version or kept without the source it comes from.
 *  Formula: =AND({{IsInConflict}}, OR({{Disposition}} = "OverriddenByConsensus", {{SourceMaterial}} = "")) */
export function calcStakeholderPerspectivesIsDissentingViewNotKeptWithSource(tc: StakeholderPerspectivesRow): boolean | null {
  return toBoolPtr(erbAnd(erbBool3(vBool(tc.is_in_conflict)), erbBool3(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.disposition)), vS("OverriddenByConsensus"))), erbBool3(erbIsBlank(vStr(tc.source_material)))))));
}

/** Computes every calculated field of the row in dependency order. */
export function computeStakeholderPerspectives(tc: StakeholderPerspectivesRow): StakeholderPerspectivesRow {
  // Level 1
  calcGuard(tc, stakeholderPerspectivesFieldTypes, "name", () => { tc.name = calcStakeholderPerspectivesName(tc); });
  calcGuard(tc, stakeholderPerspectivesFieldTypes, "is_in_conflict", () => { tc.is_in_conflict = calcStakeholderPerspectivesIsInConflict(tc); });
  // Level 2
  calcGuard(tc, stakeholderPerspectivesFieldTypes, "is_dissenting_view_not_kept_with_source", () => { tc.is_dissenting_view_not_kept_with_source = calcStakeholderPerspectivesIsDissentingViewNotKeptWithSource(tc); });
  return tc;
}

/** Reads StakeholderPerspectives rows from a JSON array file. */
export function loadStakeholderPerspectivesRows(file: string): StakeholderPerspectivesRow[] {
  return loadRows(file, { fields: stakeholderPerspectivesFieldTypes }) as unknown as StakeholderPerspectivesRow[];
}

